window.GS_NPC=[{"id":0,"name":"Aetherion Hvězdný Tkadlec","title":"Polobožský strážce osudu","is_boss":true,"story":"„Smrtelníče... odvážil ses vystoupit až sem, kde se tká osud světa.\nJá jsem Aetherion, syn Nebes a Strážce Osudu.\nVlákna osudu se trhají. Temnota z podzemí a chamtivost povrchu hrozí roztrhat rovnováhu Grumpstone.\nPotřebuji hrdinu, který shromáždí Tři Zlomené Hvězdy – tři prastaré artefakty roztroušené po světě.\nPouze jejich spojením můžu znovu utkat osud a odvrátit zkázu.\nPřijmeš tento úkol, smrtelníče? Nebo se obrátíš a utečeš před osudem?“","choices":{"boj":{"mode":"dice","success":"Ze strážcova doupěte odnášíš první Zlomenou Hvězdu. Aetherion se poprvé usměje.","fail":"Strážce tě odhodil jako hadrovou panenku. Hvězda zůstala v jeho drápech.","orig":"A","text":"Vydej se do nejnebezpečnějších míst světa (ledový palác, hlubiny, orkské území) a násilím si vezmi jednu ze Zlomených Hvězd od jejich mocných strážců."},"charisma":{"mode":"choice","options":[{"label":"Promluvit ke starému drakovi o jeho slávě","outcome":"Drak polichocen pookřeje a svěří ti Hvězdu „pro dobro světa“.","result":"good"},{"label":"Nabídnout bohům oběť ze svého měšce","outcome":"Zapomenutí bohové zlato shrábnou… a Hvězdu si nechají.","result":"bad"}],"orig":"B","text":"Přesvědč strážce jednotlivých Hvězd (staré draky, zapomenuté bohy), aby ti je dobrovolně svěřili."},"magie":{"mode":"dice","success":"Hádanky rozluštěny, rituál dokončen – Hvězda září ve tvé dlani bez jediné kapky krve.","fail":"Rituál se zvrtl a magický výboj ti spálil obočí i kus kůže.","orig":"C","text":"Vyřeš složité prastaré hádanky, rituály a morální dilemata, abys získal Hvězdy chytře a s minimálním ničením."}},"image":"assets/npc/n000.webp","source_file":"grok_image_1777242751892.jpg"},{"id":1,"name":"Auralis Plamenorodý","title":"Polobožský Fénix","is_boss":true,"story":"(Hlas zní jako praskající oheň a vzdálený zpěv)\n„Smrtelníče... vidím tě skrz plameny času.\nJá jsem Auralis, ten, který umírá a rodí se znovu.\nTentokrát... jsem uvězněn v této podobě příliš dlouho.\nNěco brání mému dalšímu znovuzrození.\nPomoz mi shořet naposledy... abych se mohl znovu narodit čistý.“","choices":{"boj":{"mode":"choice","options":[{"label":"Postavit se lovcům na otevřené pláni","outcome":"Lovce rozeženeš, ale jeden šíp tě škrábne. Auralis ti děkuje žhavou slzou.","result":"neutral"},{"label":"Nastražit na lovce past v kaňonu","outcome":"Lovci padnou do pasti a Auralis tě odmění pírkem, které hřeje jako zlato.","result":"good"}],"orig":"A","text":"Ochraň ho před lovci, kteří chtějí jeho peří."},"charisma":{"mode":"dice","success":"Najdeš laskavou bylinkářku a Auralis jí svěří jiskru svého plamene.","fail":"Tvá „hodná osoba“ byla chamtivý lichvář. Fénix tě ožehl hněvem.","karma":1,"orig":"B","text":"Pomoz mu najít hodnou osobu, které předá část svého plamene."},"magie":{"mode":"dice","success":"Popel se rozzáří a z plamenů se vznese omlazený Fénix. Svět je o kousek jasnější.","fail":"Rituál jsi pokazil a Auralis vzplál příliš brzy – a ty s ním.","orig":"C","text":"Proveď starobylý rituál, který mu umožní znovu zemřít a znovu se zrodit."}},"image":"assets/npc/n001.webp","source_file":"grok_image_1777279676011.jpg"},{"id":2,"name":"Gorthak Mlhožrout","title":"Prastarý horský titán","is_boss":true,"story":"(Gorthak se zachechtá, až se země zatřese, mlha se kolem něj víří)\n„Hrrr... malí červi. Už celá staletí spím v horách.\nTeď jsem se probudil... a mám hlad.\nTa vesnice dole... taková slabá, křehká, plná křiku a čerstvého masa.\nPůjdeš tam za mě.\nPřivedeš mi první hostinu. Nebo jim řekneš, že Gorthak Mlhožrout přichází... a ať se připraví na večeři.“","choices":{"boj":{"mode":"choice","options":[{"label":"Rozbít bránu vesnice a nahnat obyvatele titánovi","outcome":"Gorthak se nažere a hodí ti pár zlaťáků z kapes snědených. Karma pláče.","result":"good","karma":-1},{"label":"Předstírat útok a vesničany potají varovat","outcome":"Vesnice uteče, Gorthak zuří a dupne těsně vedle tebe.","result":"bad","karma":1}],"orig":"A","text":"Pomoz Gorthakovi zaútočit na vesnici – rozbij bránu, zastraš obyvatele a přiveď mu zajatce (nebo ho ochraňuj, zatímco on žere)."},"charisma":{"mode":"dice","success":"Vesničané souhlasí s „daní“ v dobytku a Gorthak spokojeně odchrápe zpátky do hor.","fail":"Vesničané tě vyhnali vidlemi a titán se rozzlobil, že nic nedostal.","orig":"B","text":"Přesvědč vesničany, aby mu dobrovolně dávali „daň“ (lidi nebo dobytek) výměnou za to, že je nesežere všechny najednou."},"magie":{"mode":"dice","success":"Našel jsi runu i slabé místo na krku. Gorthak padá na sto let do mlhy a spánku.","fail":"Gorthak tvou lest prokoukl a jen tak „mimochodem“ do tebe šťouchl kamenem.","karma":1,"orig":"C","text":"Zjisti, jak Gorthaka oslabit nebo oklamat (starobylá runa, slabé místo na krku, nebo ho nalákat na ještě větší kořist jinde)."}},"image":"assets/npc/n002.webp","source_file":"grok_image_1777243437965.jpg"},{"id":3,"name":"Kragorax Kamenný Sen","title":"Živoucí Golem z Válečných Soch","is_boss":true,"story":"(Hluboký, dunivý hlas, který zní jako padající skály)\n„Já jsem Kragorax.\nKdysi jsme stáli jako hrdinové nad tímto polem.\nTeď jsme jen sutiny a vzpomínky.\nNěco nás probudilo z dlouhého spánku. Něco temného... špatného.\nNemůžeme bojovat. Nemůžeme odejít.\nJsme uvězněni v kameni.\nPomoz nám pochopit, proč jsme vstali... nebo nás navždy znič. Ať už to skončí.“","choices":{"boj":{"mode":"dice","success":"Temnou entitu jsi vyhnal z poutního kamene. Golemové vydechnou prach a usínají.","fail":"Entita tě zaplavila stíny, zatímco golemové bezmocně přihlíželi.","karma":1,"orig":"A","text":"Najdi a znič temnou entitu, která golemům brání znovu usnout."},"charisma":{"mode":"choice","options":[{"label":"Vyprávět golemům o hrdinských písních, které o nich lidé zpívají","outcome":"Kamenné tváře změknou. Kragorax usíná s úsměvem.","result":"good"},{"label":"Říct jim tvrdou pravdu, že na ně všichni zapomněli","outcome":"Golemové se rozpláčou štěrkem a jeden ti v žalu šlápne na nohu.","result":"bad"}],"orig":"B","text":"Pomoz golemům smířit se s jejich minulostí a najít klid."},"magie":{"mode":"dice","success":"Zjistil jsi, že je probudila prokletá korouhev. Spálil jsi ji a golemové tiše usnuli.","fail":"Rituál jsi popletl a golemové začali bušit do všeho kolem – i do tebe.","orig":"C","text":"Zjisti pravý důvod, proč se probudili, a proveď rituál, který je vrátí do věčného spánku."}},"image":"assets/npc/n003.webp","source_file":"grok_image_1777279860970.jpg"},{"id":4,"name":"Lirael, Matka Všech Kořenů","title":"Prastará Dryáda Polobožka","is_boss":true,"story":"(Hlas zní jako šumění listí a vzdálený zpěv ptáků)\n„Přišel jsi, smrtelníče... cítím, jak ti bije srdce v rytmu mého lesa.\nJá jsem Lirael, Matka Všech Kořenů, dcera samotné přírody.\nLes umírá. Něco z hlubin země otravuje mé kořeny a zabíjí mé děti.\nJsi ochoten mi pomoct? Nebo jsi přišel jen krást mou moc jako všichni před tebou?“","choices":{"boj":{"mode":"dice","success":"V jeskyni pod kořeny jsi rozbil hnijící krystal. Les se nadechne.","fail":"Bestie z hlubin tě zahnala ven, pokrytého jedovatým slizem.","karma":1,"orig":"A","text":"Vydáš se do temných jeskyní pod kořeny a zničíš zdroj otravy (nějakou temnou bestii nebo artefakt).","quest":{"targets":["forest"],"goal":"Znič zdroj otravy v jeskyních pod kořeny lesa","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Požádat o pomoc moudrou starou sovu","outcome":"Sova svolá celý les. Lirael ti věnuje požehnání a hrst zlatých žaludů.","result":"good"},{"label":"Nabídnout zvířatům jídlo ze svých zásob","outcome":"Veverky jídlo sežerou a zmizí. Les mlčí.","result":"neutral"}],"orig":"B","text":"Pomůžeš Lirael získat zpět ztracenou sílu tím, že získáš důvěru a pomoc ostatních lesních bytostí."},"magie":{"mode":"choice","options":[{"label":"Hledat příčinu u otráveného potoka","outcome":"Najdeš zdroj jedu a s Lirael provedete očistu. Kořeny se zelenají.","result":"good"},{"label":"Hledat příčinu ve starých dryádích svitcích","outcome":"Svitky jsou psané jazykem stromů. Nic nezjistíš a bolí tě hlava.","result":"neutral"}],"orig":"C","text":"Zjistíš pravou příčinu, proč les umírá, a provedeš starobylý očistný rituál, který zná jen ona."}},"image":"assets/npc/n004.webp","source_file":"grok_image_1777280123617.jpg"},{"id":5,"name":"Lord Baelgor Kozlí","title":"Temný lord s kozlí hlavou","is_boss":true,"story":"„Moc je sladká... a lidské duše jsou ještě sladší.“","choices":{"boj":{"mode":"choice","options":[{"label":"Přivést mu opilého lupiče z krčmy","outcome":"Baelgor se ušklíbne, „chutná trochu kysele“, ale zaplatí.","result":"good","karma":-1},{"label":"Vrátit se s prázdnou a lhát, že vesnice byla prázdná","outcome":"Baelgor lež vycítí a jeho kopyto tě nakopne do žeber.","result":"bad"}],"orig":"A","text":"„Přiveď mi živého zajatce z vesnice – chci si ho vychutnat sám.“","quest":{"targets":["village"],"goal":"Přiveď lordu Baelgorovi zajatce z vesnice","gp":false}},"charisma":{"mode":"dice","success":"Kněžka podlehla tvým slovům. Baelgor je spokojen, ale tvá duše ztmavla.","fail":"Kněžka tě prohlédla a polila svěcenou vodou. Pálí to.","karma":-1,"orig":"B","text":"„Přesvědč mladou kněžku, ať mi dobrovolně daruje svou čistotu.“"},"magie":{"mode":"choice","options":[{"label":"Pečeť opravdu aktivovat","outcome":"Brána se pootevře a démoni ti „z vděčnosti“ hodí měšec. Svět se otřese.","result":"good","karma":-1},{"label":"Pečeť „omylem“ upustit do propasti","outcome":"Baelgor ztratí hračku a zuří. Karma ti ale děkuje.","result":"bad","karma":1}],"orig":"C","text":"„Našel jsem starou pečeť, která otevírá bránu do říše démonů. Pomoz mi ji aktivovat.“"}},"image":"assets/npc/n005.webp","source_file":"grok_image_1777027341997.jpg"},{"id":6,"name":"Nyxara, Královna Šepotu","title":"Temná polobožská entita","is_boss":true,"story":"(Nyxara se vznáší nad rozbitým oltářem, její hlas je sladký, ale zároveň děsivě mnohovrstevný)\n„Konečně... někdo s dostatečně černým srdcem, aby sem přišel.“\n„Já jsem Nyxara, dcera První Tmy a Královna Šepotu.\nTento svět je příliš hlučný. Příliš plný světla a naděje.\nChci ho umlčet.\nPřines mi Sedm Žijících Hvězd — duše sedmi nevinných, kteří ještě nikdy nezabili.\nAž je obětuješ na mém oltáři, otevřu Bránu věčné noci.\nA ty... ty budeš stát po mé pravici, až se vše ponoří do ticha.“","choices":{"boj":{"mode":"choice","options":[{"label":"Odmítnout a utéct od oltáře","outcome":"Nyxara se směje do tmy, ale nechá tě jít. Tvé srdce zůstalo čisté.","result":"neutral","karma":1},{"label":"Předstírat souhlas a zmizet s její zálohou","outcome":"Uteče ti to se zlatem v kapse, ale šepot tě bude pronásledovat ve snech.","result":"bad"}],"orig":"A","text":"Najdi a zabij sedm nevinných duší (děti, kněží, léčitelé) a dones jejich esence Nyxaře."},"charisma":{"mode":"dice","success":"Nevinní přišli k oltáři… Nyxara tě odmění temným zlatem. Tvá karma těžce klesá.","fail":"Nevinní tvou lež prokoukli a stráže tě vypráskaly z města.","karma":-1,"orig":"B","text":"Přesvědč (nebo nalákej) nevinné, aby sami přišli k oltáři („zachráníš je před horšími věcmi“)."},"magie":{"mode":"dice","success":"Rituál jsi zvrátil – místo duší Nyxara spolkla vlastní stín a zmizela v oltáři.","fail":"Temná magie se obrátila proti tobě. Stíny ti vysály sílu.","karma":1,"orig":"C","text":"Proveď temný rituál, který umožní Nyxaře sežrat duše na dálku, aniž bys musel zabíjet vlastníma rukama."}},"image":"assets/npc/n006.webp","source_file":"grok_image_1777245133881.jpg"},{"id":7,"name":"Tortulon Prastarý","title":"Strážce hlubin a želví titán","is_boss":true,"story":"(Hlas Tortulona duní jako vzdálené zemětřesení, pomalý a hluboký)\n„Smrtelníče... odvážil ses přijít až ke mně.\nJá jsem Tortulon Prastarý, strážce rovnováhy oceánu.\nTisíce let jsem chránil Srdce Oceánu – krystal, který udržuje život v moři.\nNyní byl ukraden chamtivými lidskými piráty, kteří ho chtějí použít pro sebe – a moře umírá.\nPomůžeš mi ho vrátit zpět? Není to úkol pro slabé srdce.“","choices":{"boj":{"mode":"dice","success":"Probil ses na pirátskou loď a vyrval Srdce Oceánu z truhly kapitána.","fail":"Piráti tě hodili přes palubu. Domů jsi doplaval s mořskou řasou ve vlasech.","karma":1,"orig":"A","text":"Vydej se na nepřátelskou loď / pevnost na pobřeží, kde Srdce drží, a probij se skrz stráže a magické ochrany."},"charisma":{"mode":"choice","options":[{"label":"Vyhrožovat kapitánovi hněvem želvího titána","outcome":"Kapitán zbledne a krystal vrátí. Tortulon spokojeně zamručí.","result":"good"},{"label":"Nabídnout kapitánovi podíl na výkupném","outcome":"Kapitán si vezme zálohu a odpluje i s krystalem. Ups.","result":"bad"}],"orig":"B","text":"Přesvědč chamtivé šlechtice nebo kapitána, kteří krystal ukradli, aby ho dobrovolně vrátili (nebo je donuť pocítit důsledky jejich chamtivosti)."},"magie":{"mode":"dice","success":"Hádanky vyřešeny, klíč získán a Srdce vráceno bez krveprolití.","fail":"Ostrůvek se pod tebou potopil a ty jsi strávil noc na kamenné želví hlavě.","orig":"C","text":"Vyřeš starobylé hádanky a rituály na ostrůvku Tortulona, abys získal klíč k Srdci Oceánu, a vymysli chytrý plán, jak ho získat bez zbytečného krveprolití."}},"image":"assets/npc/n007.webp","source_file":"grok_image_1777206548786.jpg"},{"id":8,"name":"Valthorax Šedokřídlý","title":"Prastarý modrošedý drak","is_boss":true,"story":"(Valthorax pomalu zvedne hlavu, jeho hlas je hluboký, dunivý a plný starobylé arogance)\n„Hmmm... další malý červ, který si dovolil vstoupit do mé pokladnice.\nJá jsem Valthorax Šedokřídlý, Strážce Hořící Hromady.\nTisíc let sbírám to, co mi patří.\nA ty... co ty mi přinášíš? Zlato? Moc? Nebo jen své křehké tělo, které si mohu dát k večeři?“","choices":{"boj":{"mode":"choice","options":[{"label":"Ulovit drakovi obřího mořského hada","outcome":"Drak se nacpe, říhne ohněm a hodí ti hrst mincí z hromady.","result":"good"},{"label":"Přinést mu stádo ovcí z vesnice","outcome":"Valthorax se urazí, že je to „předkrm“, a ožehne ti záda.","result":"bad"}],"orig":"A","text":"Drak je hladový. Přines mu velké množství masa (nebo pomoz mu ulovit nějakou obrovskou nestvůru), jinak si vezme tebe."},"charisma":{"mode":"dice","success":"Tvůj příběh draka tak pobavil, že ti dal zlatý pohár „za zábavu“.","fail":"Drak zívl a zahnal tě plamenem. Prý „nuda“.","orig":"B","text":"Přesvědč draka, aby tě nechal odejít (nebo ho dokonce přiměj, aby ti dal část pokladu za „zajímavý příběh“)."},"magie":{"mode":"dice","success":"Hádanka vyřešena – Valthorax je zaneprázdněn a ty odcházíš s plnými kapsami.","fail":"Drak tvou lest prohlédl a málem tě přidal k pokladu.","orig":"C","text":"Pomoz Valthoraxovi vyřešit starobylou hádanku nebo rituál, který mu umožní získat ještě větší poklad (nebo najdi způsob, jak ho oslabit a ukrást část bohatství)."}},"image":"assets/npc/n008.webp","source_file":"grok_image_1777245696662.jpg"},{"id":9,"name":"Vesperon Měsíční Had","title":"Krutý upír-mág","is_boss":true,"story":"(Vesperon se pomalu otočí, jeho hadí oči se zalesknou a úsměv se roztáhne ještě víc)\n„...no konečně. Už jsem se začínal nudit.\nJsem Vesperon. Polovina upír, polovina mág... a celý hladový.\nTisíc let jsem čekal, až se někdo odváží přijít až sem.\nPřinesl jsi mi něco na zub? Nebo... mám si tě nechat na dezert?“","choices":{"boj":{"mode":"choice","options":[{"label":"Vést upíra k vesnici","outcome":"Vesperon se nasytí a odmění tě zlatem. Hory budou dlouho plakat.","result":"good","karma":-1},{"label":"Svést ho na falešnou stopu do mlhy","outcome":"Vesperon zabloudí a vrátí se rozzuřený – kousne tě do ramene.","result":"bad","karma":1}],"orig":"A","text":"Pomoz Vesperonovi zaútočit na nedalekou horskou vesnici – má hlad a chce „čerstvou zásilku“.","quest":{"targets":["snezna_lhota","kamenita_ves"],"goal":"Přepadni s Vesperonem horskou vesnici","gp":false}},"charisma":{"mode":"dice","success":"Přesvědčil jsi ho, že karavana je „větší hostina“ – a varoval jsi karavanu včas.","fail":"Vesperon ti nevěří a „ochutná“ tě na zkoušku.","karma":1,"orig":"B","text":"Přesvědč ho, aby si vybral jinou oběť (nebo ho nalákej na ještě větší kořist – např. celý karavan)."},"magie":{"mode":"choice","options":[{"label":"Rituál zmařit tajným protikouzlem","outcome":"Rituál se zhroutí a Vesperon slábne. Uteče do stínů, ty máš jeho prsten.","result":"good","karma":1},{"label":"Rituál skutečně dokončit","outcome":"Vesperon zesílí a zaplatí ti… ale tvé svědomí krvácí.","result":"neutral","karma":-1}],"orig":"C","text":"Pomoz mu dokončit temný rituál, při kterém potřebuje srdce tří „čistých duší“ (děti, kněz, panna), aby získal ještě větší moc."}},"image":"assets/npc/n009.webp","source_file":"grok_image_1777243800972.jpg"},{"id":10,"name":"Xal'Tharion","title":"Exotický polobůh mnoha rukou","is_boss":true,"story":"(Obě hlavy mluví střídavě - nejprve hluboký lidský hlas, pak zvířecí zavrčení)\nLidská hlava: „Smrtelníče... odvážil ses vystoupit až sem, kde se láme realita.“\nPanterí hlava: „...my voníme tvůj strach.“\nLidská hlava: „Jsem Xal'Tharion, Ten, Který Drží Nebe. Kdysi jsem hlídal bránu mezi světy. Teď je brána prasklá a já nemohu odejít z tohoto místa.“\nPanterí hlava: „Přines nám Srdce Nebeského Oka - artefakt, který nám ukradli z hlubin. Udělej to... a my ti dáme sílu, o jaké se ti ani nesnilo.“","choices":{"boj":{"mode":"dice","success":"V hlubinách reality jsi získal Srdce Nebeského Oka. Obě hlavy jásají.","fail":"Strážci prasklé reality tě vyplivli zpět – trochu poskládaného jinak.","orig":"A","text":"Vydej se do hlubin prasklé reality a v boji si vezmi Srdce Nebeského Oka od jeho strážců."},"charisma":{"mode":"choice","options":[{"label":"Požádat ho, ať tě naučí ovládat levitující kameny","outcome":"Naučíš se nadnést malý kamínek. Panterí hlava se uchechtne, ale dá ti odměnu.","result":"good"},{"label":"Smlouvat o lehčí úkol","outcome":"Lidská hlava souhlasí, panterí ne. Kousne tě do ruky.","result":"bad"}],"orig":"B","text":"Přesvědč Xal'Thariona, aby ti dal úkol jiného druhu (nebo ho přiměj, aby tě naučil ovládat levitující kameny)."},"magie":{"mode":"dice","success":"Bránu jsi zacelil runami a Xal'Tharion poprvé po věcích odchází domů.","fail":"Brána se rozšířila a vcucla ti batoh. Ty ses sotva udržel.","orig":"C","text":"Zjisti, jak opravit prasklou bránu mezi světy a osvobodit ho z tohoto vznášejícího se vězení."}},"image":"assets/npc/n010.webp","source_file":"grok_image_1777279992319.jpg"},{"id":11,"name":"Aerithia","title":"Stříbrná víla-královna větrů","is_boss":false,"story":"„Smrtelníče... vítr mi šeptal o tvém příchodu.\nTemnota se šíří z hor. Pomoz mi obnovit Větrné Stráže, než bouře pohltí celý svět.“","choices":{"boj":{"mode":"dice","success":"Temní tvorové jsou rozprášeni a Větrné Stráže znovu zpívají.","fail":"Temní tvorové tě zasypali kamením a vítr ti vyfoukl klobouk i odvahu.","karma":1,"orig":"A","text":"Znič temné tvory, které ničí Větrné Stráže."},"charisma":{"mode":"choice","options":[{"label":"Oslovit víly písní","outcome":"Víly se přidají a Aerithia tě políbí na čelo větrem.","result":"good"},{"label":"Oslovit elementály vážnou řečí o povinnosti","outcome":"Elementálové se nudí a jeden tě odfoukne do bodláčí.","result":"bad"}],"orig":"B","text":"Přesvědč ostatní víly a elementály, aby se spojili."},"magie":{"mode":"dice","success":"Starý rituál větru se rozezněl a Stráže se probudily.","fail":"Rituál tě zvedl do vzduchu a pak pustil. Z velké výšky.","orig":"C","text":"Vyřeš starobylé rituály, jak obnovit ochranu větru."}},"image":"assets/npc/n011.webp","source_file":"grok_image_1777246948111.jpg"},{"id":12,"name":"Azura Smrtonoška","title":"Temná lesní entita","is_boss":false,"story":"(Azura se vynoří z kouře u studny, její hlas zní jako šepot větru mezi větvemi) „Smrt přichází pomalu... ale já ji mohu urychlit. Tato studna živí celou vesnici. Znečistíme ji mým rituálem. Ať se jejich voda stane jedem... ať konečně pocítí, co znamená temnota lesa.“","choices":{"boj":{"mode":"choice","options":[{"label":"Postavit se Azuře u studny","outcome":"Azura před ocelí ucukne a zmizí v kouři. Vesnice má čistou vodu.","result":"good","karma":1},{"label":"Pomoci jí dokončit rituál","outcome":"Studna zčerná, Azura tě odmění temným zlatem. Vesnice bude trpět.","result":"neutral","karma":-1}],"orig":"A","text":"Ochraň studnu před Azurou (nebo jí naopak pomoz rituál dokončit násilím)."},"charisma":{"mode":"dice","success":"Azura se nechala nalákat k jiné studni – opuštěné a vyschlé. Vesnice je v bezpečí.","fail":"Azura se jen usmála a pošeptala ti kletbu do ucha. Je ti zle.","karma":1,"orig":"B","text":"Přesvědč Azuru, aby si vybrala jinou studnu, nebo ji nalákej na větší oběť místo vesnice."},"magie":{"mode":"dice","success":"Protikouzlo zabralo a rituál se rozpadl na mlhu.","fail":"Protikouzlo se zvrtlo a voda ti vyšplíchla do obličeje – trochu jedovatá.","orig":"C","text":"Zjisti, jak rituál přerušit (nebo naopak dokončit) – musíš najít a použít protikouzlo nebo obětovat něco silnějšího."}},"image":"assets/npc/n012.webp","source_file":"grok_image_1777118916703.jpg"},{"id":13,"name":"Banda Černého Havrana","title":"Nebezpečná lupičská tlupa","is_boss":false,"story":"Ravenna se nakloní přes stůl, její dekolt téměř přetéká: „Tak co, cizince? Zítra ráno vyrážíme na bohatou karavanu ze Zlatobřehu. Chceš se přidat? Podělíme se... nebo ti podřízneme krk hned teď. Rozhodni se rychle.“","choices":{"boj":{"mode":"choice","options":[{"label":"Přidat se k přepadení karavany","outcome":"Banda je bohatá a ty taky. Jen svědomí trochu svědí.","result":"good","karma":-1},{"label":"Zradit bandu a bránit karavanu","outcome":"Karavana je zachráněna, ale Ravennin nůž tě škrábl.","result":"neutral","karma":1}],"orig":"A","text":"Přidej se k přepadení karavany a bojuj po boku bandy (nebo je zraď a braň karavanu)."},"charisma":{"mode":"dice","success":"Ravenna ti dala dvojitý podíl – prý „za ten pohled“.","fail":"Ravenna se urazila a podřízla ti… aspoň měšec.","orig":"B","text":"Přesvědč Ravennu, ať ti dá větší podíl, nebo ji přemluv, ať celou akci zruší (nebo tě vezme jako milence do bandy)."},"magie":{"mode":"choice","options":[{"label":"Zjistit vše o karavaně a varovat ji","outcome":"Strážní kapitán ti z vděčnosti zaplatí. Banda nic netuší.","result":"good","karma":1},{"label":"Zjistit vše a prodat plán bandě","outcome":"Banda zaplatí, ale karavana nečekaně posílila stráže. Bitka, rány, útěk.","result":"bad","karma":-1}],"orig":"C","text":"Zjisti podrobnosti o karavaně (kolik stráží, co převáží, kdy přesně vyjíždí) a buď pomoz bandě s dokonalým plánem, nebo varuj karavanu včas."}},"image":"assets/npc/n013.webp","source_file":"grok_image_1777111989468.jpg"},{"id":14,"name":"Bivojec Tvrdohlav","title":"Trpasličí válečník","is_boss":false,"story":"„Co chceš, dlouhán? Já Bivojec! Když něco rozbiju, tak to už zůstane rozbitý. A teď mi řekni, co máš na práci!“","choices":{"boj":{"mode":"dice","success":"BUM! Brána je na třísky a Bivojec ti nadšeně buší do zad.","fail":"Brána vydržela, tvá ramena ne.","orig":"A","text":"Pomoz mu rozbít nepřátelskou bránu nebo obléhací stroj."},"charisma":{"mode":"choice","options":[{"label":"Vyzvat Bivojce na pití","outcome":"Bivojec prohraje, přizná ti úctu a odtahá ti všechny klády.","result":"good"},{"label":"Zalichotit mu, jaký je silák","outcome":"„Já vím, že jsem silák!“ Bivojec odejde pochlubit se jinam.","result":"neutral"}],"orig":"B","text":"Přesvědč ho, ať ti pomůže s těžkou fyzickou prací."},"magie":{"mode":"dice","success":"Stroj znovu bafá párou a kladivo má zpět svou ztracenou hlavici.","fail":"Stroj vybuchl a obočí ti zůstalo jen jedno.","orig":"C","text":"Pomoz mu opravit starý trpasličí stroj (nebo najít ztracenou část jeho legendárního kladiva)."}},"image":"assets/npc/n014.webp","source_file":"grok_image_1777111024955.jpg"},{"id":15,"name":"Blepta Zadní","title":"Uražený trpasličí milenec","is_boss":false,"story":"„Dalirian se mi chce omluvit, jo? Ten nafoukaný elfí cvok! Řekl, že moje zbroj vypadá „rustikálně“! Já mu ukážu rustikálně! Buď mi pomůžeš, ať se ten sviňák pořádně plazí... nebo mu pomůžu já — kladivem!“","choices":{"boj":{"mode":"choice","options":[{"label":"Zastoupit Bleptovi cestu","outcome":"Blepta se o tebe rozbije jako o skálu, vychladne a pozve tě na pivo.","result":"good"},{"label":"Nechat ho jít","outcome":"Blepta Daliriana „upraví“. Celé město se směje a tobě nikdo nezaplatí.","result":"bad"}],"orig":"A","text":"Blepta se rozčílí natolik, že chce Daliriana „trochu upravit“ kladivem. Uklidni situaci (nebo ho pusť)."},"charisma":{"mode":"dice","success":"Blepta odpustil. Dalirian pláče dojetím a oba ti děkují.","fail":"Blepta se urazil i na tebe a hodil po tobě helmu.","orig":"B","text":"Přesvědč Bleptu, aby Dalirianovi odpustil (nebo naopak pomoz Bleptovi vymyslet pomstu)."},"magie":{"mode":"choice","options":[{"label":"Navrhnout květinovou zbroj na bál","outcome":"Dalirian přijme, Blepta řve smíchy. Oba ti platí.","result":"good"},{"label":"Navrhnout jim, ať se poperou","outcome":"Poperou se. A pak oba zmlátí tebe.","result":"bad"}],"orig":"C","text":"Zjisti, co Bleptu skutečně urazilo (a pomoz najít kompromis, který uspokojí oba – např. Dalirian musí nosit trpasličí květinovou zbroj na bál)."}},"image":"assets/npc/n015.webp","source_file":"grok_image_1777194990078.jpg"},{"id":16,"name":"Borislav Kamenný","title":"Zlomený kameník a bývalý hrdina","is_boss":false,"story":"(Borislav sedí na kameni, ruce má složené na klíně, a dívá se do vody pod mostem)\n„Ten most... já ho stavěl před deseti lety. Nejlepší dílo mého života.“\nA pak přišla velká voda... most se zřítil a pod ním bylo 27 lidí. Včetně mé ženy a bratra.\nVšichni říkají, že to nebyla moje vina. Že to byla příroda.\nAle já vím, že jsem to měl udělat pevnější.\n„Teď tu každou noc sedím... a prosím, abys mi pomohl najít aspoň jejich ostatky, abych je mohl pořádně pochovat.\nNebo... abys mi pomohl sám sebe odpustit. Protože já to nedokážu.“","choices":{"boj":{"mode":"dice","success":"V troskách pod mostem jsi našel ostatky. Borislav je konečně může pochovat.","fail":"Vodní stvůry tě stáhly pod hladinu. Vyplaval jsi, ale s prázdnýma rukama.","karma":1,"orig":"A","text":"Sestup do nebezpečných zřícenin pod mostem a vypořádej se s vodními stvůrami a troskami, abys dostal ostatky."},"charisma":{"mode":"choice","options":[{"label":"Přivést svědky, aby mu řekli pravdu","outcome":"Přeživší mu odpustí. Borislav se poprvé po letech usměje.","result":"good","karma":1},{"label":"Opít Borislava v krčmě, ať zapomene","outcome":"Ráno je mu hůř než předtím a ty platíš útratu.","result":"bad"}],"orig":"B","text":"Pomoz Borislavovi najít přeživší svědky a přesvědč je, aby mu řekli, že to opravdu není výhradně jeho vina."},"magie":{"mode":"dice","success":"Zjistil jsi, že most podkopal pašerácký tunel. Nebyla to jeho vina!","fail":"Nic jsi nenašel a Borislav se ještě víc uzavřel do sebe.","orig":"C","text":"Zjisti pravou příčinu zřícení mostu (špatný materiál, sabotáž, nebo magická interference) a přines mu důkazy."}},"image":"assets/npc/n016.webp","source_file":"grok_image_1777202960683.jpg"},{"id":17,"name":"Bořík","title":"Sprostá moudrá sova","is_boss":false,"story":"„No konečně někdo, kdo nevypadá jako totální debil. Hele, ty suchopárný křupane... vidíš to okno támhle? Tam ta tlustá bába právě vytáhla z trouby obrovský jablečný koláč. Já bych ho sežral zaživa, ale tahle křídla mi na to nestačí. Tak co? Jdeš mi ho ukrást? Nebo se bojíš, že ti ta babizna nakope prdel?“","choices":{"boj":{"mode":"dice","success":"Koláč je tvůj! Sova se cpe a ty máš drobky až za ušima.","fail":"Babizna tě zmlátila válečkem a koláč zůstal na okně.","karma":-1,"orig":"A","text":"„Tak jdi a ten koláč jí seber! Kdyby začala řvát, tak jí dej přes hubu utěrkou... nebo prostě utíkej, ty srabku.“"},"charisma":{"mode":"choice","options":[{"label":"Hrát hladového sirotka","outcome":"Bába tě pohladí, dá ti koláč a k tomu i hrnek mléka.","result":"good"},{"label":"Zkusit Bořikovu „ocasovou“ hlášku","outcome":"Bába zrudne, popadne pánev a pak už jen vidíš hvězdičky.","result":"bad"}],"orig":"B","text":"„Nebo ji tam dole nějak obalamutíš, ať ti ten koláč sama dá. Třeba jí řekni, že jsi hladový sirotek... nebo že máš hladový ocas, to taky funguje.“"},"magie":{"mode":"choice","options":[{"label":"Podstrčit falešný koláč z bláta","outcome":"Bába nic nepozná a Bořík řve smíchy. Koláč je váš.","result":"good","karma":-1},{"label":"Zapálit jí komín","outcome":"Hoří celá střecha a vesnice tě honí s vědry.","result":"bad","karma":-1}],"orig":"C","text":"„Nebo vymysli nějakou chytrou léčku – třeba zapálíš její komín, ať uteče, nebo jí podstrčíš falešný koláč. Hlavně ať se nažereme.“"}},"image":"assets/npc/n017.webp","source_file":"grok_image_1777206268385.jpg"},{"id":18,"name":"Bratr Anselm","title":"Mladý horlivý kněz","is_boss":false,"story":"„Dobrého dne, cestovateli. Já jsem bratr Anselm. V naší vesnici je velký nedostatek vody a lidé se začínají hádat o každý kbelík. Potřebuji, aby se lidé znovu spojili v modlitbě a vzájemné pomoci. Pomůžeš mi svolat vesničany a uspořádat společnou bohoslužbu a sbírku na novou studnu?“","choices":{"boj":{"mode":"dice","success":"Rozlícený dav jsi odrazil, aniž bys někomu ublížil. Anselm ti žehná.","fail":"Dav tě zasypal shnilou zeleninou a Anselm musel zachraňovat tebe.","karma":1,"orig":"A","text":"Ochraň Anselma před rozlícenými vesničany, kteří ho obviňují, že je to on, kdo „zlobil bohy“."},"charisma":{"mode":"dice","success":"Hlavní rodiny přišly a vesnice se znovu spojila v modlitbě.","fail":"Rodiny se pohádaly ještě víc – a teď i s tebou.","karma":1,"orig":"B","text":"Pomoz Anselmovi přesvědčit hlavní vesnické rodiny, aby se dostavily na shromáždění."},"magie":{"mode":"choice","options":[{"label":"Sledovat pramen nahoru do lesa","outcome":"Najdeš mrtvého jelena v prameni. Odklidíš ho a voda je zase čistá.","result":"good","karma":1},{"label":"Obvinit mlynáře, který vypadá podezřele","outcome":"Mlynář je nevinný a jeho synové ti to vysvětlí pěstmi.","result":"bad"}],"orig":"C","text":"Zjisti skutečnou příčinu nedostatku vody (někdo znečišťuje pramen) a pomoz ji vyřešit."}},"image":"assets/npc/n018.webp","source_file":"grok_image_1777121949398.jpg"},{"id":19,"name":"Bratrstvo Padlých","title":"Zeleně zářící pustina mrtvých válečníků","is_boss":false,"story":"„...jsme ti, co zůstali...\nTrpaslíci, orkové, lidé, elfové...\nBojovali jsme tu proti sobě celé dny.\nPadli jsme vedle sebe.\nTeď už není nenávist. Jen únava.\nBloudíme tu už stovky let a vzpomínáme, jak jsme zemřeli.“\n„Chceme najít klid. Chceme odejít dál.\nPomoz nám pochopit, proč jsme tu uvězněni... a jak konečně najít mír.“","choices":{"boj":{"mode":"dice","success":"Duch velitele padl a uznal, že bitva skončila. Bratrstvo může odejít.","fail":"Duch velitele tě srazil přízračnou sekerou. Bitva pro něj pokračuje.","karma":1,"orig":"A","text":"Poraz nejsilnějšího ducha mezi nimi (ducha velitele bitvy), který brání zbytku odejít, protože stále věří, že bitva neskončila."},"charisma":{"mode":"choice","options":[{"label":"Nechat promluvit nejdřív orky","outcome":"Orkové mluví o cti, elfové pláčou, trpaslíci se smějí. Odpustí si.","result":"good","karma":1},{"label":"Nechat promluvit nejdřív elfy","outcome":"Elfové mluví tři hodiny a orkové usnou. Nic se nezmění.","result":"neutral"}],"orig":"B","text":"Vyslechni jejich příběhy o smrti, usmiř staré nepřátele mezi nimi a pomoz jim odpustit si navzájem poslední zbytky zášti."},"magie":{"mode":"dice","success":"Znesvěcený hrob jsi znovu posvětil. Duchové se rozplynou ve světle.","fail":"Kletba ti vlezla do kostí a dlouho tě mrazí.","orig":"C","text":"Zjisti pravou příčinu, proč jsou uvězněni (starobylá kletba bitevního pole, znesvěcený hrob velitele, nebo zapomenutý rituál) a proveď obřad, který je osvobodí."}},"image":"assets/npc/n019.webp","source_file":"grok_image_1777244932897.jpg"},{"id":20,"name":"Brokton Hromobijec","title":"Humanoidní opičí válečník","is_boss":false,"story":"„Grunt! Já Brokton! Potřebuju postavit pořádnou loď, co vydrží dva dny na moři… ale sám to nestihnu. Ty silný! Pomůžeš mi? Já ti dám nejlepší část pokladu, co najdu na ostrově!“","choices":{"boj":{"mode":"dice","success":"Loď stojí! Brokton řve radostí a bubnuje si na hruď.","fail":"Stěžeň ti spadl na hlavu. Brokton se směje a ty vidíš opice.","orig":"A","text":"Pomoz Broktonovi postavit loď vlastními silami."},"charisma":{"mode":"choice","options":[{"label":"Sehnat v hospodě silné dřevorubce","outcome":"Za sud piva přijdou celá vesnice. Loď je hotová v rekordním čase.","result":"good"},{"label":"Vymámit z Broktona větší podíl","outcome":"Brokton slíbí cokoliv – a pak zapomene. Opice.","result":"neutral"}],"orig":"B","text":"Sežeň v okolní vesnici další silné ruce (nebo přesvědč Broktona, ať ti slíbí větší podíl z pokladu).","quest":{"targets":["village"],"goal":"Sežeň v okolní vesnici silné ruce pro Broktona","gp":false}},"magie":{"mode":"dice","success":"Tvé dehtování a spoje vydrží i bouři. Brokton tě jmenuje kapitánem.","fail":"Loď se potopila u mola. Brokton tě hodil za ní.","orig":"C","text":"„Navrhni lepší konstrukci lodi (lepší spoje, dehtování, plachty), aby opravdu vydržela dva dny na otevřeném moři.“"}},"image":"assets/npc/n020.webp","source_file":"grok_image_1777103724418.jpg"},{"id":21,"name":"Bubík Vševědoucí","title":"Drobný vtipný polobůh","is_boss":false,"story":"(Bubík se opře o korunu, která mu sjela přes oči, a zakřičí písklavým hlasem)\n„No konečně! Už jsem si myslel, že tu chcípnu nudou!\nJá jsem Bubík Vševědoucí, polobůh zábavy, pití a občas i trochy moudrosti!\nVíš, jak je to s bohy - jednou za sto let se mi chce něco udělat, a zrovna teď mi přišla chuť na srandu.\nTak pojď, smrtelníku! Mám pro tebe tři úplně debilní úkoly.\nKdo splní všechny tři, dostane ode mě opravdový božský dar. Nebo aspoň pořádnou opici.“","choices":{"boj":{"mode":"dice","success":"Medvěd dostal přes držku a Bubík má zpět svou medovinu.","fail":"Medvěd dostal přes držku tebe. Dvakrát.","orig":"A","text":"„Tamhle za kopcem je obří medvěd, který mi ukradl sud medoviny. Jdi mu ho sebrat! Ať mu dáš přes držku, ať ví, že se s Bubíkem nezahrává!“"},"charisma":{"mode":"choice","options":[{"label":"Říct starostovi kletbu vážně a dramaticky","outcome":"Starosta omdlí, Bubík se smíchy válí po zemi a hodí ti zlaťák.","result":"good"},{"label":"Říct to se smíchem","outcome":"Starosta se urazí a pošle na tebe stráže.","result":"bad"}],"orig":"B","text":"„Běž do vesnice a řekni tamnímu starostovi, že ho Bubík Vševědoucí proklel, ať mu tři dny roste ocas. A natoč mi, jak bude reagovat!“","quest":{"targets":["village"],"goal":"Vyřiď starostovi Bubíkovu „kletbu“","gp":false}},"magie":{"mode":"choice","options":[{"label":"Ukrást pokrývku a nastražit stopu na kozu","outcome":"Kněží honí kozu po náměstí. Bubík má nový klobouk.","result":"good","karma":-1},{"label":"Prostě ji vzít a utíkat","outcome":"Kněží tě poznali. Celý týden tě budou proklínat.","result":"bad","karma":-1}],"orig":"C","text":"„Ukradni z místního chrámu kněžskou pokrývku hlavy a přines mi ji. Chci si z ní udělat klobouk. Ať to vypadá, že jsem to neukradl já... i když jo.“"}},"image":"assets/npc/n021.webp","source_file":"grok_image_1777280231010.jpg"},{"id":22,"name":"Bába Ludmila","title":"Zoufalá stará žena","is_boss":false,"story":"Prosím tě, hrdino... můj Jindřich umírá. Už tři dny mu to v sobě hlodá. Pomoz mi, než ho ztratím!","choices":{"boj":{"mode":"dice","success":"Velmíra jsi přivlekl dolů z hor. Jindřich přežije.","fail":"Velmír tě praštil holí a utekl do skal.","orig":"A","text":"Nejlepší léčitel na celém kontinentu žije vysoko v horách – mistr Velmír. Je to tvrdý a nedůvěřivý muž. Přiveď ho sem silou, jestli bude nutné. Můj muž už nemá čas.","quest":{"targets":["mountain"],"goal":"Přiveď z hor mistra léčitele Velmíra","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Slíbit Velmírovi babičky poslední groš","outcome":"Velmír se zastydí, peníze nevezme a přijde.","result":"good","karma":1},{"label":"Vyhrožovat mu kletbou vesnice","outcome":"Velmír se jen zasměje a zabouchne ti dveře před nosem.","result":"bad"}],"orig":"B","text":"Přesvědč mistra Velmíra, ať přijde. Řekni mu, co chceš – že mu zaplatím poslední groš, že mu políbím nohy, cokoliv... Jen ať přijde a zachrání mého Jindřicha."},"magie":{"mode":"dice","success":"Zlá energie vyletěla z Jindřicha jako černý dým. Ludmila pláče štěstím.","fail":"Kouzlo se ti vymklo a kletba přeskočila na chvíli do tebe.","karma":1,"orig":"C","text":"Mistr Velmír říká, že v mém muži je zlá energie – nějaké prokletí. Máš pomoct provést rituál, který ji z něj dostane ven. Mám už připravené všechny byliny a svíce... chybí jen tvá pomoc při samotném kouzlu."}},"image":"assets/npc/n022.webp","source_file":"grok_image_1777035157731.jpg"},{"id":23,"name":"Bělovlasá","title":"Duch bledé dívky","is_boss":false,"story":"„Viděl jsi mou panenku? Má modré šaty... Už ji hledám sto let...\nProsím... pomoz mi ji najít, abych mohla konečně spát.“","choices":{"boj":{"mode":"dice","success":"Temné duchy jsi rozehnal a dívka konečně odchází ke světlu.","fail":"Temní duchové tě obklíčili a ledovým dechem ti vzali sílu.","karma":1,"orig":"A","text":"Ochraň ji před temnými duchy, kteří jí brání odejít."},"charisma":{"mode":"choice","options":[{"label":"Najít panenku a dát jí ji","outcome":"Bělovlasá se usměje, obejme panenku a pomalu se rozplyne.","result":"good","karma":1},{"label":"Říct jí, že panenka už neexistuje","outcome":"Dívka se rozpláče, sklo v oknech praská a tebe mrazí.","result":"bad"}],"orig":"B","text":"Utěš ji a pomoz jí přijmout, že už je mrtvá."},"magie":{"mode":"dice","success":"Zjistil jsi, že ji zamkli ve sklepě. Otevřel jsi dveře a ona je volná.","fail":"Minulost tě pohltila v nočních můrách a ráno ses probudil vyčerpaný.","orig":"C","text":"Zjisti, co se jí skutečně stalo před sto lety a pomoz jí dokončit nedokončenou věc."}},"image":"assets/npc/n023.webp","source_file":"grok_image_1777246681959.jpg"},{"id":24,"name":"Běta Mlynářová","title":"Tlustá mlynářova žena","is_boss":false,"story":"Manžel je pořád v mlýně... a já tady sama jako kůl v plotě. No, ne tak docela sama...","choices":{"boj":{"mode":"choice","options":[{"label":"Ukázat jí sílu – při štípání dřeva","outcome":"Běta je nadšená, manžel taky. Dostaneš koláč i zlaťák.","result":"good"},{"label":"Ukázat jí sílu… jinak","outcome":"Mlynář se vrátil dřív. S pytlem mouky v ruce.","result":"bad"}],"orig":"A","text":"„Můj manžel je silný jako býk, ale v posteli je jako mouka. Ukaž mi, jakej jsi opravdovej silák!“"},"charisma":{"mode":"dice","success":"Běta se nasmála a byla tak spokojená, že ti dala do kapsy pár grošů.","fail":"Běta tě vyhodila – nejsi prý dost „sladký“.","orig":"B","text":"„Pojď sem, ty hezoune. Manžel je pryč do večera... a já mám takovou chuť na něco sladkého.“","text_female":"„Rozvesel mého manžela, ať je v dobré náladě. Pak si můžu doběhnout do hospody za Jírou... ten aspoň umí kejkle!“"},"magie":{"mode":"dice","success":"Mlynář dostal na starost „velkou zakázku“. Vy dva jste si… popovídali.","fail":"Mlynář tvůj trik prohlédl a hodil po tobě pytlem mouky.","orig":"C","text":"„Manžel je chudák, pořád jen mele. Vymysli nějaký chytrý trik, jak ho na chvíli zaměstnat, ať si můžeme... popovídat!“"}},"image":"assets/npc/n024.webp","source_file":"grok_image_1777032281873.jpg"},{"id":25,"name":"Bětka Dojička","title":"Vesnická kráska s kravami","is_boss":false,"story":"„No nazdar, cizince… Nechtěl bys mi pomoct s dojením? Ty krávy dneska dávají extra… hodně. A já mám takové teplé ruce…“","choices":{"boj":{"mode":"dice","success":"Vlkodlaci prchají a stádo je v bezpečí. Bětka ti nalije mléko i medovinu.","fail":"Vlkodlak tě kousl do zadku. Bětka se smála až do večera.","karma":1,"orig":"A","text":"Ochraň Bětku a její krávy před obřími lesními vlkodlaky, kteří útočí na stádo."},"charisma":{"mode":"choice","options":[{"label":"Flirtovat s ní zpátky","outcome":"Bětka se rozesměje, zčervená a dá ti džbánek smetany a pusu.","result":"good"},{"label":"Vážně se učit dojit","outcome":"Kráva tě kopla. Bětka smutně vzdychla.","result":"bad"}],"orig":"B","text":"„Pomoz mi s dojením… a já ti pak ukážu, jak se správně drží… mléko.“ (dvojsmyslný flirt)"},"magie":{"mode":"dice","success":"Magický zvonek byl u kozla v chlévě. Krávy zase dojí jako o život.","fail":"Zvonek jsi nenašel a krávy tě vyhnaly z ohrady.","orig":"C","text":"Zjisti, proč krávy nedávají mléko (někdo jim ukradl magický zvonek) a pomoz ho najít."}},"image":"assets/npc/n025.webp","source_file":"grok_image_1777106637375.jpg"},{"id":26,"name":"Bětka Velká Lžíce","title":"Baculatá kuchařka","is_boss":false,"story":"No tak pojď, ty silný! Pomoz mi s tou zatracenou řepou!","choices":{"boj":{"mode":"dice","success":"Obří řepa je venku! Bětka z ní uvaří polévku pro celou vesnici.","fail":"Řepa tě zalehla a Bětka tě musela vytahovat.","orig":"A","text":"Obří řepa se probudila a ničí zahradu! Vytáhni ji ze země!"},"charisma":{"mode":"choice","options":[{"label":"Slíbit manželovi pivo navíc","outcome":"Manžel vyskočí z lavice a hned krájí cibuli.","result":"good"},{"label":"Vyhrožovat mu","outcome":"Manžel se urazí a jde spát. Bětka se zlobí na tebe.","result":"bad"}],"orig":"B","text":"Můj manžel je lenoch. Přesvědč ho, ať mi pomůže v kuchyni."},"magie":{"mode":"choice","options":[{"label":"Sehnat ingredience v lese","outcome":"Najdeš všechny houby. Kouzelná polévka tě posílí.","result":"good"},{"label":"Sehnat ingredience na trhu","outcome":"Trhovec tě ošidil a polévka chutná jako ponožky.","result":"neutral"}],"orig":"C","text":"Našla jsem starý recept na kouzelnou polévku. Pomoz mi sehnat chybějící ingredience."}},"image":"assets/npc/n026.webp","source_file":"grok_image_1777024577436.jpg"},{"id":27,"name":"Dalirian Jemný","title":"Elfský estét","is_boss":false,"story":"„Ach, drahoušku... ty jsi ale pohled pro unavené oči.“","choices":{"boj":{"mode":"dice","success":"Medvěd utekl a Dalirian tě políbil na obě tváře.","fail":"Medvěd ti roztrhl kalhoty. Dalirian omdlel.","orig":"A","text":"„Divoký medvěd terorizuje mou zahradu. Zbav mě ho, milánku.“"},"charisma":{"mode":"choice","options":[{"label":"Přinést milenci kytici od Daliriana","outcome":"Blepta dojatě zabrumlá a milenci se usmíří.","result":"good"},{"label":"Napsat milenci básničku za Daliriana","outcome":"Básnička se rýmuje na „kladivo“. Hádka pokračuje.","result":"bad"}],"orig":"B","text":"„Můj milenec se se mnou pohádal. Pomoz mi ho usmířit.“"},"magie":{"mode":"dice","success":"Báseň jsi rozluštil – je to milostný dopis elfí královny! Dalirian zaplatí zlatem.","fail":"Báseň byla prokletá a ty jsi celý den mluvil ve verších.","orig":"C","text":"„Našel jsem starou elfskou báseň, kterou nikdo nedokáže přeložit. Pomoz mi ji rozluštit.“"}},"image":"assets/npc/n027.webp","source_file":"grok_image_1777023837762.jpg"},{"id":28,"name":"Dalirie Šuplíková","title":"Tajemná špionka a kurtizána","is_boss":false,"story":"(Dalirie se k tobě přiblíží, lehce se dotkne tvé paže a zašeptá ti do ucha sametovým hlasem) „Milý... potřebuji tvou pomoc. Dnes večer musím někoho... navštívit. Budeš mým rozptýlením? Tanec, flirt, malý skandálek... cokoli, co odvede pozornost. Za dobrou službu ti zaplatím víc než zlato.“","choices":{"boj":{"mode":"choice","options":[{"label":"Vyvolat rvačku v sále","outcome":"Stráže se rvou s hosty a Dalirie nepozorovaně splní svou misi.","result":"good"},{"label":"„Nešťastnou náhodou“ shodit lustr","outcome":"Lustr spadl na tebe. Mise se povedla, ale bolí to.","result":"bad"}],"orig":"A","text":"Vytvoř rozptýlení násilím – vyvolat rvačku, odvést stráže nebo „nešťastnou náhodou“ způsobit chaos v sále."},"charisma":{"mode":"dice","success":"Celý sál zírá na váš tanec. Dalirie mizí a ty dostáváš sladkou odměnu.","fail":"Zakopl jsi při tanci a všichni se smáli. Dalirie musela misi odložit.","orig":"B","text":"Flirtuj s Dalirií na veřejnosti tak intenzivně, aby všichni zírali jen na vás dva (tanec, polibky, skandál)."},"magie":{"mode":"dice","success":"Falešná zpráva zabrala a cíl vyšel na balkón. Dalirie ti tajně předá váček zlata.","fail":"Tvůj plán se prozradil a stráže tě vyvedly ven.","orig":"C","text":"Vymysli chytrý plán rozptýlení – např. falešnou zprávu, sabotáž hudby, nebo odlákat cíl na balkón, zatímco Dalirie pracuje."}},"image":"assets/npc/n028.webp","source_file":"grok_image_1777194336653.jpg"},{"id":29,"name":"Darena & Levandula","title":"Hnusné sestry z Černého Kotlíku","is_boss":false,"story":"(Darena se zachechtá chraplavě, Levandula se zlomyslně usměje)\nDarena: „Hehehe, další hlupák přišel!“\nLevandula: „Místní lidé nás obtěžují... pořád si stěžují, že jim krademe děti, trávíme dobytek a posíláme noční můry.“\nDarena: „Tak jsme se rozhodly... ať už konečně drží hubu!“\nObě: „Přines nám Srdce sedmi vesničanů, kteří si na nás stěžovali. Čerstvá, ještě teplá. Uděláš to pro nás... a my ti dáme moc, o jaké se ti ani nezdálo.“","choices":{"boj":{"mode":"choice","options":[{"label":"Odmítnout a varovat vesničany","outcome":"Vesničané se ozbrojí a čarodějnice odletí. Vesnice ti děkuje.","result":"good","karma":1},{"label":"Předstírat souhlas a utéct se zálohou","outcome":"Čarodějnice tě proklely – celý týden ti budou vypadávat vlasy.","result":"bad"}],"orig":"A","text":"Zavraždi sedm vybraných vesničanů (nebo jejich rodinné příslušníky) a dones čarodějnicím jejich srdce."},"charisma":{"mode":"dice","success":"Čarodějnice přijaly jako oběť černého kohouta a nechaly vesnici být.","fail":"Čarodějnice se urazily a proměnily tvé boty v ropuchy.","karma":1,"orig":"B","text":"Přesvědč čarodějnice, aby místo toho přijaly jinou oběť (nebo je nalákej na ještě horší zlo)."},"magie":{"mode":"dice","success":"Ukradené vlasy z kotle čarodějnice svázaly. Jsou bezmocné!","fail":"Kotlík vybuchl a pokryl tě zeleným slizem.","orig":"C","text":"Zjisti, jak čarodějnice oslabit (najdi jejich pravé jméno, ukradni jejich vlasy z kotle, nebo najdi starobylou runu, která je sváže)."}},"image":"assets/npc/n029.webp","source_file":"grok_image_1777243208212.jpg"},{"id":30,"name":"Darla Plamenná","title":"Provokativní sukuba","is_boss":false,"story":"„Pojď blíž, hrdino… nebo hrdinko. Nikdo mi ještě neodolal… zatím.“","choices":{"boj":{"mode":"choice","options":[{"label":"Odmítnout ji a odejít","outcome":"Darla se urazí, ale s respektem. Prý jsi první, kdo odolal.","result":"good"},{"label":"Nechat se zlákat","outcome":"Probudíš se bez měšce, bez bot a s úsměvem.","result":"bad"}],"orig":"A","text":"„Byl jsi najat, abys mě porazil, že? Ale já nechci bojovat… Pojď ke mně. Ukaž mi, jaký jsi opravdový silák… v něčem mnohem příjemnějším.“"},"charisma":{"mode":"dice","success":"Odolal jsi jejímu pohledu! Darla ti uznale hodí zlatý přívěsek.","fail":"Zlomil ses za půl minuty. Darla si vzala tvé zlaťáky jako trofej.","orig":"B","text":"„Myslíš, že mě mentálně porazíš? Že mi odoláš? No tak… podívej se mi do očí a zkus to. Uvidíme, jak dlouho vydržíš, než se zlomíš.“"},"magie":{"mode":"choice","options":[{"label":"Nakonec rytíře Tymothyho varovat","outcome":"Tymothy ti děkuje a Darla zuří – ale už ti nic neudělá.","result":"good","karma":1},{"label":"Rytíře očarovat pro Darlu","outcome":"Rytíř padne k jejím nohám. Darla platí, karma pláče.","result":"neutral","karma":-1}],"orig":"C","text":"„Chceš mi opravdu pomoct? Ten jeden jediný chlap, co mi kdy odolal — rytíř Tymothy. Očaruj ho, zlom ho, ať mi konečně padne k nohám.“"}},"image":"assets/npc/n030.webp","source_file":"grok_image_1777040400961.jpg"},{"id":31,"name":"Deméter Dvorní Šašek","title":"Zlý manipulátor","is_boss":false,"story":"Ach, můj milý dobrodruhu... Vládce je tak snadno ovladatelný. Stačí mu našeptat pár lží... a brzy se všichni ti pyšní lordi a rádcové pustí do sebe jako psi. Pomůžeš mi trochu... zažehnout ten oheň?","choices":{"boj":{"mode":"choice","options":[{"label":"Polít šlechtice vínem a hodit vinu na druhého","outcome":"Šlechtici se poperou, Deméter tleská a platí. Dvůr se otřásá.","result":"good","karma":-1},{"label":"Odmítnout a varovat stráže","outcome":"Deméter se jen usměje… a tvé jméno se brzy objeví v pomluvách.","result":"bad","karma":1}],"orig":"A","text":"Vyprovokuj veřejně spor mezi dvěma vlivnými šlechtici, aby se fyzicky střetli (nebo jejich stráže)."},"charisma":{"mode":"dice","success":"Pomluvy se šíří jako mor. Deméter ti štědře zaplatí.","fail":"Tvá lež se prozradila a dvořané tě vyhodili z paláce.","karma":-1,"orig":"B","text":"Pomoz Deméterovi šířit rafinované pomluvy a dezinformace mezi členy rady a dvořany."},"magie":{"mode":"choice","options":[{"label":"Podstrčit vládci falešný dopis","outcome":"Vládce zuří a rádci prchají. Deméter ti hodí měšec – a varuje tě, ať mlčíš.","result":"good","karma":-1},{"label":"Prozradit Deméterův plán vládci","outcome":"Vládce ti nevěří a nechá tě vyprovodit. Deméter se zlověstně usmívá.","result":"bad","karma":1}],"orig":"C","text":"Vymysli a proveď chytrý plán, jak donutit vládce, aby podezíral své nejbližší rádce a začal je pronásledovat."}},"image":"assets/npc/n031.webp","source_file":"grok_image_1777118318463.jpg"},{"id":32,"name":"Dvojice ošklivých trpaslic – „Sestřičky“ Bruta & Gruda","title":"","is_boss":false,"story":"(Bruta se na tebe nakloní, pěna jí teče po bradě)\nBruta: „No nééé, podívej, Grudo! To je ale féšák!“\nGruda: „Jojo, von voní jako čerstvě vykopaná šachta… Hej ty! Nedáš si panáka? Nebo rovnou nás dvě? My ti ukážeme, jak trpaslice kopou!“\n(Obě se hlasitě zachechtají a přiťuknou si korbely)","choices":{"boj":{"mode":"dice","success":"Přežil jsi „zápasovou noc“! Trpaslice tě oslavují a dají ti půlku své výplaty.","fail":"Ráno nemůžeš chodit. Trpaslice spokojeně chrápou.","orig":"A","text":"„Tak co, jdeš do toho? Kdo z nás tě unaví dřív!“ (fyzicky náročná „zápasová“ noc)"},"charisma":{"mode":"choice","options":[{"label":"Zdvořile odmítnout a koupit jim rundu","outcome":"Sestřičky se dojmou, připijí ti a dají ti tip na zlatý důl.","result":"good"},{"label":"Povzbuzovat je ještě víc","outcome":"Rozjedou se tak, že tě odnášejí na ramenou do tmavé šachty.","result":"bad"}],"orig":"B","text":"Přesvědč je, ať tě nechají na pokoji… nebo naopak je ještě víc povzbuď (plno černého humoru a trpaslic)."},"magie":{"mode":"dice","success":"„Mám doma tři manželky a draka!“ Sestřičky ti uvěří a s respektem ustoupí.","fail":"Výmluva se nepovedla. Sestřičky tě unesly na tanec do rána.","orig":"C","text":"Vymysli chytrou výmluvu, jak se z toho elegantně vykroutit (nebo naopak je obě „uspokojit“ najednou kreativním způsobem)."}},"image":"assets/npc/n032.webp","source_file":"_storage_emulated_0_GRUMPSTONE desková hra _BOSSOVE A NPC A HRDINOVE_grok_image_1777245439394.jpg"},{"id":33,"name":"Děda Hniloba","title":"Lesní dědeček","is_boss":false,"story":"Člověče... masíčko... přines mi něco dobrého k jídlu.","choices":{"boj":{"mode":"choice","options":[{"label":"Lovce varovat a odvést pryč","outcome":"Lovec ti vděčně dá kožešinu a zlaťáky. Děda Hniloba skřípe zuby.","result":"good","karma":1},{"label":"Lovce skutečně zabít","outcome":"Děda tě odmění kostí plnou zlata. Tvé ruce jsou ale od krve.","result":"neutral","karma":-1}],"orig":"A","text":"Zabij toho otravného lovce, co mi ruší hostinu."},"charisma":{"mode":"dice","success":"Dovedl jsi dědu k dívce… která byla převlečený strážný. Hniloba prchá do bažin.","fail":"Vesničané tě s dívkou viděli a honili tě s pochodněmi.","karma":1,"orig":"B","text":"Přiveď mi mladou dívku z vesnice... živou."},"magie":{"mode":"dice","success":"Runy prozradily: snědl duši starého potulného barda. Děda je spokojený a zaplatí.","fail":"Kost tě proklela a celý den ti v hlavě hraje falešná loutna.","orig":"C","text":"Našel jsem starou kost s runami. Ty mi řekni, jakou duši jsem snědl."}},"image":"assets/npc/n033.webp","source_file":"grok_image_1777024491814.jpg"},{"id":34,"name":"Děda Levandulín Mrkvička","title":"90letý vesnický stařík","is_boss":false,"story":"„Kde je moje Maruška? Nebo byla to Mařenka? Počkej… a kde je vlastně Igor Mrkvička, můj bratr! Musím ho najít, než zapomenu, jak se jmenuji… což už se stalo dvakrát dneska.“","choices":{"boj":{"mode":"dice","success":"Igora jsi z lesa přivedl domů – i s medvědem na provázku. Stařík pláče štěstím.","fail":"Dlužníci si tě spletli s Igorem. Dostal jsi jeho výprask.","orig":"A","text":"„Ten můj bratr Igor se prý schovává před starými dlužníky v lese za vesnicí. Jdi tam a přiveď mi ho domů! Jestli tam bude medvěd, tak ho taky přiveď, ať máme maso.“","quest":{"targets":["forest"],"goal":"Najdi Igora schovaného v lese","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Hledat Marušku na hřbitově","outcome":"Najdeš její hrob a dědu tam přivedeš. Usmíří se s minulostí.","result":"good","karma":1},{"label":"Hledat Mařenku v krčmě","outcome":"Mařenka v krčmě je zrzavá výčepní. Děda se zamiluje znovu. Chaos.","result":"neutral"}],"orig":"B","text":"„Najdi mou ženu Marušku… nebo byla to Mařenka? Řekni jí, ať se vrátí, že jí odpouštím, že mi spálila kaši před čtyřiceti lety. Ať už mi uvaří novou!“"},"magie":{"mode":"choice","options":[{"label":"Projít s dědou staré dopisy","outcome":"V dopisech je adresa. Igor bydlí za humny! Rodina je zase pohromadě.","result":"good"},{"label":"Zeptat se na trhu","outcome":"Trhovci se smějí. Za padesát let se tu vystřídalo hodně Igorů.","result":"neutral"}],"orig":"C","text":"„Mám tu fotku mého bratra Igora… nebo je to já? Nebo můj táta? Pomoz mi zjistit, kde teď bydlí. Vzpomínám si, že říkal něco o tom, že jde na trh… před padesáti lety.“"}},"image":"assets/npc/n034.webp","source_file":"grok_image_1777038892663.jpg"},{"id":35,"name":"Eldrinus Stínolovec","title":"Tajemný půl-elf lovec","is_boss":false,"story":"„Šest banditů v sousedním městě… Já je znám, ale nechci riskovat krk sám. Půjdeš se mnou? Odměnu si rozdělíme férově. Co říkáš, parťáku?“","choices":{"boj":{"mode":"dice","success":"Šest banditů je poražených. Eldrinus férově dělí odměnu.","fail":"Bandité tě přepadli dřív, než jste dorazili. Eldrinus tě táhne pryč.","karma":1,"orig":"A","text":"Vydej se s Eldrinusem a společně zlikvidujte šest banditů v jejich táboře."},"charisma":{"mode":"choice","options":[{"label":"Zeptat se Eldrinuse na bandity přímo","outcome":"Eldrinus prozradí, že bandité mají strach z vlků. Plán je jasný a odměna tvoje.","result":"good"},{"label":"Opít ho, ať se rozpovídá","outcome":"Eldrinus usne a ráno nic neví. Bandité jsou pryč.","result":"neutral"}],"orig":"B","text":"Přesvědč Eldrinuse, ať ti prozradí víc o banditech (nebo ho přemluv, ať to vyřešíte chytřeji než přímým útokem)."},"magie":{"mode":"choice","options":[{"label":"Nastražit past s falešným pokladem","outcome":"Bandité se vrhnou na bednu a spadnou do jámy. Snadná výhra!","result":"good"},{"label":"Nastražit past s ohněm","outcome":"Oheň se rozšíří a spálí půlku tábora i tvůj plášť.","result":"bad"}],"orig":"C","text":"Vymysli past nebo léčku, aby se banditi dostali sami do léčky bez velkého boje."}},"image":"assets/npc/n035.webp","source_file":"grok_image_1777098709930.jpg"},{"id":36,"name":"Elfský král","title":"","is_boss":false,"story":"„Orkové se znovu rozmnožili. Naše lesy krváčí. Potřebuji někoho, kdo dokáže udělat to, co elfské ruce nemohou veřejně poskvrnit. Jsi ochoten sloužit koruně?“","choices":{"boj":{"mode":"dice","success":"Orčí velitel padl. Elfský král ti tajně předá měšec zlata.","fail":"Orkové tě zahnali zpět do lesa a ty jsi přišel o kus ucha.","orig":"A","text":"Znič orkský tábor nebo zabij významného orčího velitele."},"charisma":{"mode":"choice","options":[{"label":"Přesvědčit lordy výzvou ke cti","outcome":"Lordi se přidají. Král tě jmenuje přítelem koruny.","result":"good"},{"label":"Přesvědčit lordy úplatkem","outcome":"Lordi úplatek vezmou a nic neudělají. Král se mračí.","result":"bad"}],"orig":"B","text":"Pomoz králi přesvědčit ostatní elfské lordy, aby podpořili tažení proti orkům."},"magie":{"mode":"dice","success":"Navrhl jsi léčku v soutěsce. Král ji schválí a odmění tě.","fail":"Tvůj plán prozradil zrádce. Elfové prohráli šarvátku a ty neseš vinu.","orig":"C","text":"Zjisti slabiny orkské armády a navrhni strategii, jak je porazit s minimálními ztrátami."}},"image":"assets/npc/n036.webp","source_file":"grok_image_1777131632436.jpg"},{"id":37,"name":"Elowen Stříbrný List","title":"Starý Elfský Archivář","is_boss":false,"story":"„Všechno už jsem viděl... kromě toho, že se někdo dokáže chovat slušně.“","choices":{"boj":{"mode":"dice","success":"Golem je rozbitý na štěrk. Elowen poprvé po letech zamumlá „děkuji“.","fail":"Golem tě vyhodil z okna. Naštěstí do kupky sena.","orig":"A","text":"„V mé staré věži se usadil kamenný golem. Rozbij ho.“"},"charisma":{"mode":"choice","options":[{"label":"Zdvořile elfku požádat","outcome":"Elfka se zastydí a knihu vrátí. Elowen je ohromen tvou slušností.","result":"good"},{"label":"Knihu jí potají ukrást","outcome":"Elfka tě chytí a celá vesnice ví, že jsi zloděj.","result":"bad","karma":-1}],"orig":"B","text":"„Potřebuji, abys přesvědčil mladou elfku z vedlejší vesnice, aby mi vrátila ukradenou knihu.“","quest":{"targets":["village"],"goal":"Získej zpět ukradenou knihu od mladé elfky","gp":false}},"magie":{"mode":"dice","success":"Text je přeložen – je to recept na věčné mládí čaje. Elowen platí.","fail":"Slova tě uspala a probudil ses s inkoustem na obličeji.","orig":"C","text":"„Našel jsem prastarý text v jazyce, který už nikdo neumí. Pomoz mi ho přeložit.“"}},"image":"assets/npc/n037.webp","source_file":"grok_image_1777022832504.jpg"},{"id":38,"name":"Elyndor Modrooký","title":"Zlomený modrý elf v hladomorně","is_boss":false,"story":"(Elyndor zvedne hlavu, hlas má slabý, chraplavý a zlomený)\n„...ty... ty nejsi jeden z nich. Už to nevydržím. Dny se slévají v noci a bolest mě žere zaživa.\nMístní alchymista prodává rychlý bezbolestný jed... pro ty, kteří už nemají naději. Přines mi. Prosím. Nebo... jestli máš odvahu, tak mě osvoboď. Ale vím, že bych daleko nedoběhl...“","choices":{"boj":{"mode":"choice","options":[{"label":"Přetnout řetězy a utéct s ním","outcome":"Útěk se podaří o vlas. Elyndor ti slibuje věčnou vděčnost.","result":"good","karma":1},{"label":"Počkat na noční střídání stráží","outcome":"Stráže se nezměnily. Chytili tě a zmlátili.","result":"bad"}],"orig":"A","text":"Osvoboď Elyndora násilím – přetni řetězy, zabij stráže a pokus se ho dostat ven (velmi nebezpečné)."},"charisma":{"mode":"dice","success":"Elyndor našel v tvých slovech kousek naděje. Rozhodl se žít.","fail":"Tvá slova byla prázdná. Elyndor se odvrátil ke zdi.","karma":1,"orig":"B","text":"Přesvědč ho, aby ještě chvíli bojoval a nechtěl jed (nebo naopak ho utěš a slib mu, že mu jed doneseš)."},"magie":{"mode":"choice","options":[{"label":"Donést mu místo jedu uspávací lektvar a pomoci k útěku","outcome":"Elyndor „zemře“, stráže ho vynesou ven a on se probudí svobodný!","result":"good","karma":1},{"label":"Donést mu skutečný jed","outcome":"Elyndor odejde v klidu. Smutná, tichá odměna.","result":"neutral"}],"orig":"C","text":"Najdi alchymistu, získej rychlý jed a rozhodni, jestli mu ho doneseš, nebo najdeš jiný způsob, jak mu pomoci (léčba, útěk, atd.).","quest":{"targets":["city"],"goal":"Sežeň u městského alchymisty rychlý jed","gp":false}}},"image":"assets/npc/n038.webp","source_file":"grok_image_1777206884028.jpg"},{"id":39,"name":"Etelie Klavírová","title":"Svůdná krčmářská loutnistka","is_boss":false,"story":"„No nazdar, fešáku... Hledám svého bratra. Už tři týdny se neukázal a já mám o něj strach. Ale teď... teď bych si radši zahrála něco jiného než na loutnu. Co ty? Zahraješ si se mnou?“","choices":{"boj":{"mode":"dice","success":"Obtěžovatele jsi vyhodil oknem. Etelie ti zahraje píseň a prozradí stopu po bratrovi.","fail":"Obtěžovatelé byli tři. A měli kamarády.","karma":1,"orig":"A","text":"Někdo u vedlejšího stolu začne Etelii obtěžovat a urážet. Rukama se jí dotkne a ona se lekne. Zbav se ho (nebo celé skupiny) násilím."},"charisma":{"mode":"choice","options":[{"label":"Hrát poctivě","outcome":"Vyhraješ a Etelie ti prozradí, kde je její bratr. A taky… zbytek večera.","result":"good"},{"label":"Švindlovat s kartami","outcome":"Etelie tě prokoukla. Prohrál jsi peníze i kalhoty.","result":"bad"}],"orig":"B","text":"Zahraj si s Etelií svlékací poker. Čím víc vyhraješ, tím víc se svléká a tím víc ti prozradí o svém bratrovi."},"magie":{"mode":"dice","success":"Hádanka vyřešena: bratr je v ledovém sklepení u Rudohradu. Etelie tě obejme.","fail":"Odpověděl jsi „loutna“. Etelie se smutně usmála.","orig":"C","text":"Vyřeš její hádanku, kterou ti dá (týká se jejího bratra a místa, kde by mohl být). Správná odpověď ti prozradí, kde přesně ho hledat."}},"image":"assets/npc/n039.webp","source_file":"grok_image_1777132015321.jpg"},{"id":40,"name":"Eufemie Sladká","title":"Cukrářka s „tajným“ receptem","is_boss":false,"story":"Ochutnej můj koláček, drahoušku! Je v něm láska… a trocha těch zelených fleků, co dávají extra chuť!","choices":{"boj":{"mode":"dice","success":"Obří myš je mrtvá. Eufemie ji opravdu upekla a tobě dala zlaťáky.","fail":"Myš ti ukousla kus boty.","orig":"A","text":"„Obří myš mi požírá zásoby! Zabij ji! Ať mi aspoň tu myš upeču do dortu, bude mít masovou náplň!“"},"charisma":{"mode":"choice","options":[{"label":"Rytíři říct, že koláče jsou afrodisiakum","outcome":"Rytíř koupí celou várku. Eufemie se směje celý den.","result":"good","karma":-1},{"label":"Rytíři říct pravdu o másle","outcome":"Rytíř je dojatý poctivostí, ale koupí jen jeden koláček.","result":"neutral","karma":1}],"orig":"B","text":"„Přesvědč toho otravného rytíře, ať mi koupí celou várku „Speciálních koláčků“. Řekni mu, že je to afrodisiakum… i když včera jsem do nich dala prosté máslo.“"},"magie":{"mode":"choice","options":[{"label":"Zamaskovat to skořicí a medem","outcome":"Lidé se po koláčcích jen zalykají nadšením. Eufemie platí.","result":"good"},{"label":"Zamaskovat to česnekem","outcome":"Půl vesnice má průjem a hledá tě s vidlemi.","result":"bad"}],"orig":"C","text":"„Pomoz mi vymyslet nový recept. Mám tady prošlé vejce, plesnivý med a mléko, co už voní jako boty… Jak to zamaskovat, aby to lidi kupovali?“"}},"image":"assets/npc/n040.webp","source_file":"grok_image_1777037207378.jpg"},{"id":41,"name":"Evžen Ovčáček","title":"Pasáček ovcí","is_boss":false,"story":"„Ovce mě mají rády... aspoň většinou. Holky ne. Ty mě koušou.“","choices":{"boj":{"mode":"dice","success":"Klárku jsi vytrhl trolům z drápů. Evžen tě objímá, až ti praská páteř.","fail":"Trolové tě vyhodili ze soutěsky. Klárka se tam má dobře.","orig":"A","text":"„Klárka se mi zatoulala do temné soutěsky! Tam žijí trolové a já se bojím. Najdi ji a přiveď ji zpátky, prosím!“","quest":{"targets":["mountain"],"goal":"Najdi Klárku v soutěsce trolů","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Poradit mu, ať jí nosí čerstvý jetel","outcome":"Klárka mu zase okusuje rukáv z lásky. Evžen platí sýrem i grošem.","result":"good"},{"label":"Poradit mu, ať jí zazpívá","outcome":"Evžen zpívá strašně. Uteklo mu celé stádo.","result":"bad"}],"orig":"B","text":"„Klárka se na mě zlobí a už ke mně ani nezajde. Poradíš mi, jak si ji zase získat? Je to moje nejoblíbenější ovce...“"},"magie":{"mode":"choice","options":[{"label":"Ukázat ovcím, jak si vítr hraje s pampeliškami","outcome":"Ovce bečí nadšením a Evžen je hvězda pastvin.","result":"good"},{"label":"Ukázat ovcím jiskřivé kouzlo","outcome":"Ovce se lekly a utekly do vesnice. Evžen pláče.","result":"bad"}],"orig":"C","text":"„Můžeš mi ukázat nějaký pěkný přírodní trik nebo kouzlo, co by nadchlo celé moje stádo? Aby na mě byly pyšné!“"}},"image":"assets/npc/n041.webp","source_file":"grok_image_1777031997840.jpg"},{"id":42,"name":"Fanouš Roubenka","title":"Svalnatý vesnický sedlák","is_boss":false,"story":"„Dobrého večera, cizince... Já jsem Fanouš Roubenka. Syna mi vzali do války už před třemi měsíci a já to pole sám nestihnu. Zima se blíží a když teď nezasiju... doplatím na vše. Pomohl bys mi aspoň dneska? Nebo zítra? Zaplatím ti, co budu moct... nebo ti dám kus úrody na zimu.“","choices":{"boj":{"mode":"dice","success":"Divoká prasata utekla a Fanouš ti nabídne pytel brambor a zlaťák.","fail":"Kanec tě nabral na kly a odhodil do brázdy.","karma":1,"orig":"A","text":"Pomoz Fanoušovi bránit pole před divokými prasaty (nebo bandou zlodějů úrody), která mu ničí práci."},"charisma":{"mode":"choice","options":[{"label":"Požádat o pomoc vdovy z vesnice","outcome":"Vdovy přijdou s koláči i motykami. Pole je hotové do večera.","result":"good","karma":1},{"label":"Požádat mladé kluky","outcome":"Kluci přišli, ale hrají kuličky. Půl pole zůstalo ležet.","result":"neutral"}],"orig":"B","text":"Sežeň ve vesnici další pomocníky (mladé kluky, vdovy, starší sousedy), aby společně stihli pole obdělat."},"magie":{"mode":"dice","success":"Dvojí zápřah a nová brány – pole je zoráno za půl dne!","fail":"Tvůj nový pluh se zlomil a Fanouš musel orat rukama.","orig":"C","text":"Vymysli chytrý způsob, jak pole rychleji obdělat (lepší zapřažení koně, provizorní nástroje, střídání práce atd.)."}},"image":"assets/npc/n042.webp","source_file":"grok_image_1777120846862.jpg"},{"id":43,"name":"Gorzod Modrokůž","title":"Modrý půl-ork válečník","is_boss":false,"story":"„Hej ty! Ano, ty drobný… Potřebuju dračí zub z Ostrovů Zlomených Šupin. Velký, starý, magický. Přineseš mi ho a já ti zaplatím víc, než kdy viděl. Nebo… můžu ti ukázat, jak odměňuju ty, co mi donesou, co chci.“\n(Široce se zazubí a mrkne)","choices":{"boj":{"mode":"dice","success":"Dračí zub je tvůj! Gorzod ti nadšeně buší do zad a platí.","fail":"Drakova potomstva tě zahnala zpátky k lodi. Oheň, kouř, ostuda.","orig":"A","text":"Vypluj na Ostrov Zlomených Šupin a získej dračí zub přímým bojem s drakem nebo jeho potomky.","quest":{"targets":["water"],"goal":"Získej dračí zub na Ostrově Zlomených Šupin","gp":true}},"charisma":{"mode":"choice","options":[{"label":"Najít spojence mezi ostrovními rybáři","outcome":"Rybáři znají jeskyni s vypadlými zuby. Zub je tvůj bez boje.","result":"good"},{"label":"Smlouvat s Gorzodem o zálohu","outcome":"Gorzod se zazubí a místo zálohy ti nabídne „jinou odměnu“. Raději jsi utekl.","result":"neutral"}],"orig":"B","text":"Přesvědč Gorzoda, ať ti dá lepší odměnu dopředu, nebo najdi spojence na ostrovech, kteří ti pomohou zub získat bez zbytečného krveprolití."},"magie":{"mode":"choice","options":[{"label":"Ukrást zub spícímu drakovi","outcome":"Drak chrápe, ty kradeš. Zub je tvůj a kalhoty suché.","result":"good"},{"label":"Vyměnit zub za sud rumu","outcome":"Drak rum vypil, ale zub ti nedal. Pak si říhl ohněm.","result":"bad"}],"orig":"C","text":"Prostuduj staré mapy a legendy, najdi bezpečnější cestu na ostrov a způsob, jak dračí zub získat lstí (např. výměnou nebo krádeží ze spánku)."}},"image":"assets/npc/n043.webp","source_file":"grok_image_1777104665371.jpg"},{"id":44,"name":"Grimor Šedý","title":"Vybledlý skřetí poustevník","is_boss":false,"story":"„Jsem Grimor Šedý... už mnoho let žiji sám. Teď musím vykonat pouť na starobylé místo. Cesta je nebezpečná - banditi, divoká zvěř, temní tvorové... Potřebuji ochranu. Doprovodíš mě? Zaplatím ti vším, co mám... a možná ti ukážu věci, které stojí za to.“","choices":{"boj":{"mode":"dice","success":"Doprovodil jsi Grimora bezpečně. U ruin ti ukáže skrytou truhlu.","fail":"Bandité vás přepadli a Grimor tě musel ošetřovat.","karma":1,"orig":"A","text":"Doprovoď Grimora a braň ho před útoky banditů a divokých šelem na cestě.","quest":{"targets":["chram_slunce","elowen","grimfort"],"goal":"Doprovoď Grimora ke starobylé svatyni","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Zeptat se ho s úctou","outcome":"Grimor prozradí, že hledá hrob své ženy. Daruje ti starý amulet.","result":"good"},{"label":"Naléhat na vyšší odměnu","outcome":"Grimor se urazí a zaplatí jen polovic.","result":"neutral"}],"orig":"B","text":"Přesvědč Grimora, aby ti prozradil, proč jde na tu pouť a co přesně hledá (nebo ho přemluv, ať ti dá větší odměnu)."},"magie":{"mode":"dice","success":"Našel jsi starou poutní stezku. Cesta byla klidná a Grimor ti platí.","fail":"Zabloudili jste v bažinách. Grimor kašle a ty jsi promočený.","orig":"C","text":"Zjisti bezpečnější cestu k cíli (starobylé svatyni / ruinám) a pomoz mu vyhnout se největším nebezpečím."}},"image":"assets/npc/n044.webp","source_file":"grok_image_1777132569118.jpg"},{"id":45,"name":"Grimwald Krvavý","title":"Temný alchymista","is_boss":false,"story":"„Etika je pro slabé. Věda je pro ty, kteří se nebojí krve.“","choices":{"boj":{"mode":"choice","options":[{"label":"Přinést srdce poraženého zločince","outcome":"Grimwald je spokojený. Zaplatí ti dobře, ale tvé ruce páchnou krví.","result":"good","karma":-1},{"label":"Přinést prasečí srdce a zalhat","outcome":"Grimwald to pozná okamžitě a vychrstne na tebe kyselinu.","result":"bad"}],"orig":"A","text":"„Potřebuji čerstvé srdce silného válečníka. Přines mi ho.“"},"charisma":{"mode":"dice","success":"Učedník svolil. Grimwald platí, učedník bledne.","fail":"Učedník utekl za strážemi a ty máš problém.","karma":-1,"orig":"B","text":"„Přesvědč mladého učedníka, ať mi dobrovolně daruje svou krev.“"},"magie":{"mode":"choice","options":[{"label":"Podstrčit Grimwaldovi falešnou „duši“ ve flakonu","outcome":"Elixír vybuchne Grimwaldovi do tváře. Ty mizíš s jeho zlatem.","result":"good","karma":1},{"label":"Opravdu mu duši obstarat","outcome":"Grimwald zesílí. Platí štědře, ale svět je temnější.","result":"neutral","karma":-1}],"orig":"C","text":"„Pomoz mi dokončit elixír nesmrtelnosti. Chybí mi jen jedna složka... lidská duše.“"}},"image":"assets/npc/n045.webp","source_file":"grok_image_1777031344410.jpg"},{"id":46,"name":"Grizelda Krásná","title":"Béžová goblinská „Kráska“","is_boss":false,"story":"No nejsem snad ta nejkrásnější bytost v celém království? Všichni to říkají... no, aspoň já si to říkám. Ale potřebuju lepší zrcadlo, aby to viděl i zbytek světa!","choices":{"boj":{"mode":"dice","success":"Zrcadlo je zpět a trol má bouli. Grizelda se v něm zhlíží celý den.","fail":"Trol tě shodil do bažiny. Grizelda se urazila, že smrdíš.","orig":"A","text":"Ten zlý trol v bažině mi ukradl moje staré zrcadlo! Jdi mu ho sebrat... a jestli budeš muset, tak ho rozmlátíš. Nikdo mi nesmí brát mou krásu!","quest":{"targets":["vodnikova_tun","stare_blato"],"goal":"Seber trolovi z bažiny ukradené zrcadlo","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Zalichotit kováři jeho uměním","outcome":"Kovář vyrobí zrcadlo, které z Grizeldy udělá „princeznu“. Platí ti.","result":"good"},{"label":"Zalichotit kováři Grizeldinou krásou","outcome":"Kovář se rozesmál tak, že spadl do výhně. Žádné zrcadlo.","result":"bad"}],"orig":"B","text":"Přesvědč toho elfského kováře ve vesnici, ať mi vyrobí Zrcadlo úpravy. Řekni mu, že jsem ta nejkrásnější zákaznice, jakou kdy měl. Ať mi udělá iluzi, která ze mě udělá opravdovou princeznu!"},"magie":{"mode":"choice","options":[{"label":"Dát Grizeldě ten polibek","outcome":"Zrcadlo iluzí září. Grizelda je nadšená a štědrá.","result":"good"},{"label":"Podstrčit jí polibek od žáby","outcome":"Zrcadlo ukazuje jen ropuchy. Grizelda tě zmlátí deštníkem.","result":"bad"}],"orig":"C","text":"Našla jsem starý návod na Zrcadlo iluzí, ale chybí mi tři věci: slza jednorožce, duha z pavučiny a polibek od opravdového hrdiny. Pomoz mi to sehnat... a ten polibek můžeš dát ty sám!"}},"image":"assets/npc/n046.webp","source_file":"grok_image_1777035942411.jpg"},{"id":47,"name":"Grohulec Krvavý Řev","title":"Orkský velitel","is_boss":false,"story":"„GRAAAAGH! Grohulec chce krvavou lázeň! Kdo se postaví mé smečce, ten zemře pomalu a bolestivě!“","choices":{"boj":{"mode":"dice","success":"Přežil jsi střet a Grohulcova smečka ustoupila.","fail":"Orkové tě rozdupali. Grohulec se smál ještě tři dny.","karma":1,"orig":"A","text":"Přežij přímý střet s Grohulcovou armádou (nebo mu pomoz v bitvě)."},"charisma":{"mode":"choice","options":[{"label":"Poslat ho na sousední orčí kmen","outcome":"Grohulec řve radostí a táhne pryč. Vesnice ti děkuje.","result":"good"},{"label":"Podplatit ho zlatem","outcome":"Grohulec zlato vezme… a vesnici stejně vyplení.","result":"bad"}],"orig":"B","text":"Přesvědč Grohulce, ať zaútočí na jiného nepřítele (nebo ho podplatíš, aby nechal vesnici na pokoji)."},"magie":{"mode":"dice","success":"Sabotoval jsi zásobování. Hladová armáda se rozpadá.","fail":"Chytili tě u vozů a zmlátili. Grohulec tě nechal jít jen proto, že ses moc smál.","orig":"C","text":"Zjisti slabé místo jeho armády a sabotuj zásobování."}},"image":"assets/npc/n047.webp","source_file":"grok_image_1777110601609.jpg"},{"id":48,"name":"Gromir Železnooký","title":"Zkušený žoldák a lovec odměn","is_boss":false,"story":"(Gromirův hlas je hluboký a drsný, jako škrábání meče o kámen) „Hledám jednoho parchanta. Ukradl něco, co neměl... a teď má cenu za hlavu. Dvacet zlatých živých, třicet mrtvý. I tvrdím, jako že umíš držet meč. Pomůžeš mi ho dostat? Nebo znáš někoho, kdo by mohl...“","choices":{"boj":{"mode":"dice","success":"Cíl je zajat v katakombách. Gromir ti dá tvůj podíl.","fail":"Zločinec tě zahnal do slepé chodby a Gromir ho ztratil.","orig":"A","text":"Přidej se k Gromirovi a pomoz mu zajmout (nebo zabít) cíl – nebezpečného zločince, který se skrývá v městských katakombách."},"charisma":{"mode":"choice","options":[{"label":"Ptát se žebráků","outcome":"Žebráci vědí všechno. Za pár grošů prozradí úkryt a Gromir platí.","result":"good"},{"label":"Ptát se strážných","outcome":"Strážní jsou podplacení zločincem. Pošlou tě do pasti.","result":"bad"}],"orig":"B","text":"Pomoz Gromirovi získat informace od místních (hostinských, žebráků, strážných) a přesvědčit je, aby promluvili."},"magie":{"mode":"dice","success":"Past se zaklapla. Zločinec je v síti a Gromir uznale kývá.","fail":"Převlek se nepovedl a celé město se ti smálo.","orig":"C","text":"Zjisti pravou identitu cíle a vymysli chytrý plán, jak ho lapit (past, převlek, lstivá past v temných uličkách)."}},"image":"assets/npc/n048.webp","source_file":"grok_image_1777202689257.jpg"},{"id":49,"name":"Grushak Železný Dráp","title":"Velitel orkské karavany","is_boss":false,"story":"„My Grushak Železný Dráp. Vezeme zboží do Černovodu. Cesta přes Les je nebezpečná – banditi, vlci, elfské pasti. Ty poznat značky, kde je bezpečno. Zaplatíme ti tučně. Zlatem. Nebo si můžeš vybrat jednoho otroka...“","choices":{"boj":{"mode":"dice","success":"Cesta je čistá. Grushak ti zaplatí tučně.","fail":"Elfské pasti tě chytily za kotník. Visíš hlavou dolů.","orig":"A","text":"Vyčisti cestu od banditů, divokých šelem a elfských hlídek, které karavanu sledují.","quest":{"targets":["forest"],"goal":"Vyčisti lesní cestu před orkskou karavanou","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Požádat o rozhovor s otroky","outcome":"Pomůžeš dvěma otrokům uprchnout v noci. Grushak nic netuší.","result":"good","karma":1},{"label":"Vzít si jednoho otroka jako odměnu","outcome":"Grushak ti ho dá. Hned ho propustíš, ale ostatní zůstali v řetězech.","result":"neutral"}],"orig":"B","text":"Přesvědč Grushaka, ať ti dá větší odměnu nebo ti dovolí promluvit s otroky (možnost pokusu o záchranu některého z nich)."},"magie":{"mode":"dice","success":"Bezpečná trasa je vyznačená. Karavana projde bez ztrát.","fail":"Zavedl jsi karavanu do bažiny. Grushak řve a ty taky.","orig":"C","text":"Najdi a označ bezpečnou trasu lesem, vyhni se pastím, nebezpečným bažinám a místům, kde by mohla číhat léčka."}},"image":"assets/npc/n049.webp","source_file":"grok_image_1777132827162.jpg"},{"id":50,"name":"Gurkenis Péroříz","title":"Srstnatý ork v řetězech","is_boss":false,"story":"„RRRRGH! Pusť mě ven, ty červe! Jmenuju se Gurkenis Péroříz a chci krev! Až budu venku, tak si prvního strážnýho vezmu na Péroříz!“","choices":{"boj":{"mode":"choice","options":[{"label":"Zaútočit na stráže","outcome":"Probijete se ven, Gurkenis ti hodí ukořistěný měšec a zmizí v noci.","result":"good","karma":-1},{"label":"Odejít a nechat ho v cele","outcome":"Gurkenis ti slibuje pomstu. Stráže ti ale dají odměnu za klid.","result":"neutral","karma":1}],"orig":"A","text":"„Stráže jsou slabé! Zabij je všechny a rozbij mi ty řetězy! Chci svobodu a jejich hlavy jako trofeje!“"},"charisma":{"mode":"dice","success":"Velitel je opilý, klíče jsou tvoje. Gurkenis je volný a vděčný.","fail":"Velitel tě zavřel do vedlejší cely na jednu noc.","orig":"B","text":"„Ten hloupý velitel stráže má klíče. Přesvědč ho (nebo ho opij, nebo ho podplať), ať mě pustí. Slib mu cokoliv – zlato, ženy, nebo že ho nezabiju jako prvního.“"},"magie":{"mode":"dice","success":"Stoková šachta vede ven. Gurkenis tě odmění hrstí ukradených mincí.","fail":"Uvízl jsi v šachtě a vylezl celý od bahna a krys.","orig":"C","text":"„Najdi tajný východ z žaláře – je tu stará stoková šachta. Přines mi pilník na řetězy a mapu, jak se dostat ven z města, aniž by nás chytili. Chci ven… a pak chci pomstu.“"}},"image":"assets/npc/n050.webp","source_file":"grok_image_1777039703701.jpg"},{"id":51,"name":"Harpyjí sestry – Hnilka, Smradla a Žravka","title":"","is_boss":false,"story":"„Človíčku… voníš tak svěže… Buď nás nakrmíš, nebo se staneš večeří. Jsme tři a máme velký hlad!“","choices":{"boj":{"mode":"dice","success":"Porazil jsi všechny tři harpyje! Z jejich hnízda si bereš poklad.","fail":"Harpyje tě rozdrápaly a odletěly se smíchem.","karma":1,"orig":"A","text":"„Jsme hladové! Buď s námi bojuj hned teď… nebo nám dones čerstvé maso – ideálně živého zajatce. Ať si ho můžeme vychutnat ještě teplého!“"},"charisma":{"mode":"choice","options":[{"label":"Přivést jim zabitého kance místo člověka","outcome":"Harpyje se nacpou a usnou. Ty bereš lesklé věci z hnízda.","result":"good"},{"label":"Přivést jim opilého zločince","outcome":"Harpyje hodují. Svět je o zločince chudší, tvá karma taky.","result":"neutral","karma":-1}],"orig":"B","text":"„Přines nám hostinu! Najdi nějakého opilého vesničana, tuláka nebo zločince a přiveď ho sem živého. Slibíme ti, že tě necháme na pokoji… tentokrát.“"},"magie":{"mode":"choice","options":[{"label":"Odlákat je na slavnost s falešnými hosty ze slámy","outcome":"Harpyje se zamotají do strašáků. Lidé se smějí a tobě platí starosta.","result":"good","karma":1},{"label":"Přilákat je ke karavaně","outcome":"Karavana je zbraněná. Harpyje se vrátí rozzuřené za tebou.","result":"bad"}],"orig":"C","text":"„Známé místo, kde se scházejí lidé – karavana, tábor nebo slavnost. Vymysli plán, jak nám odtamtud přivést aspoň dva hosty. Chceme večeři s příchutí!“"}},"image":"assets/npc/n051.webp","source_file":"grok_image_1777039865923.jpg","special":"Speciální poznámka pro kladné postavy: Kladné postavy (a některé neutrální) mají možnost odmítnout a okamžitě bojovat se všemi třemi harpyjemi najednou. Boj je obtížný, ale přináší dobré odměny (zkušenosti, poklad z hnízda a reputaci hrdiny).","extra":{"id":"harpyje","who":"good","label":"Bojovat se všemi třemi harpyjemi najednou","stat":"boj","boss":true,"success":"Hnilka, Smradla i Žravka padly. V hnízdě najdeš poklad a bardi o tobě budou zpívat.","fail":"Tři harpyje na jednoho – drápy tě rozsekaly a ty sotva utečeš.","karma":1}},{"id":52,"name":"Hniják","title":"Mluvící hnijící zombie farmář","is_boss":false,"story":"(Hniják se šourá směrem k tobě, z břicha mu kape něco zeleného)\n„No nazdar... už zase někdo živý.\nJá jsem Hniják. Umřel jsem před třemi lety na tomhle poli a pořád tu musím pracovat, protože mi hospodář nevrátil poslední výplatu.\nChceš mi pomoct najít toho parchanta? Nebo mi aspoň podržet ruku, než mi spadne?“","choices":{"boj":{"mode":"choice","options":[{"label":"Hospodáře nakopat","outcome":"Hospodář pláče a vrátí výplatu. Hniják jásá a ztratí přitom ucho.","result":"good"},{"label":"Hospodáře jen postrašit v noci","outcome":"Hospodář umře strachy. Teď máte dva zombie farmáře.","result":"bad"}],"orig":"A","text":"Pomoz mi najít hospodáře a pořádně mu nakopat prdel (nebo ho aspoň pořádně postrašit)."},"charisma":{"mode":"dice","success":"Hniják se rozplakal a odešel na věčnost. Pole je volné.","fail":"Hniják se urazil a hodil po tobě vlastní ruku.","karma":1,"orig":"B","text":"Přesvědč mě, ať už konečně odejdu na věčnost a přestanu strašit lidi na poli."},"magie":{"mode":"dice","success":"Výplata byla pod hruškou. Hniják odchází s úsměvem a nechá ti spropitné.","fail":"Kopal jsi celý den a našel jen starou botu.","orig":"C","text":"Zjisti, kde je zakopaná moje poslední výplata (hospodář ji ukradl) a přines mi ji, ať můžu konečně odejít v klidu."}},"image":"assets/npc/n052.webp","source_file":"grok_image_1777246499591.jpg"},{"id":53,"name":"Hrabiš Potkanius","title":"Protivný místní politik","is_boss":false,"story":"„Poslouchej, ty… ehm… dobrodruhu. Můj podnik je pojištěný na spoustu peněz. Kdybys ho „vykradl“, nahlásím to jako pojistnou událost. Ty si necháš 25 % z lupu, zbytek je můj. Nikdo se nic nedozví. No?“","choices":{"boj":{"mode":"choice","options":[{"label":"Vykrást podnik silou","outcome":"Lup je tvůj, ale stráže si tě zapamatovaly.","result":"good","karma":-1},{"label":"Udat Potkaniuse strážím","outcome":"Stráže ho zatknou za pojistný podvod. Odměna je menší, ale čistá.","result":"neutral","karma":1}],"orig":"A","text":"Vykradni Potkaniusův podnik silou (a riskuj, že tě stráže chytí)."},"charisma":{"mode":"dice","success":"Potkanius kapituluje a dá ti 50 %. Prý „jsi tvrdý vyjednavač“.","fail":"Potkanius tě vyhodil z kanceláře i s 25 %.","karma":-1,"orig":"B","text":"Přesvědč Potkaniuse, ať ti dá větší podíl než 25 % nebo ať ti poskytne vnitřní plán podniku."},"magie":{"mode":"dice","success":"Rafinovaná loupež! Nikdo tě nepoznal a Potkanius platí.","fail":"Zakopl jsi o vlastní past. Stráže už běží.","orig":"C","text":"Vymysli rafinovaný způsob, jak podnik vykrást, aby to vypadalo jako skutečná loupež a nikdo tě nepoznal."}},"image":"assets/npc/n053.webp","source_file":"grok_image_1777098870920.jpg"},{"id":54,"name":"Hrugor Mostobijec","title":"Obrovský troll mostu","is_boss":false,"story":"(Hrugor bouchne kyjem do mostu, až se celý zatřese, pak se zazubí od ucha k uchu a zařve) „HRRUUUG! Já Hrugor! Temný pán řekl: ‚Zadrž Sira Denise! Znič most! Ať nestihne dvůr!‘ Há ha ha! Ten starý plešoun na koni už tu čeká půl hodiny a křičí. Ty malý! Pomůžeš mi? Nebo chceš, abych tě rozmáčkl jako toho mostu?“","choices":{"boj":{"mode":"choice","options":[{"label":"Pomoct trollovi zbourat most","outcome":"Most padá do řeky, Hrugor tancuje a hodí ti mýtné z celého týdne.","result":"good","karma":-1},{"label":"Rozbít jen zábradlí a tvrdit, že je to hotové","outcome":"Hrugor tvůj podvod nepozná. Sir Denis projede a nadšeně ti mává.","result":"neutral","karma":1}],"orig":"A","text":"Pomoz Hrugorovi úplně zničit most, aby Sir Denis musel jet dlouhou oklikou."},"charisma":{"mode":"dice","success":"Hrugor tě pustí a ještě tě nechá vybrat mýtné od dalšího pocestného.","fail":"Hrugor tě zvedl, zatřásl tebou a hodil do řeky.","orig":"B","text":"Přesvědč Hrugora, ať tě pustí přes most (nebo ho nalákej na větší odměnu od temného pána)."},"magie":{"mode":"dice","success":"Temným pánem je převlečený lichvář! Troll se urazí a jde ho rozmáčknout. Most je volný.","fail":"Troll tvou lest prokoukl a usedl na tebe.","orig":"C","text":"Zjisti, kdo je onen „temný pán“, který trollovi nařídil most blokovat, a vymysli, jak trolla oklamat nebo rychle zneškodnit."}},"image":"assets/npc/n054.webp","source_file":"grok_image_1777195467553.jpg"},{"id":55,"name":"Hugo Kovář","title":"Městský trpasličí kovář","is_boss":false,"story":"Potřebuju pořádnou ocel, ne tyhle hadry, co mi sem nosí. Farunotre doly mají tu nejlepší… ale ty zatracený skřeti a trolové tam teď řádí.","choices":{"boj":{"mode":"dice","success":"Skřeti jsou vyhnáni a žíla je volná. Hugo ti ukove nůž a zaplatí.","fail":"Skřeti tě vyhodili ze šachty v kolečku na rudu.","orig":"A","text":"„V dolech Farunotre se usadili skřeti a ucpali nejlepší žílu. Jdi tam a vyčisti mi cestu – chci čistou ocel, ne šrot z gobliních lebek.“","quest":{"targets":["dul_farunotre"],"goal":"Vyčisti důl Farunotre od skřetů","gp":true}},"charisma":{"mode":"choice","options":[{"label":"Připomenout Brunirovi starý dluh přátelsky","outcome":"Brunir se zasměje, pošle rudu a pozve tě na pivo.","result":"good"},{"label":"Vyhrožovat mu Hugovým kladivem","outcome":"Brunir se urazí a rudu prodá jinému kováři.","result":"bad"}],"orig":"B","text":"„Starý horník Brunir mi dluží sud piva. Přesvědč ho, ať mi pošle první várku čerstvé rudy z nové žíly. Řekni mu, že Hugo Kovář na něj nezapomněl… a že mu uvařím novou sekeru.“"},"magie":{"mode":"dice","success":"Runy jsou rozluštěny a postranní šachta vede přímo k nejlepší oceli.","fail":"Šachta byla zasypaná. Půl dne jsi kopal do kamene.","orig":"C","text":"„Našel jsem starou mapu dolů Farunotre. Ukazuje tajnou postranní šachtu, kde je nejlepší ocel. Pomoz mi rozluštit runy a najít bezpečný způsob, jak se tam dostat bez boje se skřety.“"}},"image":"assets/npc/n055.webp","source_file":"grok_image_1777036463767.jpg"},{"id":56,"name":"Igor Mrkvička","title":"Bratr dědy Levandulína","is_boss":false,"story":"Levandulín mě zase hledá? Ten blázen… Já jsem tady v důchodu! Řekni mu, ať mě nechá na pokoji, mám tu novou známost – je jí teprve sedmdesát!","choices":{"boj":{"mode":"dice","success":"Hrdina, kterého Levandulín poslal, utekl s křikem. Igor ti z vděčnosti hodí groš.","fail":"Ten „hrdina“ byl kovář. Zmlátil tě.","orig":"A","text":"„Můj bratr Levandulín sem určitě pošle někoho, aby mě „zachránil“. Jestli přijde nějaký hrdina, tak ho trochu postraš – ať si nemyslí, že mě jen tak odvede domů!“"},"charisma":{"mode":"choice","options":[{"label":"Vyřídit Levandulínovi pravdu o paní Boženě","outcome":"Levandulín se zaraduje, že bratr žije, a pošle mu svatební dar. Oba ti platí.","result":"good"},{"label":"Říct Levandulínovi, že Igor umřel","outcome":"Děda pláče, pak zapomene a hledá dál. Igor tě proklíná.","result":"bad"}],"orig":"B","text":"„Přesvědč mého bratra Levandulína, ať mě přestane hledat. Řekni mu, že jsem šťastný, mám tu slepici Blanku a novou známost – paní Boženu. A že mu pošlu sud piva, když mě nechá na pokoji.“"},"magie":{"mode":"choice","options":[{"label":"Napsat falešný dopis od krále","outcome":"Levandulín je pyšný na „sira Igora“ a nechá ho být. Igor tleská.","result":"good"},{"label":"Poslat dědovi Igorův portrét se slepicí Blankou","outcome":"Levandulín si myslí, že slepice je Igor. Zmatek pokračuje.","result":"neutral"}],"orig":"C","text":"„Levandulín si pořád plete jména a data. Pomoz mi vymyslet vtipnou zprávu nebo důkaz, že jsem naživu a nechci se vrátit. Něco jako… falešný dopis od krále, že jsem byl pasován na rytíře a musím zůstat v lese.“"}},"image":"assets/npc/n056.webp","source_file":"grok_image_1777039039332.jpg"},{"id":57,"name":"Jimmy Sirotek","title":"Chlapec ze sirotčince na berlích","is_boss":false,"story":"„Bůh žehnej všem lidiškám!“ „Pánové… já dneska ještě nic nejedl… Bůh žehnej, kdybyste měli něco k jídlu…“","choices":{"boj":{"mode":"dice","success":"Pes utekl s kňučením. Jimmy ti žehná a sdílí s tebou svůj poslední drobek.","fail":"Pes tě pokousal. Jimmy tě musel ošetřovat obvazem z rukávu.","karma":1,"orig":"A","text":"Ochraň Jimmyho před velkým vzteklým loveckým psem, který na něj doráží."},"charisma":{"mode":"choice","options":[{"label":"Poprosit pekařku o čerstvý chléb","outcome":"Pekařka dá chléb i koláč. Jimmy září štěstím.","result":"good","karma":1},{"label":"Prostě koupit jídlo za své","outcome":"Jimmy se nají. Ty jsi o něco chudší, ale srdce máš plné.","result":"neutral","karma":1}],"orig":"B","text":"Sežeň Jimmyho něco k jídlu od místních (pečivo, polévku, ovoce) a dones mu to.","quest":{"targets":["village"],"goal":"Sežeň u místních jídlo pro Jimmyho","gp":false}},"magie":{"mode":"dice","success":"Správce sirotčince kradl zásoby. Odhalil jsi ho a děti budou mít co jíst.","fail":"Správce tě vyhodil a pohrozil ti strážemi.","orig":"C","text":"Zjisti, proč v sirotčinci nemají jídlo a pomoz najít způsob, jak tam dovézt zásoby."}},"image":"assets/npc/n057.webp","source_file":"grok_image_1777095932714.jpg"},{"id":58,"name":"Jindra Hříbek","title":"Uprchlý ženich a budoucí spisovatel","is_boss":false,"story":"(Jindra se krčí v křoví, má široce otevřené oči a šeptá zoufale) „Psss! Neřvi tak nahlas! To je táta Mileny... ten blázen na mě mířil vidlemi přímo do zad! Říkal, že jestli si ji nevezmu, tak mě propíchne jako jelena! Já nechci žít na vsi a sekat seno... Já chci cestovat! Chci psát příběhy, vidět svět! Prosím tě, neprozraď mě... nebo mi pomoz utéct!“","choices":{"boj":{"mode":"dice","success":"Táta Mileny je odzbrojený a Jindra uniká. Prý o tobě napíše knihu!","fail":"Vidle tě píchly do zadku. Jindra utekl i bez tebe.","orig":"A","text":"Ochraň Jindru před rozzuřeným tátou Mileny (a případně i dalšími vesničany), kteří ho honí."},"charisma":{"mode":"choice","options":[{"label":"Povzbudit Jindru v útěku","outcome":"Jindra zmizí za obzorem a za rok ti pošle svou první knihu – s věnováním a penězi.","result":"good"},{"label":"Přesvědčit ho, ať se vrátí na svatbu","outcome":"Jindra se vrátí, Milena pláče, táta platí za smír. Jindra je nešťastný.","result":"neutral"}],"orig":"B","text":"Přesvědč Jindru, ať se vrátí na svatbu (nebo ho naopak povzbuď v útěku a pomoz mu zmizet)."},"magie":{"mode":"choice","options":[{"label":"Sehnat mu místo na lodi","outcome":"Jindra odpluje vstříc světu. Milena se mezitím zamilovala do kočího.","result":"good"},{"label":"Převléct ho za babičku","outcome":"Táta Mileny poznal Jindrovy fousy. Honička pokračuje – i s tebou.","result":"bad"}],"orig":"C","text":"Pomoz Jindrovi vymyslet chytrý plán útěku – najdi mu převlek, loď nebo vymysli, jak to celé vysvětlit Mileně, aniž by někdo zemřel."}},"image":"assets/npc/n058.webp","source_file":"grok_image_1777195777282.jpg"},{"id":59,"name":"Josefína Bylinkářka","title":"Vesnická bylinkářka","is_boss":false,"story":"„Dobré ráno, milánku! Potřebuješ něco na bolest hlavy? Nebo na… no víš co? Josefína má na všechno bylinky!“","choices":{"boj":{"mode":"dice","success":"Vlci prchli a zahrádka je zachráněna. Josefína ti dá léčivý čaj.","fail":"Vlci ti ukousli kus pláště a pošlapali bylinky.","karma":1,"orig":"A","text":"Ochraň Josefínu před divokými vlky, kteří jí ničí zahrádku s vzácnými bylinkami."},"charisma":{"mode":"choice","options":[{"label":"Sbírat bylinky za úsvitu","outcome":"Bylinky jsou plné rosy a síly. Speciální čaj tě posílí.","result":"good"},{"label":"Sbírat bylinky o půlnoci","outcome":"Natrhal jsi jedovatý blín. Josefína tě celý den léčí.","result":"bad"}],"orig":"B","text":"Pomoz jí nasbírat vzácné bylinky v nebezpečném lese a ona ti uvaří „speciální posilující čaj“.","quest":{"targets":["forest"],"goal":"Nasbírej vzácné bylinky v nebezpečném lese","gp":false}},"magie":{"mode":"dice","success":"Chybí jen kořen mandragory – a ty ho najdeš. Odvar je dokonalý.","fail":"Mandragora zakřičela a tobě ještě večer zvonilo v uších.","orig":"C","text":"Zjisti recept na její slavný léčivý odvar a pomoz jí najít chybějící ingredienci."}},"image":"assets/npc/n059.webp","source_file":"grok_image_1777105572452.jpg"},{"id":60,"name":"Juseph Loutkář","title":"Starý loutkář s oživlou loutkou","is_boss":false,"story":"„Ach, moje krásná Marioneto… já jsem ti chtěl jen dát život… no… hlavně do postele!“","choices":{"boj":{"mode":"dice","success":"Marionetu jsi zkrotil a svázal provázky. Juseph ti zaplatí z vděčnosti.","fail":"Marioneta tě zmlátila vlastní dřevěnou nohou.","orig":"A","text":"Marioneta se rozzuřila a začala Jusepha mlátit. Pomoz mu ji „uklidnit“ (nebo ji rozmlátit na třísky)."},"charisma":{"mode":"choice","options":[{"label":"Poradit loutce, ať od Jusepha uteče","outcome":"Marioneta odejde do světa a stane se hvězdou divadla. Pošle ti dar.","result":"good","karma":1},{"label":"Přemluvit ji, ať se vrátí k Jusephovi","outcome":"Marioneta se vrátí… a za týden Jusepha znovu zmlátí.","result":"neutral"}],"orig":"B","text":"Přesvědč oživlou loutku, ať se uklidní a vrátí se k Jusephovi (nebo ji přesvědč, ať uteče od starého pervoza)."},"magie":{"mode":"dice","success":"Zakázané kouzlo jsi zrušil. Loutka usíná, Juseph se stydí a platí.","fail":"Kouzlo přeskočilo na tebe. Chvíli se pohybuješ jako loutka.","orig":"C","text":"Zjisti, jak přesně loutka ožila (Juseph použil zakázané kouzlo z prastaré knihy) a pomoz mu to buď zrušit, nebo to ovládnout."}},"image":"assets/npc/n060.webp","source_file":"grok_image_1777096077586.jpg"},{"id":61,"name":"Jíra Stříbrný Tesák","title":"Vlkodlak","is_boss":false,"story":"„Někdy jsem člověk… někdy pes. A někdy mám strašný hlad.“","choices":{"boj":{"mode":"choice","options":[{"label":"Lovce zahnat výstřely do vzduchu","outcome":"Lovci utečou a Jíra ti věnuje stříbrný tesák pro štěstí.","result":"good"},{"label":"Lovce zabít","outcome":"Jíra je volný, ale tvé ruce jsou od krve a ve vesnici se šeptá.","result":"neutral","karma":-1}],"orig":"A","text":"„Lovci mě pronásledují. Zabij je, nebo je zažeň.“"},"charisma":{"mode":"dice","success":"Dívka souhlasila. Setkání v lese bylo… překvapivě romantické.","fail":"Dívka tě nahlásila strážím a Jíra musel uprchnout.","orig":"B","text":"„Přesvědč tu krásnou vesnickou dívku, ať se se mnou setká v lese… i když ví, co jsem.“"},"magie":{"mode":"dice","success":"Amulet je nalezen v ruinách. Jíra se konečně může ovládat.","fail":"Ruiny se zřítily a amulet zmizel v propasti.","orig":"C","text":"„Hledám starý amulet, který mi pomáhá ovládat proměnu. Pomoz mi ho najít v ruinách.“"}},"image":"assets/npc/n061.webp","source_file":"grok_image_1777040507366.jpg"},{"id":62,"name":"Kaelor Větrný","title":"Ptako-humanoid (harpyjí muž)","is_boss":false,"story":"„Ty silný! Ty pohlídat vejce? Já lovit jídlo!“","choices":{"boj":{"mode":"dice","success":"Dravec je zahnán a vejce jsou v bezpečí. Kaelor ti nosí ryby.","fail":"Dravec tě poškrábal a jedno vejce rozbil.","karma":1,"orig":"A","text":"„Velký dravec chce sežrat moje vejce. Ty ho zabít.“"},"charisma":{"mode":"choice","options":[{"label":"Říct družce, že Kaelor celé noci hlídal hnízdo","outcome":"Družka se rozplyne a Kaelor ti dá lesklé peříčko a pár mincí.","result":"good"},{"label":"Říct jí, že Kaelor je nejlepší lovec","outcome":"Družka se směje – Kaelor nic neulovil. Zlobí se na oba.","result":"bad"}],"orig":"B","text":"„Moje družka se na mě zlobí. Ty jí říct, že já dobrý otec.“"},"magie":{"mode":"dice","success":"Kámen je úlomek padlé hvězdy. Kaelor ti ho věnuje za pomoc.","fail":"Kámen ti v ruce zasyčel a popálil ti prsty.","orig":"C","text":"„Starý vítr mi přinesl podivný svítící kámen. Ty pomoct zjistit, co to je.“"}},"image":"assets/npc/n062.webp","source_file":"grok_image_1777024427073.jpg"},{"id":63,"name":"Kapitán Marek Železný","title":"Velitel městské stráže","is_boss":false,"story":"„Vstávej, zločince. V Telgarionu platí zákon. A ten zákon jsem já.“","choices":{"boj":{"mode":"dice","success":"Vzpoura je potlačena. Kapitán ti podá ruku i zlaťáky.","fail":"Vzbouřenci tě shodili do přístavní vody.","orig":"A","text":"Pomoz stráži potlačit vzpouru v přístavu.","quest":{"targets":["sedy_pristav","zlatobreh"],"goal":"Pomoz stráži potlačit vzpouru v přístavu","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Přiznat se a omluvit","outcome":"Kapitán ocení upřímnost a dá ti povolení k nočnímu vstupu.","result":"good","karma":1},{"label":"Vymlouvat se na dvojníka","outcome":"Kapitán se zasměje a pošle tě na noc do šatlavy.","result":"bad"}],"orig":"B","text":"Přesvědč kapitána, aby ti odpustil drobný přestupek (nebo ho přemluv, ať ti dá povolení k nočnímu vstupu do zakázaných čtvrtí)."},"magie":{"mode":"choice","options":[{"label":"Pátrat v kanálech","outcome":"V kanálech najdeš doupě vraha. Případ je uzavřen a odměna tvoje.","result":"good"},{"label":"Pátrat mezi šlechtou","outcome":"Šlechta tě vyhodí a stěžuje si kapitánovi.","result":"bad"}],"orig":"C","text":"Vyřeš případ záhadných vražd, které trápí městskou stráž."}},"image":"assets/npc/n063.webp","source_file":"grok_image_1777110470529.jpg"},{"id":64,"name":"Kapitán Roberto Slim","title":"","is_boss":false,"story":"„Ha! Vítej na palubě, příteli! Jsem Roberto Slim, nejlepší kapitán od Černovodu po Mlžné ostrovy. Hledám odvážné duše, které se nebojí bouře ani pokladu. Co ty?“","choices":{"boj":{"mode":"dice","success":"Nestvůra je zahnána a kapitán ti dá podíl z nákladu.","fail":"Nestvůra tě smetla z paluby. Vylovili tě sítí.","orig":"A","text":"Pomoz kapitánovi odrazit útok mořských pirátů nebo obří mořské nestvůry."},"charisma":{"mode":"dice","success":"Posádka zůstává věrná a kapitán ti slíbí větší podíl.","fail":"Posádka se vzbouřila a ty jsi musel drhnout palubu.","orig":"B","text":"Pomoz mu přesvědčit posádku, aby zůstala loajální (nebo ho přemluv, ať ti dá větší podíl z pokladu)."},"magie":{"mode":"choice","options":[{"label":"Oklamat nepřítele falešnými vlajkami","outcome":"Nepřátelská loď odpluje. Poklad je váš!","result":"good"},{"label":"Plout zkratkou přes útesy","outcome":"Loď narazila na útes. Celá posádka pumpuje vodu.","result":"bad"}],"orig":"C","text":"Najdi na mapě bezpečnou cestu k pokladu nebo vymysli chytrý plán, jak oklamat nepřátelskou loď."}},"image":"assets/npc/n064.webp","source_file":"grok_image_1777131386581.jpg"},{"id":65,"name":"Kapitán Vratislav Řezník","title":"Hrůzostrašný velitel městské stráže","is_boss":false,"story":"„Buď užitečný, nebo zmiz.“","choices":{"boj":{"mode":"dice","success":"Skřetí tábor je vyčištěn. Řezník kývne a hodí ti měšec.","fail":"Skřeti tě zahnali až k městské bráně.","orig":"A","text":"„Skřeti táboří u silnice. Vyčisti je.“"},"charisma":{"mode":"choice","options":[{"label":"Vydírat kupce","outcome":"Kupci platí, Řezník je spokojen a dá ti podíl. Karma klesá.","result":"good","karma":-1},{"label":"Říct kupcům pravdu o vydírání","outcome":"Kupci tě pozvou na pivo. Řezník tě vyhodí z města.","result":"bad","karma":1}],"orig":"B","text":"„Přesvědč kupce, ať zaplatí vyšší „ochranné“ poplatky.“"},"magie":{"mode":"dice","success":"Důkazy jsou jasné: rada Ludovik kradl. Řezník tě odmění.","fail":"Ludovik důkazy spálil dřív, než jsi je našel.","orig":"C","text":"„Najdi důkaz, že rada Ludovik krade z městské pokladny.“"}},"image":"assets/npc/n065.webp","source_file":"grok_image_1777037058683.jpg"},{"id":66,"name":"Kostlivci Poker Club","title":"„Chlapi od stolu“","is_boss":false,"story":"„Hej živý! Chceš si zahrát? Vsadíme duše… nebo aspoň pár zlatých. Ale žádný blefování, my to poznáme – už jsme mrtví, takže máme poker face.“","choices":{"boj":{"mode":"dice","success":"Rozbil jsi oba kostlivce na kosti – a pak je zase poskládal. Hra pokračuje a ty máš výhru.","fail":"Kostlivci se spojili proti tobě. Kosti létají a ty utíkáš.","orig":"A","text":"Vyřeš spor u stolu silou, když jeden kostlivec obviní druhého z podvádění."},"charisma":{"mode":"choice","options":[{"label":"Hrát opatrně a sázet málo","outcome":"Pomalu, ale jistě vyhraješ. Kostlivci ti prozradí tajemství hradu.","result":"good"},{"label":"Vsadit všechno na jednu kartu","outcome":"Prohrál jsi. Kostlivci se chechtají a cvakají čelistmi.","result":"bad"}],"orig":"B","text":"Přidej se ke hře a vyhraj velkou sumu (nebo je přesvědč, ať ti prozradí tajemství hradu)."},"magie":{"mode":"dice","success":"Skrytá kost je nalezena! Podvodník musí zaplatit všem – i tobě.","fail":"Obvinil jsi nevinného kostlivce. Teď tě nenávidí všichni.","orig":"C","text":"Zjisti, kdo z kostlivců podvádí (jeden má skrytou extra kost) a vyřeš to chytře."}},"image":"assets/npc/n066.webp","source_file":"grok_image_1777106062210.jpg"},{"id":67,"name":"Krazzok Bahenní","title":"Lizardfolk válečník","is_boss":false,"story":"„Ssstrach... chutná jako bahno. Já Krazzok. Lovím. Chráním bažiny. Ty pomůžeš, nebo se staneš kořistí?“","choices":{"boj":{"mode":"dice","success":"Dřevorubci prchají z bažin. Krazzok ti daruje šupinový amulet.","fail":"Dřevorubci tě odhodili do bahna. Krazzok syčí smíchy.","orig":"A","text":"Společně odrazit útok lidských dřevorubců, kteří ničí jeho bažiny."},"charisma":{"mode":"choice","options":[{"label":"Navrhnout výměnu ryb za nástroje","outcome":"Vesnice a bažina uzavřou spojenectví. Obě strany ti platí.","result":"good","karma":1},{"label":"Navrhnout, ať vesnice platí bažině daň","outcome":"Vesničané se urazí a Krazzok taky. Nikdo nic.","result":"bad"}],"orig":"B","text":"Přesvědč ho, aby uzavřel spojenectví s nedalekými vesnicemi (nebo ho přemluv, ať tě pustí hlouběji do bažin).","quest":{"targets":["village"],"goal":"Uzavři spojenectví s nedalekými vesnicemi","gp":false}},"magie":{"mode":"dice","success":"Bobři postavili hráz! Rozebral jsi ji a bažiny se znovu zalily.","fail":"Bobři tě pokousali a hráz stojí dál.","orig":"C","text":"Zjisti, proč se bažiny začaly vysoušet a pomoz mu najít zdroj problému."}},"image":"assets/npc/n067.webp","source_file":"grok_image_1777119877226.jpg"},{"id":68,"name":"Krákor Havraní Stín","title":"Temný kenku druid","is_boss":false,"story":"„Les... umírá... (hlas staré ženy) Musíme... přivést temnotu zpět. (hlas umírajícího válečníka) Pomoz mi... nebo zemřeš jako oni.“","choices":{"boj":{"mode":"choice","options":[{"label":"Lovce zahnat a rituál chránit","outcome":"Rituál se dokončí, les potemní. Krákor ti dá havraní pero s mocí.","result":"good","karma":-1},{"label":"Nechat lovce projít","outcome":"Lovci Krákora zaženou. Les je klidný, ale druid ti posílá kletby.","result":"bad","karma":1}],"orig":"A","text":"Bránit rituál před lovci, kteří přišli zabít „ďábelského ptáka“."},"charisma":{"mode":"dice","success":"Krákor změnil plán – místo temnoty povolá ochranné duchy lesa.","fail":"Krákor ti ukradl hlas. Celý den jen krákáš.","karma":1,"orig":"B","text":"Přesvědč ho, aby ti ukradl hlas někoho důležitého (nebo ho přemluv, ať změní svůj plán)."},"magie":{"mode":"dice","success":"Havraní duchové přilétají. Krákor je spokojen a odměňuje tě.","fail":"Duchové tě obklopili a klovali do tebe, dokud jsi neutekl.","karma":-1,"orig":"C","text":"Pomoz mu dokončit rituál volání temných havraních duchů."}},"image":"assets/npc/n068.webp","source_file":"grok_image_1777119927396.jpg"},{"id":69,"name":"Kňour","title":"Sprostý obří jezevec","is_boss":false,"story":"(Kňour zvedne hlavu a zavrčí)\n„No kurva, zase nějakej suchozemskej idiot... Já jsem Kňour.\nUž tři dny mi někdo krade med z úlů. Pomůžeš mi, nebo ti nakopu prdel?“","choices":{"boj":{"mode":"dice","success":"Skřety jsi zmlátil a med je zase Kňourův. „No konečně, kurva.“","fail":"Skřeti tě zmlátili. Kňour se smál, až se zalykal.","orig":"A","text":"Najdi a zmlať medvěda (nebo skřety), kteří mu kradou med."},"charisma":{"mode":"choice","options":[{"label":"Požádat o pomoc včely","outcome":"Včely se zuřivě přidají. Zloději už se nevrátí.","result":"good"},{"label":"Požádat o pomoc lišku","outcome":"Liška slíbí pomoc – a sama ukradne zbytek medu.","result":"bad"}],"orig":"B","text":"Přesvědč lesní zvířata, ať mu pomůžou bránit úly."},"magie":{"mode":"choice","options":[{"label":"Nastražit past s lepkavou pryskyřicí","outcome":"Zloděj se přilepil. Je to opilý goblin. Kňour je nadšený.","result":"good"},{"label":"Nastražit past s jámou","outcome":"Do jámy spadl sám Kňour. Teď tě nenávidí.","result":"bad"}],"orig":"C","text":"Vymysli chytrou past na zloděje medu."}},"image":"assets/npc/n069.webp","source_file":"grok_image_1777246855408.jpg"},{"id":70,"name":"Křesílko Pulec","title":"Starý vesnický vodník","is_boss":false,"story":"„Rudy… můj tlustý kamarád… Kdo mi ho sebral, toho utopím. Pomalu. Ať si stihne uvědomit, co udělal.“","choices":{"boj":{"mode":"dice","success":"Rudy je zpátky ve vodě! Křesílko tě odmění perlou ze dna.","fail":"Rybář Oldřich tě praštil veslem.","orig":"A","text":"„Ten rybář Oldřich mi ukradl Rudyho! Jdi k němu a vezmi mi kapra zpátky. Jestli bude bránit… tak ho stáhni pod vodu. Ale kapra mi přines živého!“","quest":{"targets":["rybniky","rybarska_osada"],"goal":"Vezmi rybáři Oldřichovi kapra Rudyho","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Vyprávět rybáři o nočních vodnických návštěvách","outcome":"Rybář zbledne a kapra vrátí. Vodník ti zaplatí.","result":"good"},{"label":"Nabídnout rybáři výměnou jiného kapra","outcome":"Rybář vezme oba. Křesílko zuří.","result":"bad"}],"orig":"B","text":"„Přesvědč toho rybáře, ať mi Rudyho vrátí. Řekni mu, že jestli ho nevrátí, tak mu každou noc budu tahat nohy z postele a plnit mu boty bahnem… nebo něčím horším.“"},"magie":{"mode":"dice","success":"Rudy je nalezen a vypuštěn bez šrámu. Rybník se uklidní.","fail":"Rudy ti vyklouzl a skočil do studny.","orig":"C","text":"„Rudy má na břiše moje staré znamení. Najdi, kde ho rybář schoval, a vymysli, jak ho dostat ven z kádě, aniž bychom ho zranili. Musí se vrátit domů… jinak se rybník rozzlobí.“"}},"image":"assets/npc/n070.webp","source_file":"grok_image_1777037872250.jpg"},{"id":71,"name":"Křišťálová Koruna „Korunka“","title":"Živoucí Artefakt","is_boss":false,"story":"(Korunka se pomalu otočí ve vzduchu a promluví nadřazeným, lehce hysterickým ženským hlasem)\n„Konečně! Někdo s fungujícím mozkem!\nJá jsem Korunka, Královna Všech Korun a Poslední Pravidlo Zapomenuté Říše.\nPřed tisíci lety mě nějaký debil nasadil na hlavy a já se probudila. Od té doby jsem uvězněná v této zkurvené jeskyni, protože mě nikdo nedokáže pořádně nosit.\nJsi dost hodný? Nebo aspoň dost atraktivní? Pomůžeš mi najít nového nositele... ideálně krále nebo královnu. Nebo aspoň někoho, kdo není totální idiot.“","choices":{"boj":{"mode":"dice","success":"Lovci artefaktů jsou rozprášeni. Korunka ti „milostivě“ děkuje.","fail":"Lovci tě srazili a Korunku málem odnesli.","orig":"A","text":"Ochraň Korunku před bandity / lovci artefaktů, kteří ji chtějí rozbít na suroviny."},"charisma":{"mode":"choice","options":[{"label":"Nabídnout Korunku vdově po starém králi","outcome":"Královna ji nasadí a Korunka konečně ztichne. Platí ti z pokladny.","result":"good"},{"label":"Nabídnout ji ješitnému starostovi","outcome":"Starosta ji nasadí a Korunka na něj ječí. Pak ječí na tebe.","result":"bad"}],"orig":"B","text":"Najdi vhodného nositele (šlechtice, válečníka, politika) a přesvědč ho, aby si Korunku nasadil."},"magie":{"mode":"dice","success":"Kletba je zlomena. Korunka svobodně pluje vzduchem a zpívá.","fail":"Korunka se rozzlobila a nasadila se tobě. Bolí to.","orig":"C","text":"Zjisti, jak Korunku „uklidnit“ a zbavit ji staré kletby, aby mohla svobodně existovat bez potřeby nositele."}},"image":"assets/npc/n071.webp","source_file":"grok_image_1777278725498.jpg"},{"id":72,"name":"Křupavý Křup","title":"Mluvící obří rak","is_boss":false,"story":"„No kurva, ty suchozemská larva! Nechceš si jít se mnou na dno?\nMám tam skvělej úkryt... a pěkně velký kámen, kde se dá schovat ocas.“","choices":{"boj":{"mode":"dice","success":"Vydry jsou vyhnané. Křup ti nadšeně cvaká klepety.","fail":"Vydry tě pokousaly a odnesly ti bačkoru.","orig":"A","text":"Pomoz mi vyhnat vydry, které mi kradou úkryt."},"charisma":{"mode":"choice","options":[{"label":"Zalichotit Křupovi, jaký je chytrý rak","outcome":"Křup ti ukáže poklad utopených obchodníků. Paráda!","result":"good"},{"label":"Vyhrožovat mu hrncem s vroucí vodou","outcome":"Křup tě štípl do nosu a zmizel na dně.","result":"bad"}],"orig":"B","text":"Přesvědč mě, ať ti ukážu, kde je zakopaný poklad utopených obchodníků."},"magie":{"mode":"dice","success":"Nový úkryt pod vodopádem je dokonalý. Křup ti daruje perlu.","fail":"Úkryt se zřítil a Křup tě nazval suchozemskou larvou.","orig":"C","text":"Vymysli, jak mi postavit lepší úkryt, aby mě nikdo nenašel."}},"image":"assets/npc/n072.webp","source_file":"grok_image_1777246637366.jpg"},{"id":73,"name":"Lady Eleonora Zlatoluská","title":"Bohatá městská dáma","is_boss":false,"story":"Ach, milý hrdino… můj manžel se v poslední době chová velmi podezřele. Včera přišel domů vonící levandulí! A on levanduli nesnáší… nebo ano? Už nevím…","choices":{"boj":{"mode":"choice","options":[{"label":"Sledovat manžela potají","outcome":"Manžel chodí do pekařství učit se péct dort k výročí! Eleonora pláče dojetím a platí.","result":"good"},{"label":"Vtrhnout dovnitř se zbraní","outcome":"Vyděsil jsi pekaře i manžela. Dort je na zemi a ty máš ostudu.","result":"bad"}],"orig":"A","text":"„Můj manžel se dnes večer chystá „na schůzku s obchodními partnery“. Sleduj ho a jestli uvidíš nějakou lehkou ženštinu, tak ji… no… postraš svou zbraní! Ale ať to nevypadá, že jsem žárlivá!“"},"charisma":{"mode":"dice","success":"Manžel se přiznal: tajně se učí tančit, aby Eleonoru překvapil.","fail":"Manžel tě prokoukl a nechal tě vyhodit sluhy.","orig":"B","text":"„Přesvědč mého manžela, ať mi řekne pravdu, kam chodí každý čtvrtek večer. Můžeš mu nalhat, že jsi jeho dávný kamarád z mládí, nebo že máš pro něj výhodnou nabídku… hlavně ať se přizná!“"},"magie":{"mode":"dice","success":"Adresa patří levandulové zahradě, kde manžel pěstuje květiny pro ni. Odměna!","fail":"Na adrese byl nevěstinec. A ty tam vešel. A někdo tě viděl.","orig":"C","text":"„Našla jsem v jeho kapse lístek s adresou a srdíčkem. Pomoz mi zjistit, co tam přesně je. Ať už je to nevěstinec, nebo… pekařství. Já už tomu nerozumím!“"}},"image":"assets/npc/n073.webp","source_file":"grok_image_1777038649983.jpg"},{"id":74,"name":"Lady Elowen Zrádná","title":"Manipulativní šlechtična","is_boss":false,"story":"„Všichni mají nějaké tajemství. Já jen pomáhám, aby se dostalo na světlo.“","choices":{"boj":{"mode":"choice","options":[{"label":"Kapitána zabít","outcome":"Lady Elowen platí zlatem. Na tvých rukou ulpí krev.","result":"good","karma":-1},{"label":"Kapitána varovat","outcome":"Kapitán uteče a odmění tě. Lady Elowen tě teď nenávidí.","result":"neutral","karma":1}],"orig":"A","text":"„Můj manžel má nepříjemného strážného kapitána. Postarej se o něj.“"},"charisma":{"mode":"dice","success":"Manžel podepsal. Lady Elowen se usměje a zaplatí.","fail":"Manžel tě prohlédl a nechal tě vyhodit z paláce.","karma":-1,"orig":"B","text":"„Přesvědč mého manžela, ať podepíše novou závěť... ve můj prospěch.“"},"magie":{"mode":"dice","success":"Dopis je dokonale upraven. Rodina je zachráněna – nebo spíš Elowen.","fail":"Inkoust se rozmazal a tvé jméno je teď v dopise taky.","karma":-1,"orig":"C","text":"„Našla jsem starý dopis, který by mohl zničit mou rodinu. Pomoz mi ho upravit.“"}},"image":"assets/npc/n074.webp","source_file":"grok_image_1777031278854.jpg"},{"id":75,"name":"Lady Violetta von Melounová","title":"Arogantní šlechtična","is_boss":false,"story":"„Ach, ty silný hrdino... nebo hrdinko? Je mi to jedno. Pojď, nudím se.“","choices":{"boj":{"mode":"dice","success":"Kanec padl a ty jsi u toho vypadal úžasně. Violetta ti hodí zlatý prsten.","fail":"Kanec tě převálcoval přes růžový záhon. Violetta se nudí ještě víc.","orig":"A","text":"„Na mém panství řádí divoký kanec a ničí mi růže. Ulov ho – ale ať u toho vypadáš dobře!“"},"charisma":{"mode":"choice","options":[{"label":"Zostudit hraběnku vtipem na plese","outcome":"Celý sál se směje a hraběnka se omluví. Violetta je nadšená.","result":"good"},{"label":"Napsat hraběnce výhrůžný dopis","outcome":"Hraběnka dopis ukáže strážím a obě dámy tě vyhodí.","result":"bad"}],"orig":"B","text":"„Na plese mě urazila hraběnka Rozálie. Zařiď, ať se mi omluví – veřejně a na kolenou.“"},"magie":{"mode":"dice","success":"Ohňostroj z kouzelných světlušek! Violetta poprvé za rok tleská.","fail":"Kouzlo vybuchlo Violettě do paruky. Už se nenudí, ale zuří.","orig":"C","text":"„Nudím se k smrti. Vymysli pro mě zábavu, jakou ještě nikdo neviděl – a ať je trochu kouzelná.“"}},"image":"assets/npc/n075.webp","source_file":"grok_image_1777024782960.jpg"},{"id":76,"name":"Lilith Inferna","title":"Svůdná Tieflingka","is_boss":false,"story":"„Ach, milý smrtelníku… co bys dal za jednu noc se mnou? Nebo radši za dvě?“","choices":{"boj":{"mode":"dice","success":"Lovce démonů jsi zahnal. Lilith tě políbí na čelo – pálí to jako oheň.","fail":"Lovec tě postříkal svěcenou vodou. Pálilo to víc než Lilith.","karma":-1,"orig":"A","text":"„Jde mi po krku pekelný lovec démonů. Zbav mě ho… a já tě odměním. Osobně.“"},"charisma":{"mode":"choice","options":[{"label":"Lhát knězi, že je Lilith poutnice","outcome":"Kněz ji pustí dovnitř. Slavnost je… nezapomenutelná. Lilith platí.","result":"good","karma":-1},{"label":"Říct knězi pravdu","outcome":"Kněz Lilith vyžene. Ta se urazí, ale nechá tě být.","result":"neutral","karma":1}],"orig":"B","text":"„Přesvědč místního kněze, ať mě pustí na posvátnou slavnost. Chci tam trochu… rozproudit krev.“"},"magie":{"mode":"dice","success":"Runy jsou rozluštěny. Lilith zůstává a štědře se odvděčí.","fail":"Runy tě spálily a Lilith se smála.","orig":"C","text":"„Pekelná pouta mě drží v tomhle světě jen do úplňku. Pomoz mi rozluštit runy na mém rohu, ať tu můžu zůstat.“"}},"image":"assets/npc/n076.webp","source_file":"grok_image_1777040330146.jpg"},{"id":77,"name":"Lirael „Melounová“ Hazardka","title":"Opilá elfí hazardní kráska","is_boss":false,"story":"„No konečně někdo, kdo vypadá... zajímavě. Hraju o pořádné prachy, zlato... a občas i o něco jiného. Rukta mi hlídá, aby nikdo nepodváděl. Chceš si zahrát? Nebo... chceš si zahrát se mnou?“","choices":{"boj":{"mode":"dice","success":"Rvačku jste s Ruktou vyhrály! Lirael ti nalije a hodí ti podíl z banku.","fail":"Rukta omylem praštila tebe. Pak všichni ostatní taky.","orig":"A","text":"Někdo u stolu obviní Lirael z podvádění → Rukta se rozčílí a začne rvačku. Pomoz jí (nebo jim) vyhrát bitku."},"charisma":{"mode":"choice","options":[{"label":"Flirtovat a sázet střídmě","outcome":"Lirael tě pozve do soukromí a prozradí tajemství pokladu.","result":"good"},{"label":"Sázet všechno a pít s ní","outcome":"Probudíš se pod stolem bez peněz a s melounem na hlavě.","result":"bad"}],"orig":"B","text":"Přisedni si, zahraj si s ní kostky a flirtuj. Můžeš ji přesvědčit, aby ti prozradila tajemství (nebo ti dala „soukromou odměnu“ za výhru)."},"magie":{"mode":"choice","options":[{"label":"Krýt ji a vzít si podíl","outcome":"Lirael s tebou dělí výhru. Karma se mračí.","result":"good","karma":-1},{"label":"Konfrontovat ji potichu","outcome":"Lirael se zasměje, přizná se a nabídne férovou dohodu.","result":"good"}],"orig":"C","text":"Zjisti, že Lirael skutečně lehce podvádí (má v rukávu speciální kostky) a buď ji kryj, nebo ji konfrontuj a domluv se na výhodné dohodě."}},"image":"assets/npc/n077.webp","source_file":"grok_image_1777120396867.jpg"},{"id":78,"name":"Lord Bedřich z Chudobova","title":"Zchudlý šlechtic s parukou","is_boss":false,"story":"Ach, milostivá... tedy... vážený hrdino! Dostal jsem na budku, protože jsem se dvořil manželce hostinského. Zachraňte mou důstojnost!","choices":{"boj":{"mode":"dice","success":"Hostinský dostal lekci a paruka je pomstěna. Bedřich ti platí posledními groši.","fail":"Hostinský praštil i tebe. Teď máte budku oba.","orig":"A","text":"Ten hromotluk hostinský mě praštil, protože jsem jeho ženě řekl, že má oči jako hvězdy. Jdi tam a pomsti mou čest! Nebo aspoň mou paruku."},"charisma":{"mode":"choice","options":[{"label":"Pochválit vdově její smích","outcome":"Vdova se usměje a dá Bedřichovi druhou šanci. Pivo je na ni!","result":"good"},{"label":"Pochválit vdově Bedřichovu paruku","outcome":"Vdova se rozesměje tak, že Bedřich uteče. Ostuda pro oba.","result":"bad"}],"orig":"B","text":"Ta krásná vdova u vedlejšího stolu mě odmítla. Přesvědč ji, ať mi dá ještě jednu šanci... nebo aspoň další pivo na účet."},"magie":{"mode":"dice","success":"Prsten ležel v kaluži piva pod lavicí. Bedřich tě objímá.","fail":"Opilec prsten zastavil dřív, než jsi ho našel.","orig":"C","text":"Ztratil jsem svůj rodový prsten někde pod stolem v krčmě. Pomoz mi ho najít, než ho ten opilec použije jako zástavu za další rundu!"}},"image":"assets/npc/n078.webp","source_file":"grok_image_1777032986884.jpg"},{"id":79,"name":"Lord Efolka Hubička","title":"Šmrncovní vysoký lord","is_boss":false,"story":"(Lord Hubička se zastaví, opře se o hůl a lehce se ukloní s dramatickým gestem) „Ach, milý příteli! Já jsem lord Efolka Hubička, největší znalec etikety a dobrého vkusu v celém Telgarionu. Dnes večer se koná velký bál u dvora... a já mám důvodné podezření, že se mě někdo hodlá pokusit otrávit. Potřebuji spolehlivého a diskrétního ochránce, který mě doprovodí. Samozřejmě... za tučnou finanční odměnu.“","choices":{"boj":{"mode":"dice","success":"Vrah s dýkou je zneškodněn. Lord Hubička ti tleská rukavičkami.","fail":"Útočník tě pobodal a lord omdlel do dortu.","orig":"A","text":"Chránit lorda Hubičku během bálu, pokud se někdo pokusí o přímý útok (nebo ho dostat živého ven, když se situace zhorší)."},"charisma":{"mode":"choice","options":[{"label":"Sledovat sluhu s vínem","outcome":"Sluha přisypává jed! Zastavíš ho a lord ti tučně zaplatí.","result":"good"},{"label":"Sledovat podezřelou hraběnku","outcome":"Hraběnka tě nařkne z obtěžování. Mezitím lord kašle nad pohárem.","result":"bad"}],"orig":"B","text":"Pomoz mu společensky – sleduj podezřelé hosty, odhaluj intriky a pomoz mu udržet si tvář mezi šlechtou."},"magie":{"mode":"dice","success":"Důkaz je jasný: travičem je lordův bratranec. Hubička zachráněn!","fail":"Obvinil jsi nevinného barona. Bál skončil skandálem.","orig":"C","text":"Zjisti, kdo ho chce otrávit (který šlechtic, sluha nebo konkurent) a buď mu zabraň v plánu, nebo najdi důkaz."}},"image":"assets/npc/n079.webp","source_file":"grok_image_1777194118270.jpg"},{"id":80,"name":"Lord Suchoprst","title":"Nadržený šlechtic","is_boss":false,"story":"„No konečně někdo zajímavý! Povídejte, milý příteli... nebo přítelkyně?“","choices":{"boj":{"mode":"dice","success":"Bandité jsou pryč. Suchoprst platí a přitom tě nepříjemně plácá po zádech.","fail":"Bandité tě svlékli do spodků. Suchoprst se pobaveně usmívá.","orig":"A","text":"„Bandité mi rabují karavany. Zlikvidujte je.“"},"charisma":{"mode":"choice","options":[{"label":"Koupit manželce kytici jménem lorda","outcome":"Manželka se uklidní a lord ti zaplatí.","result":"good"},{"label":"Říct manželce, že lord je nevinný jako beránek","outcome":"Manželka se rozesměje a vyhodí vás oba.","result":"bad"}],"orig":"B","text":"„Moje manželka je velmi žárlivá. Pomozte mi ji... uklidnit.“"},"magie":{"mode":"dice","success":"Kronika ukrývá mapu k rodovému pokladu. Suchoprst se dělí.","fail":"Kronika se rozpadla v prach. Lord pláče.","orig":"C","text":"„Našel jsem starou rodinnou kroniku v tajné komnatě. Pomozte mi ji rozluštit.“"}},"image":"assets/npc/n080.webp","source_file":"grok_image_1777023685195.jpg"},{"id":81,"name":"Ludo „Šibeniční Šprýmař“","title":"Mladý zločinec na oprátce","is_boss":false,"story":"(Ludo se široce usměje, i když mu oprátka tlačí na krk, a mrkne na tebe)\n„No nazdar, kámo! Vidím, že jsi přišel na moje poslední představení.\nJo jo, dneska mě konečně pověsí... už potřetí letos.\nAle než mě tihle plechovkáři pošlou nahoru za mým dědou, mám pro tebe tři poslední přání.\nUděláš je pro mě? Nebo chceš, abych ti tady před smrtí ještě vynadal?“","choices":{"boj":{"mode":"choice","options":[{"label":"Rozpoutat rebelii","outcome":"V chaosu Ludo uteče a hodí ti ukradený měšec. Rytíři tě hledají.","result":"good","karma":-1},{"label":"Nechat to být","outcome":"Ludo visí a mává ti. Rytíři ti dají odměnu za klid.","result":"neutral"}],"orig":"A","text":"Jestli mi pomůžeš se těch rytířů zbavit... no, pak bych ti možná ještě mohl utéct. Co říkáš na malou rebelii?"},"charisma":{"mode":"dice","success":"Matka se dozví, že syn „zemřel jako hrdina“, a prsten najde pod lípou. Pláče a žehná ti.","fail":"Matka ti nevěřila a vyhnala tě koštětem.","karma":1,"orig":"B","text":"Běž do vesnice Křivý Dub a řekni mojí matce, že jsem umřel jako hrdina... a že ten prsten, co jsem jí ukradl, je zakopaný pod starou lípou. Ať se nezlobí.","quest":{"targets":["village"],"goal":"Vyřiď matce vzkaz a řekni jí o zakopaném prstenu","gp":false}},"magie":{"mode":"choice","options":[{"label":"Dát Jirkovi nůž a říct mu pravdu","outcome":"Jirka nůž odloží a jde se učit kovářem. Lepší než bratr!","result":"good","karma":1},{"label":"Dát Jirkovi nůž a vyprávět o hrdinovi Ludovi","outcome":"Jirka chce být jako Ludo. Za týden krade první slepici.","result":"neutral"}],"orig":"C","text":"Můj mladší bratr Jirka si myslí, že jsem hrdina. Najdi ho a řekni mu, ať se nestane zlodějem jako já... nebo ať je aspoň lepší než já. A dej mu tenhle nůž – byl můj nejoblíbenější."}},"image":"assets/npc/n081.webp","source_file":"grok_image_1777244213506.jpg"},{"id":82,"name":"Lída „Plamenná“ Rudovlasá","title":"Drzá hospodská servírka","is_boss":false,"story":"„Hej ty... dlouhánku. Celou noc tě pozoruju a říkám si – tenhle by mi dneska mohl pořádně prohřát krb.\nUž měsíc mi nikdo nenaplnil sud pořádně a já už jsem pěkně vyschlá.\nTak co? Pomůžeš mi dneska v noci zatopit pořádným plamenem?\nNebo se bojíš, že tě obyčejná hospodská holka udolá?“","choices":{"boj":{"mode":"dice","success":"Vydržel jsi celý tanec! Lída je nadšená a večeře je na ni.","fail":"Lída tě utancovala. Ráno se probouzíš u krbu bez bot.","orig":"A","text":"„Tak pojď, ty siláku! Ukaž mi, jak pevný máš meč a jak dlouho vydržíš v tom nejtvrdším tanci!“"},"charisma":{"mode":"choice","options":[{"label":"Lichotit jí celý večer","outcome":"Lída září a nabídne ti pokoj zdarma i sud medoviny.","result":"good"},{"label":"Říct jí, že má dnes hezkou kamarádku","outcome":"Lída tě polije pivem a vyhodí ven.","result":"bad"}],"orig":"B","text":"Přesvědč Lídu, ať ti dovolí víc než jen jednu „rundu u krbu“ (nebo ji uspokoj tak, aby byla opravdu spokojená a ještě ti něco extra nabídla)."},"magie":{"mode":"dice","success":"Hádanka i ukázka zabraly – Lída tleská a dá ti speciální bonus.","fail":"Tvá hádanka byla tak trapná, že Lída zívla a odešla.","orig":"C","text":"Vymysli chytrý a kreativní způsob, jak ji „zatopit“ (hádanka + praktická ukázka), aby byla nadšená a dala ti speciální bonus."}},"image":"assets/npc/n082.webp","source_file":"grok_image_1777203641271.jpg"},{"id":83,"name":"Lína Zlatovlasá","title":"Vesnická kráska s copem","is_boss":false,"story":"„No nazdar, cizince… Vidím, že máš pořádný… nástroj. Co kdybys mi ho ukázal trochu blíž? Tady na vsi je taková nuda… potřebuju pořádnýho chlapa, co umí pořádně… pracovat.“","choices":{"boj":{"mode":"dice","success":"Kůň je zkrocen! Lína je nadšená a pozve tě na večeři.","fail":"Kůň tě vyhodil ze stodoly přímo do hnoje.","orig":"A","text":"„Ten můj starý kůň je tak divoký a nezkrotný… Pojď ho zkrotit v stodole, ať mě pak můžeš pořádně projet.“"},"charisma":{"mode":"choice","options":[{"label":"Opravdu zalévat meloun","outcome":"Meloun je obří a šťavnatý. Lína ti dá ochutnat… a pár zlaťáků.","result":"good"},{"label":"Zalévat ji vtipy","outcome":"Lína se urazí a pošle na tebe psa.","result":"bad"}],"orig":"B","text":"„Mám takovou velkou, šťavnatou melounovou zahrádku… ale sama ji nedokážu pořádně… zavlažit. Pomůžeš mi s tím? Slibím, že ti dám ochutnat, co jsem vypěstovala.“"},"magie":{"mode":"dice","success":"Klíč byl v kozím chlévě. Truhla zaskřípe a v ní je dědečkův poklad.","fail":"Truhla ti přiskřípla prsty.","orig":"C","text":"„Na půdě mám starou velkou truhlu, která už dlouho nebyla pořádně otevřená a prozkoumaná… Najdi klíč a ukaž mi, jak se s ní zachází, ať konečně… zaskřípe.“"}},"image":"assets/npc/n083.webp","source_file":"grok_image_1777103123450.jpg"},{"id":84,"name":"Martigan Šupinatý","title":"Chamtivý koboldský horník","is_boss":false,"story":"„Sssstoj! Ty velký! Já Martigan. Tady v šachtě je moc dobrý kov… ale další chodba… tam je horko jako v pekle a něco tam sssítá. Ty mě ochráníš, jo? Já ti dám kus vzácnýho kovu! Sslibuju!“","choices":{"boj":{"mode":"dice","success":"Lávové elementály jsi zahnal a Martigan ti dá kus vzácného kovu.","fail":"Ohnivá krysa ti zapálila kalhoty.","orig":"A","text":"Probojuj se s Martiganem do horké chodby plné lávových elementálů, ohnivých krys a padajících skal."},"charisma":{"mode":"choice","options":[{"label":"Požádat ho o polovinu kovu","outcome":"Martigan syčí, ale souhlasí. Férová dohoda.","result":"good"},{"label":"Požádat ho o všechno","outcome":"Martigan se urazí, zmizí v tunelu a nechá tě ve tmě.","result":"bad"}],"orig":"B","text":"Přesvědč Martigana, ať ti prozradí, kolik vzácného kovu tam opravdu je, a domluvte se na férovém podílu."},"magie":{"mode":"dice","success":"Odklonil jsi pramen a chodba se ochladila. Kov je váš!","fail":"Pramen zaplavil šachtu a vyplavil tě ven.","orig":"C","text":"Prostuduj staré důlní mapy, najdi bezpečnější cestu nebo způsob, jak ochladit chodbu (odkloněním podzemního pramene)."}},"image":"assets/npc/n084.webp","source_file":"grok_image_1777099512243.jpg"},{"id":85,"name":"Maruška „Liška“","title":"Vesnická drbna a zvědkyně","is_boss":false,"story":"„No nazdar, cizince... Ty jsi ten nový, co? Tak poslouchej. Vím, proč bratr Anselm tak běhá. Vím, kdo krade vodu ze studny. A vím i to, co se děje v hospodě každou středu v noci. Chceš drby? Nebo chceš, abych ti řekla, kdo tady ve vesnici doopravdy tahá za nitky?“","choices":{"boj":{"mode":"choice","options":[{"label":"Pomlouvače zastrašit","outcome":"Pomlouvač zmlkne. Maruška ti prozradí, kdo krade vodu.","result":"good"},{"label":"Pomlouvače zmlátit","outcome":"Pomlouvač má bratra kováře. Teď jsi pomluvený i zmlácený.","result":"bad"}],"orig":"A","text":"Pomoz jí „zajistit“, aby jeden z vesničanů přestal šířit drby o ní samotné."},"charisma":{"mode":"dice","success":"Výměna drbů! Víš, kdo tahá za nitky, a Maruška ti dá i tip na schovaný poklad.","fail":"Maruška tvé novinky roztroubila – včetně těch o tobě.","orig":"B","text":"Vyměň si s ní informace – ona ti prozradí tajemství vesnice a ty jí dáš novinky zvenčí."},"magie":{"mode":"dice","success":"Vodu krade starostův syn kvůli nelegální palírně. Anselm i vesnice děkují.","fail":"Obvinil jsi nevinnou kozu. Maruška to roztroubila.","orig":"C","text":"Zjisti, kdo skutečně krade vodu a jak to souvisí s Anselmovým plánem shromáždění."}},"image":"assets/npc/n085.webp","source_file":"grok_image_1777121999309.jpg"},{"id":86,"name":"Milena Kopřivová","title":"Baculatá zrzavá nevěsta","is_boss":false,"story":"(Milena hlasitě vzlyká, pak tě uvidí a rozběhne se k tobě s uplakaným obličejem) „On utekl! Ten zrádce Jindra Hříbek utekl od oltáře! Táta na něj jen trochu namířil vidle... a on hned zdrhnul jako králík! Prosím tě, najdi mi toho parchanta a doveď ho zpátky! Klidně ho svaž, prašti nebo ho táhni za vlasy! Já si ho vezmu, i kdyby ho musela dotáhnout za nohu!“","choices":{"boj":{"mode":"choice","options":[{"label":"Jindru najít a odtáhnout k oltáři","outcome":"Svatba se koná. Milena je šťastná, Jindra ne. Táta ti platí.","result":"good"},{"label":"Jindru najít a nechat ho utéct","outcome":"Milena tě proklíná, ale Jindra ti pošle peníze z cest.","result":"neutral"}],"orig":"A","text":"Najdi Jindru (schovává se v lese nebo na půdě) a „přesvědč“ ho násilím, ať se vrátí na svatbu.","quest":{"targets":["forest"],"goal":"Najdi Jindru a přiveď ho zpět na svatbu","gp":false}},"charisma":{"mode":"dice","success":"Milena pochopila, že si zaslouží lepšího ženicha. Hned si všimne kočího.","fail":"Milena tě praštila kyticí. Pořádně.","orig":"B","text":"Přesvědč Jindru, aby se vrátil dobrovolně (nebo Milenu, ať ho nechá utéct a najde si lepšího ženicha)."},"magie":{"mode":"dice","success":"Jindra má dluhy u lichváře! Zaplatil jsi je z jeho věna a svatba se koná v klidu.","fail":"Pletl ses do toho tak, že teď oba chtějí, abys je oddal ty.","orig":"C","text":"Zjisti, proč Jindra utekl (má obrovské dluhy, bojí se tchána, nebo má jinou milenku) a vyřeš situaci chytře."}},"image":"assets/npc/n086.webp","source_file":"grok_image_1777133029640.jpg"},{"id":87,"name":"Mladý král Filip Degrill","title":"Ambiciózní panovník","is_boss":false,"story":"„Můj bratr ve vězení je poslední překážka. Postarej se o něj… ať už jakkoli. Koruna musí zůstat v mé linii – pro mě a mé děti.“","choices":{"boj":{"mode":"choice","options":[{"label":"Bratra zavraždit","outcome":"Mladý král platí zlatem. Království má krále, ty máš krev na rukou.","result":"good","karma":-1},{"label":"Bratra potají osvobodit","outcome":"Bratr uteče do exilu a odmění tě. Král tě začne hledat.","result":"neutral","karma":1}],"orig":"A","text":"Vnikni do vězení v jiném městě a zavraždi králova bratra."},"charisma":{"mode":"dice","success":"„Nehoda“ proběhla dokonale. Král se usměje a zaplatí.","fail":"Stráže tě prokoukly a zmlátily tě.","karma":-1,"orig":"B","text":"Přesvědč vězeňské stráže nebo samotného bratra, aby „nešťastná nehoda“ vypadala jako sebevražda."},"magie":{"mode":"dice","success":"Fingovaná poprava! Bratr žije v exilu a král si myslí, že je mrtvý.","fail":"Plán se prozradil a král tě vyhodil ze dvora.","karma":1,"orig":"C","text":"Vymysli a proveď rafinovaný plán (jed, podvrh, nebo fingovanou popravu), aby nikdo nepoznal, kdo za tím stojí."}},"image":"assets/npc/n087.webp","source_file":"grok_image_1777096587323.jpg"},{"id":88,"name":"Mojmír Hamprdlajs","title":"Nervózní obchodník","is_boss":false,"story":"„Ach bože, ach běda! Právě teď se mi rozbilo kolo! V tomhle kočáře mám zboží za tisíce zlatých - perské koberce, dračí porcelán, hedvábí z dalekých zemí... Jestli to do rána neopravíme, přijdou lupiči a všechno mi seberou! Prosím, pomozte mi, dobrý člověče! Zaplatím... zaplatím štědře!“","choices":{"boj":{"mode":"dice","success":"Lupiči jsou zahnáni a Mojmír ti nadšeně platí.","fail":"Lupiči tě svázali a vzali ti boty.","karma":1,"orig":"A","text":"Bránit kočár před bandou lupičů, kteří ucítili snadnou kořist."},"charisma":{"mode":"choice","options":[{"label":"Sehnat kolaře z vesnice","outcome":"Kolař kolo opraví do rána. Mojmír ti platí i kus hedvábí.","result":"good"},{"label":"Vzít kolo z opuštěného vozu","outcome":"Kolo nepasuje. Kočár se zhroutí do příkopu.","result":"bad"}],"orig":"B","text":"Sežeň v okolní vesnici nebo od kolemjdoucích pomocníky a materiál na opravu kola (nebo přesvědč Mojmíra, ať ti dá větší odměnu)."},"magie":{"mode":"dice","success":"Provizorní kolo z větví drží! Kočár dojede do města.","fail":"Kolo se rozpadlo a dračí porcelán s ním.","orig":"C","text":"Rychle oprav kolo provizorním způsobem (nebo vymysli, jak kočár schovat a ochránit zboží do rána)."}},"image":"assets/npc/n088.webp","source_file":"grok_image_1777120559120.jpg"},{"id":89,"name":"Morwenna Třioká","title":"Čarodějnice z Černého vrchu","is_boss":false,"story":"„Dvěma očima vidím svět. Třetím vidím, co lidé skrývají.“","choices":{"boj":{"mode":"dice","success":"Bahenní elementál je rozprsklý po celém vrchu. Morwenna ti zaplatí stříbrem.","fail":"Elementál tě spolkl a vyplivl. Smrdíš ještě týden.","orig":"A","text":"„Můj bahenní elementál se vymkl kontrole. Znič ho.“"},"charisma":{"mode":"choice","options":[{"label":"Představit Morwennu jako léčitelku","outcome":"Lord ji přijme a uzavře s ní smír. Morwenna ti děkuje třetím okem.","result":"good"},{"label":"Představit ji jako mocnou spojenkyni proti nepřátelům","outcome":"Lord se vyděsí a nechá vás oba vyhodit.","result":"bad"}],"orig":"B","text":"„Dostaň mě na audienci k lordovi a přesvědč ho, že nejsem hrozba.“"},"magie":{"mode":"dice","success":"Duch starého krále promluvil a Morwenna se dozvěděla tajemství. Platí ti.","fail":"Duch se rozzlobil a strašil tě celou noc.","orig":"C","text":"„Pomoz mi vyvolat ducha starého krále – potřebuji se ho zeptat na jedno tajemství.“"}},"image":"assets/npc/n089.webp","source_file":"grok_image_1777023216437.jpg"},{"id":90,"name":"Mág Čaryfuk Hvězdný","title":"Srandovní čaroděj s hvězdami","is_boss":false,"story":"Přemluv toho malýho blba! Říkám mu už dvě hodiny, ať to hodí do lávy, a on pořád brečí, že je to „jeho poklad“! No tak už to tam šupni, Frodo... ehm... Františku!","choices":{"boj":{"mode":"choice","options":[{"label":"Chytit gnoma a vytrhnout mu prstýnek","outcome":"Prstýnek letí do lávy. Svět je zachráněn a Čaryfuk tleská.","result":"good"},{"label":"Honit gnoma kolem sopky","outcome":"Gnom je rychlejší. Uklouzl jsi a spálil si zadek.","result":"bad"}],"orig":"A","text":"Ten malý gnome se zbláznil a nechce prstýnek pustit! Chyť ho, vytrhni mu ho a hoď ho do lávy, než se z něj stane další temný pán!"},"charisma":{"mode":"dice","success":"Gnom prstýnek hodil do lávy. Dostane medaili a ty odměnu.","fail":"Gnom se rozbrečel a utekl i s prstýnkem.","karma":1,"orig":"B","text":"Přesvědč toho kudrnatýho gnoma, ať prstýnek dobrovolně hodí. Řekni mu, že bude hrdina, že dostane medaili, nový klobouk... cokoliv! Jen ať to tam šoupne!","text_female":"„Řekni mu, že dostane nekonečné zásoby čokolády a nové kudrnaté boty, když to tam hodí. A že mu uvařím ten nejlepší lektvar na vousy... ehm, na vlasy!“"},"magie":{"mode":"dice","success":"Lest vyšla – prstýnek letí do lávy a gnom ani nemrkne.","fail":"Gnom tvou lest prokoukl a kousl tě do prstu.","orig":"C","text":"Ten prstýnek je prokletý. Pomoz mi vymyslet chytrý trik, jak gnoma přesvědčit – třeba mu slíbím nekonečné zásoby piva, nebo mu ukradnu prstýnek lstí a hodím ho sám."}},"image":"assets/npc/n090.webp","source_file":"grok_image_1777035570300.jpg"},{"id":91,"name":"Měsíční Lída","title":"Modrá rusalka","is_boss":false,"story":"(Lída se pomalu otočí, voda jí stéká po těle, usměje se sladce a promluví sametovým hlasem)\n„Konečně... už jsem si myslela, že dneska budu muset koupat se sama.\nPojď ke mně, hezký... voda je teplá a já jsem taková osamělá.\nNechceš mi pomoct umýt záda? Nebo... můžu ti ukázat, jak se rusalky koupou s muži.\nMám ráda, když mě držíš pod vodou... hodně dlouho.\nNěkdy se stane, že se pak už nevynoříš... ale to je přece součást zábavy, ne?“","choices":{"boj":{"mode":"dice","success":"Chytil jsi ji! Rusalka je ohromená a daruje ti perlu z hlubin.","fail":"Lída tě držela pod vodou příliš dlouho. Vylezl jsi napůl utopený.","orig":"A","text":"„Tak pojď dál, chyť mě... jestli mě chytíš, ukážu ti něco opravdu speciálního.“ (nebezpečná hra ve vodě)"},"charisma":{"mode":"choice","options":[{"label":"Mazlit se jen na mělčině","outcome":"Lída se zasměje, že jsi chytrý. Dá ti polibek a mušli plnou zlaťáků.","result":"good"},{"label":"Nechat se zatáhnout do hloubky","outcome":"Probudil ses na břehu, bez dechu a bez měšce.","result":"bad"}],"orig":"B","text":"„Pojď, pojď... necháš se se mnou trochu pomazlit... slibuju, že tě nechám dýchat. Občas.“"},"magie":{"mode":"choice","options":[{"label":"Přesvědčit ji, ať muže jen straší, ne topí","outcome":"Lída se stane hodnější rusalkou. Vesnice ti děkuje.","result":"good","karma":1},{"label":"Uspokojit ji a nic neřešit","outcome":"Ráno odcházíš unavený. Další muž se ale večer neutopí… zatím.","result":"neutral"}],"orig":"C","text":"Zjistíš, že Lída už „zkoupala“ několik mužů, kteří se nikdy nevrátili, a rozhodneš se, jestli ji uspokojíš, nebo z ní uděláš bezpečnější rusalku."}},"image":"assets/npc/n091.webp","source_file":"grok_image_1777280578624.jpg"},{"id":92,"name":"Pablito Bleskobijec","title":"Bouřkový rváč","is_boss":false,"story":"(Bleskobijec stojí s nohama rozkročenýma, celý promočený, a řve proti nebi) „No tak pojď sem, ty mrcho nebeská!!! Jednu ránu! Jen to zkus! Bleskobijec se nebojí! Pojď sem, ty svině mraková!!!“ (otočí se na tebe s šíleným úsměvem) „Vidíš to? Už tři hodiny je provokuju! Pomůžeš mi je dohodit, nebo aspoň podržet žebřík, ať na ně dosáhnu pořádně?“","choices":{"boj":{"mode":"dice","success":"Blesk uhodil do Bleskobijce a on jásá, že vyhrál! Ty přežil jsi taky.","fail":"Blesk uhodil do tebe. Vlasy ti stojí ještě dnes.","orig":"A","text":"Postav se vedle Bleskobijce a „bojuj“ s bouří – křič na blesky, házej kameny do mraků a snaž se přežít, až do něj udeří blesk (komická scéna)."},"charisma":{"mode":"choice","options":[{"label":"Odvést ho domů na pálenku","outcome":"Bleskobijec pije, zpívá a nakonec ti dá svou nejlepší kořalku a zlaťák.","result":"good"},{"label":"Povzbudit ho, ať řve ještě víc","outcome":"Bouřka se rozzuří a spálí vám oběma obočí.","result":"bad"}],"orig":"B","text":"Přesvědč ho, ať přestane dráždit bouřku a radši jde domů na pálenku (nebo ho naopak povzbuď, ať křičí ještě hlasitěji)."},"magie":{"mode":"dice","success":"„Magický“ hromosvod! Blesk stodolu míjí a Bleskobijec slaví vítězství.","fail":"Hromosvod přitáhl blesk přímo k tobě.","orig":"C","text":"Zjisti, proč Bleskobijec zuří na bouřku (minulý rok mu blesk spálil stodolu) a pomoz mu vymyslet „magický“ způsob, jak se bouřce pomstít (nebo ho přesvědčit, že to nemá smysl)."}},"image":"assets/npc/n092.webp","source_file":"grok_image_1777133601165.jpg"},{"id":93,"name":"Padre Křtinec Bolavý","title":"Krvavý mnich","is_boss":false,"story":"(Padre Křtinec pomalu zvedne hlavu, krev mu stéká po bradě a promluví tichým, sladkým hlasem)\n„Vítej, synu můj... cítím v tobě silnou krev.“\n„Já jsem Padre Křtinec Bolavý, služebník Pravé Krve.\nLidé mi dávají svou esenci... a já jim za to dávám požehnání.\nNebo... bolest. Záleží na tom, jak moc křičí.\nPřinesl jsi mi dar? Nebo jsi sám přišel jako dar?“","choices":{"boj":{"mode":"choice","options":[{"label":"Přivést mu zločince z šatlavy","outcome":"Padre je spokojen a požehná ti krví. Zaplatí, ale karma pláče.","result":"good","karma":-1},{"label":"Odmítnout a utéct","outcome":"Padre se jen tiše směje. Za zády ti ještě pošle bolestivou kletbu.","result":"bad","karma":1}],"orig":"A","text":"Pomoz mu „pokřtít“ nové oběti - zajmout a přivézt živé lidi pro jeho rituál."},"charisma":{"mode":"dice","success":"Padre tě nechal jít s úsměvem. Prý přijdeš znovu.","fail":"Padre ti odebral trochu krve „jako poplatek“.","orig":"B","text":"Přesvědč ho, aby tě nechal jít (nebo ho naopak nalákej na ještě větší oběť)."},"magie":{"mode":"dice","success":"Našel jsi jeho krvavou relikvii a zapečetil ji. Padre slábne a prchá.","fail":"Padre tě prokoukl a vysál ti kus síly.","karma":1,"orig":"C","text":"Zjisti, jak funguje jeho magie vysávání krve a najdi způsob, jak ho oslabit nebo navždy zapečetit."}},"image":"assets/npc/n093.webp","source_file":"grok_image_1777280941272.jpg"},{"id":94,"name":"Paní Hildegarda Štosová","title":"Úřednice městské banky","is_boss":false,"story":"„Kde jsem to jen dala ten formulář… Ach ano, byl tady někde minulý týden. Nebo předminulý? No nic, musíte mi přinést nové povolení. A podepsané. A orazítkované. A nejlépe dvakrát.“","choices":{"boj":{"mode":"choice","options":[{"label":"Vylomit dveře archivu","outcome":"Archivář vydá razítko a Hildegarda ti platí poplatek za „spěšné vyřízení“.","result":"good"},{"label":"Prosit archiváře přes klíčovou dírku","outcome":"Archivář ti podstrčí formulář na formulář. Ztratil jsi celý den.","result":"neutral"}],"orig":"A","text":"„Ten hloupý archivář v suterénu mi odmítá vydat razítko „Schváleno královskou pokladnou“. Je tam zamčený a tvrdí, že má právo. Jdi dolů a… přesvědč ho, ať mi ho dá. Silou, jestli bude nutné.“"},"charisma":{"mode":"dice","success":"Rada Boromír podepsal. Hildegarda ti dá razítko „Hrdina“ a odměnu.","fail":"Boromír flirtoval tak dlouho, že jsi utekl bez podpisu.","orig":"B","text":"„Starý rada Boromír mi dluží podpis na formuláři C-47. Je to takový starý lišák a flirtuje se všemi. Přesvědč ho, ať mi to podepíše… ať už mu slíbíš cokoliv slušného.“"},"magie":{"mode":"choice","options":[{"label":"Sehnat duplikát s modrým voskem","outcome":"Duplikát je dokonalý. Hildegarda je nadšená a vyplatí ti odměnu.","result":"good"},{"label":"Sehnat duplikát s červeným voskem","outcome":"Teď platíš daň z psů. A nemáš psa.","result":"bad"}],"orig":"C","text":"„Ztratila jsem originál povolení k výběru zlatých ingotů. Musíte mi sehnat duplikát z královského archivu v horním městě. Ale pozor – musí být správně orazítkovaný modrým voskem, ne červeným! Červený je jen pro daň z psů…“"}},"image":"assets/npc/n094.webp","source_file":"grok_image_1777036798320.jpg"},{"id":95,"name":"Patragon Ohnivý","title":"Drakojezdec","is_boss":false,"story":"„Tohle je Šupinka! Nejlepší drak na světě! No… většinou mě poslouchá… občas ne. Pomůžeš mi ho vycvičit?“","choices":{"boj":{"mode":"dice","success":"Šupinka je zkrocená a poslušně přistála. Patragon tě nechá svézt.","fail":"Šupinka tě shodila do jezera.","orig":"A","text":"Pomoz Patragonovi zkrotit draka během divokého letu."},"charisma":{"mode":"choice","options":[{"label":"Přesvědčit draka pochoutkou","outcome":"Šupinka za ovci poslechne každý povel. Patragon ti platí.","result":"good"},{"label":"Přesvědčit draka přísným hlasem","outcome":"Šupinka tě olízla a pak omylem ožehla.","result":"bad"}],"orig":"B","text":"Přesvědč draka, ať poslouchá svého jezdce."},"magie":{"mode":"dice","success":"Drak měl v tlapě trn! Vytáhl jsi ho a Šupinka je hodná jako beránek.","fail":"Šupinka si myslela, že ji chceš okrást. Oheň!","orig":"C","text":"Zjisti, proč drak neposlouchá (možná má hlad, nebo ho něco bolí)."}},"image":"assets/npc/n095.webp","source_file":"grok_image_1777110909816.jpg"},{"id":96,"name":"Pepa Hlupáček","title":"Místní vesnický blb","is_boss":false,"story":"Hej, ty! Ty vypadáš chytře! Nebo silně... nebo hezky! Pomůžeš Pepovi?","choices":{"boj":{"mode":"dice","success":"Pepa jásá „Hijééé!“ a celá vesnice tleská. Dostaneš koláč i groš.","fail":"Pepa je těžší, než vypadá. Bolí tě záda.","orig":"A","text":"Vezmi mě na záda jako koníčka a proveď mě slavnostně celou vesnicí! Budu křičet „Hijééé!“ a ty budeš můj velký hrdina!"},"charisma":{"mode":"choice","options":[{"label":"Říct radě, že Pepa se nebojí smradu","outcome":"Rada se zasměje a Pepu přijme. Pepa ti dá svůj nejlepší knoflík a groš.","result":"good"},{"label":"Říct radě, že Pepa je chytrý","outcome":"Rada se smíchy válí. Pepu nepřijmou.","result":"bad"}],"orig":"B","text":"Městská rada mě nechce vzít jako odvážeče splašek. Řekni jim, že jsem nejlepší! Ať mě vezmou, prosím!"},"magie":{"mode":"choice","options":[{"label":"Hledat klobouk na komíně","outcome":"Klobouk tam opravdu je! Pepa je šťastný.","result":"good"},{"label":"Hledat klobouk v kozím chlévě","outcome":"Najdeš jen kozu, která ten klobouk snědla.","result":"neutral"}],"orig":"C","text":"Zase jsem někde ztratil svůj milovaný děravý klobouk... Najdi mi ho! Bez něj mi fouká do hlavy a já pak ještě víc blbnu."}},"image":"assets/npc/n096.webp","source_file":"grok_image_1777031733782.jpg"},{"id":97,"name":"Poslední Strážce","title":"Duch starého rytíře","is_boss":false,"story":"„...sloužil jsem králi. Pak mě zradil.\nNikdo ho nepřešel, dokud nedokáže, že je hoden... Pomoz mi najít klid.“","choices":{"boj":{"mode":"dice","success":"Temný duch je poražen. Strážce se uklání a mizí ve světle.","fail":"Temný duch tě shodil z mostu do studené řeky.","karma":1,"orig":"A","text":"Poraz temného ducha, který ho drží na mostě."},"charisma":{"mode":"choice","options":[{"label":"Připomenout mu dobré roky služby","outcome":"Strážce odpustí králi i sobě. Odchází v klidu a nechá ti svůj štít.","result":"good","karma":1},{"label":"Říct mu, že král byl zbabělec","outcome":"Duch se rozzlobí a mrazivým mečem tě šlehne.","result":"bad"}],"orig":"B","text":"Pomoz mu odpustit králi a sobě."},"magie":{"mode":"dice","success":"Pravda vyšla najevo. Strážce dokončil poslední úkol a odpočívá.","fail":"Pravda byla jiná, než jsi myslel. Strážce zuří.","orig":"C","text":"Zjisti pravdu o jeho zradě a pomoz mu dokončit poslední úkol."}},"image":"assets/npc/n097.webp","source_file":"grok_image_1777276835550.jpg"},{"id":98,"name":"Radní Ludovik von Greif","title":"Městský radní","is_boss":false,"story":"Ten starý kněz už příliš dlouho drží moc... a já mám lepšího kandidáta. Samozřejmě mnohem... vstřícnějšího k radě.","choices":{"boj":{"mode":"choice","options":[{"label":"Stráže potichu podplatit, ať odejdou","outcome":"Stráže zmizí a Ludovik platí. Kněz je bezbranný.","result":"good","karma":-1},{"label":"Kněze varovat","outcome":"Kněz ti požehná a Ludovik tě začne pomlouvat.","result":"neutral","karma":1}],"orig":"A","text":"„Nejvyšší kněz má své fanatické stráže. Postarej se o ně – tiše, nebo hlasitě, je mi to jedno. Hlavně ať zmizí z cesty.“"},"charisma":{"mode":"dice","success":"Šlechta podpořila Ludovikova favorita. Ludovik ti platí.","fail":"Kupci se ti vysmáli a šlechta tě pozvala ke dveřím.","karma":-1,"orig":"B","text":"„Přesvědč městskou šlechtu a bohaté kupce, aby podpořili mého favorita místo toho starého fanatika. Slib jim cokoliv – zlato, tituly, nebo... jiné výhody.“"},"magie":{"mode":"dice","success":"Našel jsi milostné dopisy kněze. Ludovik je nadšený.","fail":"Kněz tě přistihl v archivu a vyhnal tě s hymnou.","karma":-1,"orig":"C","text":"„Najdi kompromitující informace na nejvyššího kněze. Staré dopisy, milenky, úplatky... cokoliv, co ho zničí a otevře cestu mému člověku.“"}},"image":"assets/npc/n098.webp","source_file":"grok_image_1777034783938.jpg"},{"id":99,"name":"Rozálie, Dcera Mlynáře","title":"","is_boss":false,"story":"Vždycky je tu místo pro jeden příběh navíc... a jedno pivo navíc!","choices":{"boj":{"mode":"dice","success":"Vodník je zahnán zpět do hlubin. Rozálie ti natočí pivo a mlynář platí.","fail":"Vodník tě stáhl do řeky. Vylezl jsi s rybou v kalhotách.","karma":1,"orig":"A","text":"Vesnici sužuje vodník, který v noci tahá lidi do řeky. Zabij ho nebo ho zažeň.","quest":{"targets":["vodnikova_tun"],"goal":"Zažeň vodníka, který tahá lidi do řeky","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Zůstat a celou noc ji hlídat u krbu","outcome":"Rozálie spí klidně a ráno ti mlynář děkuje velkou odměnou.","result":"good","karma":1},{"label":"Zůstat… a hlídat ji zblízka","outcome":"Rodiče se vrátili dřív. Mlynář má těžkou ruku.","result":"bad"}],"orig":"B","text":"„Chtěla bych strávit s tebou noc... bojím se sama a rodiče jsou pryč.“ (Získáš velkou odměnu + karmu, pokud uspěješ)"},"magie":{"mode":"dice","success":"Runy ukazují na skrýš pod mlýnským kamenem. Je tam stará truhlička!","fail":"Runy tě zmátly a celý den jsi chodil kolem mlýna dokola.","orig":"C","text":"„Něco jsem našla u staré zdi za mlýnem. Jsou to prastaré runy, ale neumím je přečíst. Pomůžeš mi?“"}},"image":"assets/npc/n099.webp","source_file":"grok_image_1777022527756.jpg"},{"id":100,"name":"Rudolína Inkwell","title":"Městská elfí spisovatelka","is_boss":false,"story":"„Fešný cizinec? Ano, hezký pohled… ale upřímně – radši se dívám na písmenka na papíru. Ty mě nikdy nezklamou.“","choices":{"boj":{"mode":"dice","success":"Kronika je tvoje a kostliví rytíři se rozpadli. Rudolína je nadšená.","fail":"Kostliví rytíři tě vyhodili z věže po schodech.","orig":"A","text":"„Slyšela jsem, že v opuštěné věži na severu je ukrytá „Kronika zapomenutých králů“. Střeží ji ale kostliví rytíři. Přines mi tu knihu… celou, ideálně bez kostí uvnitř.“","quest":{"targets":["vez_kouzla","krypta"],"goal":"Získej Kroniku zapomenutých králů z opuštěné věže","gp":true}},"charisma":{"mode":"choice","options":[{"label":"Nabídnout lordovi osobní dedikaci","outcome":"Lord Velmont rukopis půjčí a Rudolína ti věnuje první výtisk a zlaťáky.","result":"good"},{"label":"Nabídnout lordovi peníze","outcome":"Lord se urazí, že ho máš za obchodníka.","result":"bad"}],"orig":"B","text":"„Mám informaci, že bohatý sběratel lord Velmont má vzácný rukopis „Láska upíra a elfky“. Přesvědč ho, ať mi ho půjčí… nebo prodá. Můžeš mu říct, že jsem ochotná věnovat mu… osobní dedikaci.“"},"magie":{"mode":"dice","success":"Mapa je rozluštěna a kniha nalezena. Rudolína může dopsat román!","fail":"Mapa tě zavedla do bažiny plné komárů.","orig":"C","text":"„Hledám legendární knihu „Šepoty mezi stromy“ – prý obsahuje ztracené elfské básně. Najdi mi stopu, kde se nachází, a pomoz mi rozluštit starou mapu, která k ní vede. Bez té knihy nemůžu dokončit svůj román!“"}},"image":"assets/npc/n100.webp","source_file":"grok_image_1777039282014.jpg"},{"id":101,"name":"Sahir Větrný Šepot","title":"Písečný Duch","is_boss":false,"story":"(Hlas je jako šepot větrů v dunách)\n„Cizince... vítr tě přinesl.\nJá jsem Sahir, ten, který byl kdysi králem a nyní jsem jen písek.\nMá říše byla pohřbena pod dunami.\nHledám svůj ztracený trůn... a své jméno, které vítr odnesl.\nPomůžeš mi vzpomenout, kdo jsem byl?“","choices":{"boj":{"mode":"dice","success":"Písečné přízraky jsi rozprášil a Sahir si vzpomíná na kus minulosti.","fail":"Přízraky tě zasypaly pískem až po krk.","karma":1,"orig":"A","text":"Bojuj s písečnými přízraky, které ho napadají."},"charisma":{"mode":"choice","options":[{"label":"Vyprávět mu o krásných ruinách jeho říše","outcome":"Sahir se smíří s osudem a daruje ti zlatou minci své říše.","result":"good"},{"label":"Říct mu, že na jeho říši nikdo nevzpomíná","outcome":"Sahir se rozpadne v písečnou bouři. Máš písek všude.","result":"bad"}],"orig":"B","text":"Pomoz mu přijmout, že jeho říše už neexistuje."},"magie":{"mode":"dice","success":"Našel jsi hrob s jeho jménem: Sahir al-Kadar. Vzpomněl si a odchází v pokoji.","fail":"Hrob byl prázdný a tys spadl do pasti s písečnými štíry.","orig":"C","text":"Najdi jeho starobylý hrob a pomoz mu získat zpět ztracenou identitu."}},"image":"assets/npc/n101.webp","source_file":"grok_image_1777279735069.jpg"},{"id":102,"name":"Saphira Noční Květ","title":"Temná elfka špionka","is_boss":false,"story":"(nakloní se k tobě a zašeptá)\n„Hledám někoho... důvěryhodného. Někoho, kdo umí udržet tajemství,...a rty.“\n„Pomůžeš mi dostat se do paláce? Slíbím ti, že se ti to... vyplatí.“","choices":{"boj":{"mode":"dice","success":"Probili jste se do paláce. Saphira ti tajně vtiskne váček s drahokamy.","fail":"Palácové stráže tě zahnaly a Saphira zmizela beze stopy.","orig":"A","text":"Pomoz jí probojovat se do paláce."},"charisma":{"mode":"choice","options":[{"label":"Odvést pozornost tancem s hraběnkou","outcome":"Saphira nepozorovaně mizí v chodbách. Večer se ti „vyplatí“.","result":"good"},{"label":"Odvést pozornost hlasitým přípitkem","outcome":"Všichni se otočí – i na Saphiru. Musíte utéct.","result":"bad"}],"orig":"B","text":"Pomoz jí infiltrovat palác společenskou cestou (bál, flirt)."},"magie":{"mode":"dice","success":"Plán vyšel dokonale. Dokumenty jsou ukradeny a nikdo nic netuší.","fail":"Plán se prozradil a ty jsi musel skočit z okna do jezírka.","orig":"C","text":"Vymysli chytrý plán infiltrace a krádeže dokumentů."}},"image":"assets/npc/n102.webp","source_file":"grok_image_1777247029864.jpg"},{"id":103,"name":"Sestra Agáta","title":"Fanatická jeptiška s kladivem","is_boss":false,"story":"(Agáta bouchne kladivem do země, až se zvedne prach) „V této vesnici se rozmnožilo zlo! Ďábel chodil mezi vámi a vy jste nic neudělali! Já, sestra Agáta, přináším světlo... a pokud bude třeba, tak i pořádnou ránu do hlavy! Kdo se mnou půjde vyhnat hřích z této díry?“","choices":{"boj":{"mode":"choice","options":[{"label":"Jít s Agátou do stodoly","outcome":"„Démoni“ jsou bandité. Agáta je vyžene kladivem a tobě požehná.","result":"good"},{"label":"Jít do stodoly napřed sám","outcome":"Bandité tě zmlátili. Pak přišla Agáta a zmlátila je.","result":"bad"}],"orig":"A","text":"Pomoz jí vyhnat „ďábelské síly“ (skupinu bandy, kterou považuje za démony) z opuštěné stodoly."},"charisma":{"mode":"dice","success":"Agáta zmírnila svůj hněv a vesničané jsou v bezpečí. Žehná ti.","fail":"Agáta tě označila za kacíře a praštila tě kladivem.","karma":1,"orig":"B","text":"Přesvědč Agátu, aby nezničila „podezřelé“ vesničany, nebo ji naopak povzbuď v jejím tažení."},"magie":{"mode":"dice","success":"Za vším stojí opilý lesník v kozlí masce. Agáta je spokojená a nikdo nezemřel.","fail":"Obvinil jsi farářovu kozu. Agáta ti nevěří a vyhnala tě z kostela.","orig":"C","text":"Zjisti, kdo skutečně stojí za podivnými událostmi ve vesnici (nebo vymysli, jak Agátu uspokojit, aniž by někdo zemřel)."}},"image":"assets/npc/n103.webp","source_file":"grok_image_1777193708941.jpg"},{"id":104,"name":"Shamus Fisherlowe","title":"Sympatický taurenský obchodník s ovocem","is_boss":false,"story":"„Ach, příteli! Já Shamus Fisherlowe. Každý den vozím nejlepší ovoce na trh, ale ty největší a nejsladší ořechy Huro Huro rostou jen na jednom nebezpečném ostrově. Sám se tam bojím plout – jsou tam divoké šelmy a rychlé proudy. Nepomohl bys mi tam doplout a nasbírat je? Slibím ti poctivý podíl!“","choices":{"boj":{"mode":"dice","success":"Jaguáři i hadi jsou zahnáni. Shamus ti dá plný koš ořechů Huro Huro.","fail":"Had se ti omotal kolem nohy a táhl tě do křoví.","orig":"A","text":"Doprovoď Shamuse na nebezpečný ostrov a ubraň ho před divokými jaguáry a obřími tropickými hady.","quest":{"targets":["mlzny_ostrov","ostrov_prani"],"goal":"Doprovoď Shamuse na ostrov Huro Huro","gp":true}},"charisma":{"mode":"choice","options":[{"label":"Najmout místní domorodé rybáře","outcome":"Rybáři znají každý proud. Výprava je hladká a Shamus se dělí.","result":"good"},{"label":"Najmout opilé námořníky z přístavu","outcome":"Námořníci se ztratili v mlze. Vrátili jste se bez ořechů.","result":"bad"}],"orig":"B","text":"Pomoz Shamusovi najít odvážné námořníky nebo domorodce, kteří by s ním na ostrov pluli."},"magie":{"mode":"dice","success":"Skrytý záliv nalezen! Plavba je bezpečná a ořechy sladké.","fail":"Proud vás odnesl na úplně jiný ostrov. Plný komárů.","orig":"C","text":"Prostuduj staré mapy a najdi bezpečnou cestu na ostrov Huro Huro (vyhnout se proudu, najít skrytý záliv atd.)."}},"image":"assets/npc/n104.webp","source_file":"grok_image_1777111696574.jpg"},{"id":105,"name":"Sir Denis z Říčního Hradu","title":"Stárnoucí rytíř","is_boss":false,"story":"(Sir Denis si sundává helmu, otírá si čelo a těžce vzdychá) „Prokletý most... Zrovna dnes, kdy musím dovézt tento důležitý dopis na královský dvůr a ještě vyřešit spor o mé staré léno. Jestli pojedu oklikou přes hory, nestihnu ani jedno. Mladý příteli... pomohl bys mi?“","choices":{"boj":{"mode":"dice","success":"Přebrodili jste řeku a vodní bestie zahnali. Sir Denis stihne dvůr.","fail":"Proud tě strhl a vylezl jsi o míli níž.","orig":"A","text":"Přeplav s Denisem divokou řeku na koních a ubráňte se silnému proudu a vodním bestiím, které se objevily po zřícení mostu."},"charisma":{"mode":"choice","options":[{"label":"Sehnat převozníka s loďkou","outcome":"Převozník vás převeze a Sir Denis stihne obojí. Platí ti z léna.","result":"good"},{"label":"Sehnat létajícího gnoma s balónem","outcome":"Balón praskl. Sir Denis padl do řeky i s dopisem.","result":"bad"}],"orig":"B","text":"Pomoz Denisovi najít rychlé spojence nebo loďku, která by ho převezla přes propast, aby stihl obě záležitosti včas."},"magie":{"mode":"dice","success":"Starý brod byl skrytý pod mlýnem. Denis stihne dvůr i spor!","fail":"Tvůj provizorní most se zřítil – s tebou na něm.","orig":"C","text":"Prozkoumej okolí a najdi (nebo rychle postav) alternativní cestu přes propast – buď objevíš starý skrytý brod, vymyslíš provizorní řešení, nebo navrhneš chytrý plán, jak dopis i spor vyřešit najednou."}},"image":"assets/npc/n105.webp","source_file":"grok_image_1777115097469.jpg"},{"id":106,"name":"Sira Šelma","title":"Tabaxi lovkyně / Kočičí šelma","is_boss":false,"story":"„Mňau... ty voníš jako dobrá kořist... nebo jako zajímavý lovec. Hledám někoho, kdo se nebojí jít se mnou hluboko do džungle. Tam je jedna velká... velmi nebezpečná kořist. Pomůžeš mi ji ulovit?“","choices":{"boj":{"mode":"dice","success":"Obří jaguár je uloven. Sira ti dá jeho tesák a podíl z odměny.","fail":"Jaguár tě drápl přes záda. Sira tě musela táhnout z džungle.","orig":"A","text":"Doprovoď Siry na lov obrovského starobylého jaguára (nebo ještě většího predátora), který terorizuje okolí.","quest":{"targets":["forest"],"goal":"Ulov se Sirou starobylého jaguára","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Zeptat se domorodců s úctou","outcome":"Domorodci prozradí slabinu šelmy. Sira tě uzná za rovnocenného partnera.","result":"good"},{"label":"Vyptávat se Siry přímo","outcome":"Sira zasyčí, že zvědavost zabila kočku. A málem i tebe.","result":"bad"}],"orig":"B","text":"Pomoz jí získat informace od místních domorodců nebo přesvědč ji, aby ti prozradila, co přesně na té kořisti chce (a případně ji přemluv, ať tě vezme jako rovnocenného partnera)."},"magie":{"mode":"dice","success":"Past sklapla a kořist je chycena živá. Sira přede spokojeností.","fail":"Past chytila tebe. Sira se smála až do večera.","orig":"C","text":"Společně vystopujte a nalíčte past na velkou kořist – najdi její slabinu, stopu nebo způsob, jak ji chytit živou (nebo bez zbytečného krveprolití)."}},"image":"assets/npc/n106.webp","source_file":"grok_image_1777120111587.jpg"},{"id":107,"name":"Siréna Lyralei","title":"Mořská zpěvačka","is_boss":false,"story":"Rybáři nás loví do sítí… a pak nás prodávají jako exotické zvíře.","choices":{"boj":{"mode":"choice","options":[{"label":"Potopit loď","outcome":"Loď jde ke dnu, sirény jsou volné. Lyralei ti zazpívá a dá perlu.","result":"good"},{"label":"Zabít kapitána","outcome":"Sirény jsou volné, ale posádka tě pronásleduje. Krev zůstala na rukou.","result":"neutral","karma":-1}],"orig":"A","text":"Velká rybářská loď loví moje sestry. Potop ji nebo zabij kapitána."},"charisma":{"mode":"dice","success":"Rybáři slíbili sirény nelovit. Lyralei tě políbí na tvář.","fail":"Rybáři tě hodili do vlastní sítě.","karma":1,"orig":"B","text":"Přesvědč rybáře z přístavu, ať přestanou lovit sirény.","quest":{"targets":["rybarska_osada","sedy_pristav"],"goal":"Přesvědč rybáře z přístavu, ať nechají sirény","gp":false}},"magie":{"mode":"dice","success":"Poklad je vykopán! Lyralei se s tebou podělí.","fail":"Mapa byla padělek. Kopal jsi celý den pro nic.","orig":"C","text":"Našla jsem starou mořskou mapu s označením zakopaného pokladu. Pomoz mi ji rozluštit."}},"image":"assets/npc/n107.webp","source_file":"grok_image_1777039415022.jpg"},{"id":108,"name":"Slávek","title":"Sprostý Bobr Inženýr","is_boss":false,"story":"(Slávek zvedne hlavu, zuby má plné třísek a hlasitě říhne)\n„No kurva, konečně někdo! Už jsem si myslel, že tu chcípnu sám jak pes!\nJá jsem Slávek, nejlepší bobr v celým kraji.\nPrávě stavím největší bobří palác na řece... nebo aspoň největší díru, kam si budu moct natáhnout ocas.\nAle ty líný vydry mi odmítají pomoct, ty parchanti.\nTy vypadáš dost silně... půjdeš mi nasekat pár stromů? Nebo ti mám rovnou říct, kam ti mám strčit tu pilu?“","choices":{"boj":{"mode":"dice","success":"Dub padl s obrovským rachotem. Slávek nadšeně nadává radostí.","fail":"Dub padl na tebe. Slávek se smál, až se zakuckal.","orig":"A","text":"„Tamhle nahoře je obrovskej dub. Jdi ho porazit, ať to pořádně zaduní! A kdyby začal rvát, tak mu dej přes ksicht!“"},"charisma":{"mode":"choice","options":[{"label":"Uplatit vydry rybami","outcome":"Vydry přijdou pracovat. Přehrada roste a Slávek ti platí.","result":"good"},{"label":"Vyhrožovat vydrám přehradou","outcome":"Vydry tě pokousaly a utekly. Slávek nadává ještě víc.","result":"bad"}],"orig":"B","text":"„Sežeň mi ty líný vydry a řekni jim, ať táhnou prdel sem. Nebo jim vyhrož, že jim postavím přehradu přímo před noru, ať se podělaj strachy.“"},"magie":{"mode":"dice","success":"Nová přehrada drží jako skála. Slávek ti z vděčnosti daruje zlatou třísku.","fail":"Přehrada se zase sesypala. Slávek tě proklíná.","orig":"C","text":"„Vymysli, jak tu přehradu postavit chytřej, než minule. Minule se mi to celý sesypalo a já měl tři dny dřevo v prdeli.“"}},"image":"assets/npc/n108.webp","source_file":"grok_image_1777246263340.jpg"},{"id":109,"name":"Snová Koule","title":"Entita z vesmíru","is_boss":false,"story":"(hluboký, ozvěnný hlas, který zní přímo v hlavě) „Smrtelníku... vidím tvou duši. Hledáš smysl. Já ti dám úkol. Najdi... a cestuj. Splň mé přání a já ti ukážu věci, které žádný smrtelník neviděl.“","choices":{"boj":{"mode":"dice","success":"Noční přízraky jsou poraženy. Koule ti ukáže hvězdy, které nikdo neviděl.","fail":"Přízraky tě pronásledovaly až do rána. Jsi vyčerpaný.","orig":"A","text":"Probudit se v noční můře a bojovat s nočními přízraky, které brání plnění úkolu."},"charisma":{"mode":"choice","options":[{"label":"Požádat Kouli o jasnější instrukce","outcome":"Koule ti ukáže cestu a odměnu. Cítíš se moudřejší.","result":"good"},{"label":"Žádat lepší odměnu","outcome":"Koule se urazí a pošle ti noční můru o pavoucích.","result":"bad"}],"orig":"B","text":"Přesvědčit Kouli, aby ti dala jasnější instrukce nebo lepší odměnu."},"magie":{"mode":"dice","success":"Hádanka je vyřešena. Místo ze snu skutečně existuje – a v něm poklad!","fail":"Hádanka tě zamotala tak, že ses ztratil ve vlastním snu.","orig":"C","text":"Rozluštit hádanku, kterou ti Koule dala ve snu, a najít místo, kam tě posílá."}},"image":"assets/npc/n109.webp","source_file":"grok_image_1777131135700.jpg"},{"id":110,"name":"Soňa Bouřlivá","title":"Krásná kentaurice","is_boss":false,"story":"„No tak, malý človíčku... nebo malá dámo? Jsi dost odvážný, aby sis se mnou zahrál?“","choices":{"boj":{"mode":"dice","success":"Doběhl jsi do cíle první! Soňa musí splnit tvůj příkaz – a dá ti kus stříbra.","fail":"Soňa tě předběhla o tři délky. Teď musíš plnit její příkaz.","orig":"A","text":"„Tak pojď! Dáme si závody přes celou pláň! Kdo prohraje, ten druhému splní jeden příkaz. A já nerada prohrávám...“ (silový závod plný adrenalinu)"},"charisma":{"mode":"choice","options":[{"label":"Odolat a jen s ní tančit pod hvězdami","outcome":"Soňa je ohromena tvou výdrží a daruje ti podkovu pro štěstí.","result":"good"},{"label":"Nechat se svést","outcome":"Kentauří vášeň je… drtivá. Ráno tě bolí všechno.","result":"bad"}],"orig":"B","text":"„Už je to tak dlouho, co jsem necítila, jaké to být pořádnou klisnou... Pojď ke mně blíž. Ukážu ti, jak divoká umím být.“ (sexy, agresivní svádění – bisexuální)"},"magie":{"mode":"dice","success":"Vlčí bylina je nalezena a rituál vyšel. Soňa poprvé stojí na dvou nohou!","fail":"Rituál se zvrtl a tobě narostla na den koňská hříva.","orig":"C","text":"„Nechci už být napůl kůň. Chci být normální ženou. Mám všechno potřebné k rituálu... chybí mi jen vlčí bylina. Najdi ji a pomoz mi s přeměnou.“"}},"image":"assets/npc/n110.webp","source_file":"grok_image_1777033307856.jpg","extra":{"id":"zabit","who":"all","label":"Místo plnění úkolů Soňu zabít","stat":"boj","boss":true,"success":"Soňa Bouřlivá padla. Její měšec je teď tvůj, ale svědomí tě tíží.","fail":"Soňa byla rychlejší – bouřlivá nejen jménem. Odcházíš zkrvavený.","karma":-1},"special":"Hráč má možnost Soňu zabít místo plnění úkolů."},{"id":111,"name":"Soňa Rukávová","title":"Bláznivá mladá žena z okraje vesnice","is_boss":false,"story":"(Soňa se k tobě rozběhne bosá, oči má plné naděje a slz) „Prosím tě... ty jsi hodný, vidím to! Můj manžel je ve válce... už dlouho jsem mu nenapsala. Máme malou dcerku, víš? Musí vědět, že na něj čekáme. Doručíš mu tyhle dopisy? Prosím... nevím, kde přesně je, ale určitě ho najdeš. On se vrátí. Musí se vrátit...“","choices":{"boj":{"mode":"dice","success":"Lupiče jsi odrazil a dopisy doručil. Posádka slibuje, že je manželovi předá.","fail":"Dezertéři tě okradli a dopisy rozházeli do větru.","karma":1,"orig":"A","text":"Doruč dopisy do nejbližší válečné posádky, ale cestou tě napadnou lupiči nebo dezertéři.","quest":{"targets":["kamenity_prusmyk","zelezny_brod"],"goal":"Doruč dopisy válečné posádce","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Najít vojáka z manželovy jednotky","outcome":"Voják dopisy vezme a slíbí je předat. Soňa ti dá koláč a pláče štěstím.","result":"good","karma":1},{"label":"Vymyslet pro Soňu uklidňující lež","outcome":"Soňa ti věří, ale ty v noci nemůžeš spát.","result":"neutral"}],"orig":"B","text":"Najdi někoho, kdo zná jednotku jejího manžela, a přesvědč ho, aby dopisy předal (nebo vymysli uklidňující lež pro Soňu)."},"magie":{"mode":"choice","options":[{"label":"Říct jí pravdu","outcome":"Manžel padl. Soňa pláče, ale konečně se smíří a začne nový život.","result":"good","karma":1},{"label":"Nechat ji žít v iluzi","outcome":"Soňa dál čeká u cesty. Jednou se pravdu dozví sama.","result":"neutral"}],"orig":"C","text":"Zjisti pravdu o jejím manželovi (kde je, co se stalo) a rozhodni, jestli jí pravdu řekneš, nebo ji necháš žít v iluzi."}},"image":"assets/npc/n111.webp","source_file":"grok_image_1777196479885.jpg"},{"id":112,"name":"Stromoví Stařešinové","title":"Živé stromy s obličeji","is_boss":false,"story":"(největší strom se skloní, kůra zapraská a hlubokým hlasem promluví)\n„Člověče… už dlouho jsme neslyšeli pořádný vtip. Pověz nám nějaký… nebo tě tu necháme zakořenit.“\nTy (váhavě): „…Odkdy stromy mluví?!“\nStrom (zasměje se jako praskající větev): „Od té doby, co lidi přestali být vtipní. Tak co, máš pro nás něco?“","choices":{"boj":{"mode":"dice","success":"Utekl jsi mezi kořeny jako lasička. Stromy tleskají větvemi a nechají tě jít.","fail":"Větev tě trefila do hlavy. Stromy se konečně smějí – tobě.","orig":"A","text":"Stromy se rozčílí, že neumíš vtipy a začnou po tobě házet větvemi a kořeny. Uteč nebo je „uklidni“."},"charisma":{"mode":"choice","options":[{"label":"Říkat strašně špatné vtipy","outcome":"Stromy se chechtají tak, že z nich padá listí i oříšky. Odměna!","result":"good"},{"label":"Říkat chytré filozofické vtipy","outcome":"Stromy nerozumí a začnou tě obrůstat kořeny.","result":"bad"}],"orig":"B","text":"Pověz jim sérii dobrých (nebo strašně špatných) vtipů, až se stromy chechtají tak, že z nich padají listy."},"magie":{"mode":"dice","success":"„Proč strom nikdy nelže? Protože má čisté svědomí… letokruhy!“ Stromy padají smíchy.","fail":"Tvůj vtip o hoblíku stromy urazil.","orig":"C","text":"Vymysli originální vtip přímo pro stromy (třeba o lese, dřevě nebo kořenech), který je opravdu pobaví."}},"image":"assets/npc/n112.webp","source_file":"grok_image_1777104079378.jpg"},{"id":113,"name":"Sylvana Kořenová Matka","title":"Prastará dryáda-matka lesa","is_boss":false,"story":"(Sylvana se na tebe dívá svýma jezírkovýma očima, plnýma zoufalství a starobylé moudrosti.)\n„Dítě mého lesa... přišlo zlo, které požírá mé kořeny.\nStudny jsou otrávené, stromy usychají, moje děti (víly a zvířata) umírají.\nPomoz mi, nebo zemřeme všichni.“","choices":{"boj":{"mode":"dice","success":"Zmutovaný tvor v srdci lesa padl. Sylvana tě odmění zlatým listem.","fail":"Tvor tě postříkal jedem a les se ti zatočil před očima.","karma":1,"orig":"A","text":"Zabij zdroj otravy (temný alchymista nebo zmutovaný tvor v srdci lesa).","quest":{"targets":["forest"],"goal":"Zabij zdroj otravy v srdci lesa","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Přísahat lesu věrnost","outcome":"Sylvana ti svěří část moci a les se očistí. Odchází s tebou její požehnání.","result":"good","karma":1},{"label":"Slíbit jí cokoliv, jen ať pospíchá","outcome":"Sylvana vycítí tvou netrpělivost a odmítne.","result":"neutral"}],"orig":"B","text":"Přesvědč Sylvanu, aby ti svěřila část své moci a společně očistili les."},"magie":{"mode":"dice","success":"Rituál očistil studny a stromy znovu zelenají.","fail":"Rituál přitáhl jedovaté výpary. Kašleš ještě dva dny.","orig":"C","text":"Zjisti pravý původ otravy a proveď starobylý očistný rituál."}},"image":"assets/npc/n113.webp","source_file":"grok_image_1777246544548.jpg"},{"id":114,"name":"Thalor Temnohuč","title":"Temný starý Satyr","is_boss":false,"story":"„Hlasy stromů mi šeptají... svět je příliš světlý. Příliš čistý. Potřebujeme více temnoty. Pomoz mi, smrtelníku... nebo se sám staneš hnojivem pro les.“","choices":{"boj":{"mode":"choice","options":[{"label":"Bránit Thalora před strážci světla","outcome":"Rituál se zdařil, les potemněl. Thalor ti platí temným zlatem.","result":"good","karma":-1},{"label":"Pustit strážce světla k rituálu","outcome":"Rituál je zničen. Thalor tě proklíná, strážci ti děkují.","result":"neutral","karma":1}],"orig":"A","text":"Bránit Thalora před strážci světla, kteří přišli zničit jeho rituál."},"charisma":{"mode":"dice","success":"Thalor obrátí svou temnotu proti skutečnému zlu – nekromantovi v horách.","fail":"Thalor se rozzuřil a pustil na tebe trnité šlahouny.","karma":1,"orig":"B","text":"Přesvědč ho, aby svou temnotu nasměroval proti většímu zlu (nebo ho nalákej na vlastní temné ambice)."},"magie":{"mode":"choice","options":[{"label":"Rituál potají sabotovat","outcome":"Runy se rozpadnou a Thalor nic nepozná. Tvá karma září.","result":"good","karma":1},{"label":"Pomoci rituál dokončit","outcome":"Thalor zesílí a odmění tě. Les se zachvěje strachy.","result":"neutral","karma":-1}],"orig":"C","text":"Pomoz mu dokončit temný rituál spojením run a obětí, nebo ho naopak sabotuj."}},"image":"assets/npc/n114.webp","source_file":"grok_image_1777119784346.jpg"},{"id":115,"name":"Thalor Šedorožec","title":"Faun z Temného Hvozdu","is_boss":false,"story":"Můj svět vymírá... Les slábne. Temní tvorové, kteří kdysi udržovali rovnováhu, jsou pryč. Pomoz mi otevřít bránu. Nech temnotu znovu proudit. Ať se les opět zahustí... ať je znovu rovnováha.","choices":{"boj":{"mode":"dice","success":"Strážci brány ustoupili. Thalor ti s úctou daruje rohovou flétnu.","fail":"Světlí enti tě odnesli z hvozdu jako neposlušné dítě.","orig":"A","text":"Pomoz Thalorovi ubránit rituál před strážci brány (starými lesními duchy a světlými enty), kteří bránu chtějí udržet zavřenou."},"charisma":{"mode":"choice","options":[{"label":"Varovat ho před zlem za bránou","outcome":"Thalor zaváhá a hledá jinou cestu k rovnováze. Děkuje ti.","result":"good","karma":1},{"label":"Získat mu důvěru temných bytostí","outcome":"Temné bytosti tě obejdou, očichají… a kousnou.","result":"bad"}],"orig":"B","text":"Přesvědč Thalora, že otevření brány může přinést víc zla než rovnováhy, nebo mu pomoz získat důvěru ostatních temných bytostí v lese."},"magie":{"mode":"choice","options":[{"label":"Bránu tajně trvale uzavřít","outcome":"Brána je zapečetěná a Thalor si myslí, že rituál jen nevyšel.","result":"good","karma":1},{"label":"Pomoci mu runy dokončit","outcome":"Brána se otevře. Les houstne… a něco se v něm probouzí.","result":"neutral","karma":-1}],"orig":"C","text":"Pomoz mu dokončit složitý runový rituál (nebo naopak najdi způsob, jak bránu trvale uzavřít, aniž by to Thalor poznal)."}},"image":"assets/npc/n115.webp","source_file":"grok_image_1777118711160.jpg"},{"id":116,"name":"Tharok Kořenový","title":"Prastarý kentaur strážce lesa","is_boss":false,"story":"Tisíc let jsem střežil tento les.\nNyní někdo otravuje prameny života. Studny, ze kterých pijí všechny lesní bytosti, jsou zkažené.\nStromy usychají. Vlci umírají. Medvědi se mění v zuřivé bestie.\nJá už nemohu opustit srdce lesa... jsem příliš spjatý s kořeny.\nTy, smrtelníče, musíš najít toho, kdo tráví vodu, a zastavit to.","choices":{"boj":{"mode":"dice","success":"Otrávení tvorové jsou poraženi a studny volné. Tharok ti žehná.","fail":"Otrávený troll tě srazil do zkažené studny.","karma":1,"orig":"A","text":"Vydej se ke znečištěným studnám a bojuj s otrávenými tvory (zmutovaní vlci, zuřivé dryády, otrávení trolové), kteří teď brání studnám."},"charisma":{"mode":"choice","options":[{"label":"Zastrašit alchymistu","outcome":"Alchymista se pomočí strachy a přestane trávit vodu.","result":"good"},{"label":"Přesvědčit alchymistu penězi","outcome":"Alchymista peníze vezme a trávit nepřestane.","result":"bad"}],"orig":"B","text":"Najdi a přesvědč (nebo zastraš) toho, kdo vodu tráví – může to být chamtivý alchymista, temný druid nebo konkurenční frakce."},"magie":{"mode":"dice","success":"Zdrojem je prokletý krystal. Rozbil jsi ho a prameny se očistily.","fail":"Jed tě oslabil dřív, než jsi našel jeho zdroj.","orig":"C","text":"Zjisti původ otravy (magický jed, artefakt, rituál) a najdi způsob, jak studny očistit a obnovit rovnováhu lesa."}},"image":"assets/npc/n116.webp","source_file":"grok_image_1777242962013.jpg"},{"id":117,"name":"Tichý Viktor","title":"Kenku nájemný vrah","is_boss":false,"story":"(Viktor mlčí. Pak najednou promluví hlasem starého muže, kterého zřejmě zabil) „...potřebuji... někoho odstranit...“ (přepne na hlas mladé ženy) „...tiše... čistě... bez svědků.“ (vrátí se k vlastnímu chraplavému hlasu) „...zaplatím dobře.“","choices":{"boj":{"mode":"choice","options":[{"label":"Cíl zabít","outcome":"Viktor zaplatí. Mluví přitom hlasem tvé matky. Brr.","result":"good","karma":-1},{"label":"Cíl varovat","outcome":"Cíl uteče a odmění tě. Viktor si tě zapamatoval…","result":"neutral","karma":1}],"orig":"A","text":"Zabij cíl (důležitého kupce / strážného / konkurenta) a vyčisti cestu od svědků."},"charisma":{"mode":"dice","success":"Viktor prozradil objednavatele – zkorumpovaného radního. To je cenná informace!","fail":"Viktor promluvil tvým vlastním hlasem a zmizel. Děsivé.","orig":"B","text":"Přesvědč Viktora, aby ti prozradil, kdo si objednal vraždu (nebo ho přemluv, ať si vybere jiný cíl)."},"magie":{"mode":"dice","success":"Tichý plán vyšel a nikdo nic neviděl. Viktor platí.","fail":"Svědkové tě viděli a stráže tě honí.","karma":-1,"orig":"C","text":"Vymysli chytrý a tichý způsob, jak odstranit cíl (jed, past, fingovaná nehoda) a zanechat co nejméně stop."}},"image":"assets/npc/n117.webp","source_file":"grok_image_1777193773920.jpg"},{"id":118,"name":"Tyris Šťastná","title":"Veselá gnomka z krčmy","is_boss":false,"story":"„Hoj ty velký! Já Tyris, nejlepší gnomka v celým městě! Slyšela jsem o jednom runovým amuletu schovaným v podzemní kanalizaci… a já ho prostě musím mít! Půjdeš se mnou, jo? Bude sranda!“","choices":{"boj":{"mode":"dice","success":"Obří krysy i vodní monstra jsou poražena. Tyris jásá s amuletem v ruce.","fail":"Krysy tě zahnaly do stoky. Smrdíš ještě týden.","orig":"A","text":"Probojuj se s Tyris kanalizací plnou obřích krys a vodních monster."},"charisma":{"mode":"choice","options":[{"label":"Nechat Tyris vést","outcome":"Tyris zná zkratky. Amulet je váš a ona ti dá podíl.","result":"good"},{"label":"Vést sám","outcome":"Zabloudili jste do kanálu, kam se splachuje z pivovaru.","result":"bad"}],"orig":"B","text":"Přesvědč Tyris, ať ti řekne přesnou polohu amuletu a pomoz jí ho získat bez zbytečného rizika."},"magie":{"mode":"dice","success":"Staré mapy odhalily suchou chodbu přímo k amuletu.","fail":"Mapa byla vzhůru nohama. Spadli jste do krysí nory.","orig":"C","text":"Prostuduj staré mapy kanalizace a najdi bezpečný způsob, jak se k amuletu dostat."}},"image":"assets/npc/n118.webp","source_file":"grok_image_1777098472593.jpg"},{"id":119,"name":"Veselá Kapela Škubnutí","title":"Rekta, Baculatá Ema & Píšťalko","is_boss":false,"story":"(Rekta ti mává, Ema se hlasitě směje a Píšťalko píská na píšťalu)\nRekta: „Hej ty! Právě jsi spadl z nebe! Náš bubeník se včera opil natolik, že mu explodovala střeva... teda aspoň říkal, že mu je špatně.“\nEma: „Potřebujeme bubeníka na dnešní večer na svatbě v sousední vesnici! Zahraj si s náma aspoň!“\nPíšťalko: „No tak! Bude sranda! A když to nezvládneš, tak tě Ema zadusí svýma melounama!“","choices":{"boj":{"mode":"choice","options":[{"label":"Přehrát Mrtvé Skřety hudbou","outcome":"Svatba tancuje celou noc a kapela ti dá podíl z výdělku.","result":"good"},{"label":"Praštit je bubnem","outcome":"Strhla se rvačka a svatba skončila dřív. Nikdo neplatí.","result":"bad"}],"orig":"A","text":"„Na svatbě bude i konkurenční kapela ‚Mrtví Skřeti‘. Pomoz nám je přehrát... nebo je aspoň praštit bubnem do hlavy!“"},"charisma":{"mode":"dice","success":"Nejlepší svatba v historii vesnice! Nevěsta tě políbí a kapela platí.","fail":"Zakopl jsi o buben a spadl do svatebního dortu.","orig":"B","text":"Zahraj (nebo zatanči/zazpívej) s kapelou na svatbě a udělej show, aby byla nejlepší noc v životě ženicha a nevěsty (plno dvojsmyslů a trapasů)."},"magie":{"mode":"dice","success":"Magický buben hraje sám a zní skvěle. Kapela je nadšená.","fail":"Buben začal hrát sám, ale nejde zastavit. Celou noc.","orig":"C","text":"Vymysli chytrý trik, jak nahradit nemocného bubeníka (třeba magický buben, který hraje sám, nebo přesvědč místního opilce, ať si zahraje)."}},"image":"assets/npc/n119.webp","source_file":"grok_image_1777244668595.jpg"},{"id":120,"name":"Vespera Noční Dýka","title":"Assassin žena","is_boss":false,"story":"Zlato mluví. Jed mlčí... ale pracuje rychleji.","choices":{"boj":{"mode":"dice","success":"Silný válečník padl. Vespera ti beze slova přisune měšec.","fail":"Válečník byl silnější. Vespera tě musela vytáhnout z krčmy.","karma":-1,"orig":"A","text":"Můj cíl je silný válečník. Zabij ho, než mě zabije on."},"charisma":{"mode":"choice","options":[{"label":"Pozvat syna na „tajnou schůzku s obdivovatelkou“","outcome":"Syn přijde. Vespera se usměje a zaplatí. Co bylo dál, nechceš vědět.","result":"good","karma":-1},{"label":"Varovat purkmistrova syna","outcome":"Syn uteče z města. Vespera ti pošle varování – dýku v polštáři.","result":"bad","karma":1}],"orig":"B","text":"Přesvědč purkmistrova syna, ať se se mnou setká o samotě."},"magie":{"mode":"choice","options":[{"label":"Vyrobit skutečný pomalý jed","outcome":"Vespera je spokojená a platí. Někde někdo bude trpět.","result":"good","karma":-1},{"label":"Vyrobit jen silné projímadlo","outcome":"Cíl přežije, ale týden nevyleze z latríny. Vespera zuří, ty se směješ.","result":"neutral","karma":1}],"orig":"C","text":"Vyrob mi speciální jed, který působí pomalu a bolestivě. Potřebuji recepturu."}},"image":"assets/npc/n120.webp","source_file":"grok_image_1777027392935.jpg"},{"id":121,"name":"Viktor de Blanc","title":"Zchudlý šlechtic","is_boss":false,"story":"„Ach, milý příteli… kdysi jsem měl palác, víno a krásky. Teď mám jen dluhy a západ slunce. Nepomohl bys mi získat zpět mé rodinné dědictví?“","choices":{"boj":{"mode":"dice","success":"Věřitelé jsou vyhnáni a Viktor znovu spí ve svém sídle. Platí ti vínem a zlatem.","fail":"Věřitelé měli najaté rváče. Odnesl jsi to ty.","orig":"A","text":"Vyžeň věřitele z jeho starého sídla."},"charisma":{"mode":"choice","options":[{"label":"Seznámit ho s bohatou vdovou","outcome":"Vdova se do Viktora zamiluje. Svatba bude a ty jsi čestný host s odměnou.","result":"good"},{"label":"Přesvědčit ho, ať přestane pít","outcome":"Viktor slíbí, že přestane. Zítra. Dnes ale pije na tvůj účet.","result":"bad"}],"orig":"B","text":"Pomoz mu získat novou bohatou manželku (nebo ho přesvědč, ať přestane pít)."},"magie":{"mode":"dice","success":"Poklad byl ukrytý v rodinné kapli. Viktor je znovu bohatý a štědrý.","fail":"Mapa vedla do sklepa plného krys a prázdných lahví.","orig":"C","text":"Najdi jeho ukrytý rodinný poklad podle staré mapy."}},"image":"assets/npc/n121.webp","source_file":"grok_image_1777110793538.jpg"},{"id":122,"name":"Václav Rukáv","title":"Zarmoucený otec","is_boss":false,"story":"(Václav se opírá o vidle, hlas má unavený a občas se mu zlomí) „Jmenuji se Václav Rukáv... Už tři roky jsem neslyšel o své dceři Soně. Byla to hodná holka... ale pak se jí stalo něco zlého. Zmizela. Prosím tě, cizince. Najdi ji. Přiveď mi ji zpátky domů. Je to všechno, co mi zbývá na tomto světě. Pomůžeš mi?“","choices":{"boj":{"mode":"dice","success":"Soňu jsi ochránil před dotěrnými chlapy. Václav ti děkuje se slzami.","fail":"Chlapi tě zmlátili a Soňa utekla do lesa.","karma":1,"orig":"A","text":"Najdi Soňu a ochraň ji před nebezpečím (divoká zvířata, lidé, kteří ji obtěžují)."},"charisma":{"mode":"choice","options":[{"label":"Mluvit se Soňou o dcerce a domově","outcome":"Soňa se rozpláče a vrátí se k otci. Rodina je zase spolu.","result":"good","karma":1},{"label":"Přemlouvat ji příkazem a výčitkami","outcome":"Soňa se lekne a uteče. Václav je zklamaný.","result":"bad"}],"orig":"B","text":"Přesvědč Soňu, aby se vrátila domů k otci."},"magie":{"mode":"choice","options":[{"label":"Říct Václavovi celou pravdu","outcome":"Václav se dozví o válce i ztrátě. Bolí to, ale začne Soně pomáhat.","result":"good","karma":1},{"label":"Pravdu zamlčet","outcome":"Václav dál nic neví. Soňa i on žijí v nejistotě.","result":"neutral"}],"orig":"C","text":"Zjisti pravdu o tom, co se Soně před třemi lety stalo, a rozhodni, jak s informací naložit."}},"image":"assets/npc/n122.webp","source_file":"grok_image_1777197304827.jpg"},{"id":123,"name":"Zafír Al-Mor","title":"Záludný džin ze starověké vázy","is_boss":false,"story":"„Tři přání, ó mistře! Samozřejmě… za předpokladu, že přesně víš, co říkáš.“","choices":{"boj":{"mode":"choice","options":[{"label":"Přijmout bohatství i s rizikem","outcome":"Máš hromadu zlata! Jen stráže královské pokladny teď znají tvůj obličej.","result":"good","karma":-1},{"label":"Opravit přání: „Chci být bohatý poctivou cestou“","outcome":"Džin se ušklíbne. Najdeš zlaťák. Jeden.","result":"neutral"}],"orig":"A","text":"„Chci být bohatý!“ → Dostaneš hromadu zlata… které patří královské pokladně (a teď tě hledají)."},"charisma":{"mode":"choice","options":[{"label":"Osvobodit džina z vázy","outcome":"Džin se rozzuří, ale pak ti z vděčnosti nechá dar. Bouřlivý, ale dar.","result":"good","karma":1},{"label":"Přijmout obří sílu","outcome":"Jsi silný jako obr – a tři dny v měsíci obr opravdu jsi. Zbourals dveře krčmy.","result":"bad"}],"orig":"B","text":"„Chci být nejsilnější!“ → Získáš obrovskou sílu… ale proměníš se v obra na 3 dny v měsíci."},"magie":{"mode":"dice","success":"Formuloval jsi přání tak chytře, že džin zůstal bez kličky. Nestárneš… o jeden den. A máš poklad.","fail":"Džin našel kličku. Na celý den ti vypadaly všechny vlasy.","orig":"C","text":"„Chci nesmrtelnost!“ → Nestárneš… ale každý rok ti někdo blízký zemře."}},"image":"assets/npc/n123.webp","source_file":"grok_image_1777040624148.jpg","special":"Džina můžeš osvobodit z vázy (což ho rozzuří), nebo s ním smlouvat."},{"id":124,"name":"Zephyra Větrná","title":"Svobodná harpyje kurýrka","is_boss":false,"story":"(Zephyra se lehce nakloní, křídla lehce roztáhne a usměje se drze)\n„No hele, další suchozemec, co se nebojí výšky!\nJá jsem Zephyra Větrná, nejrychlejší harpyje v celým kraji.\nNosím zprávy, balíčky... a občas i pár tajností za tučný obnos.\nPrávě teď mi utekl jeden důležitý balíček - nějaký parchant mi ho sebral cestou.\nPomůžeš mi ho dostat zpátky? Nebo se bojíš létat?“","choices":{"boj":{"mode":"dice","success":"Bandité na útesech jsou poraženi a balíček je zpět. Zephyra ti dá podíl z výplaty.","fail":"Bandita tě shodil z útesu. Zephyra tě chytila těsně nad zemí.","orig":"A","text":"Najdi bandity, kteří jí ukradli balíček, a vezmi jim ho zpět (boj na útesech nebo v lese).","quest":{"targets":["krvavy_utes"],"goal":"Získej zpět ukradený balíček od banditů na útesech","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Požádat, ať tě vezme na let jako spolupracovníka","outcome":"Letíte nad krajinou! Zephyra ti platí za pomoc i za odvahu.","result":"good"},{"label":"Vyjednávat s bandity o výkupném","outcome":"Bandité výkupné vezmou a balíček nevrátí.","result":"bad"}],"orig":"B","text":"Pomoz jí vyjednat vrácení balíčku (nebo ji přesvědč, ať ti dovolí letět s ní jako „spolupracovník“)."},"magie":{"mode":"dice","success":"Balíček ukradl žárlivý kurýr. Podstrčil jsi mu falešnou zprávu a balíček je zpět.","fail":"Tvůj plán se prozradil a kurýr uletěl i s balíčkem.","orig":"C","text":"Zjisti, kdo balíček ukradl a proč, a vymysli chytrý plán, jak ho získat bez boje."}},"image":"assets/npc/n124.webp","source_file":"grok_image_1777276873978.jpg"},{"id":125,"name":"Zkorumpovaný královský rádce","title":"","is_boss":false,"story":"„Král je slabý a sentimentální. Já však vidím, co je třeba udělat pro zachování moci. Potřebuji někoho... diskrétního, kdo dokáže zařídit věci, které by královská ruka nikdy neposkvrnila.“","choices":{"boj":{"mode":"choice","options":[{"label":"Šlechtice zabít","outcome":"Rádce platí a usmívá se. Tvé ruce jsou od krve a na dvoře se šeptá.","result":"good","karma":-1},{"label":"Šlechtice varovat","outcome":"Šlechtic uprchne a odmění tě. Rádce si tě zapíše na svůj seznam.","result":"neutral","karma":1}],"orig":"A","text":"Odstraň (zabij) nepohodlného šlechtice, který se staví proti rádci."},"charisma":{"mode":"dice","success":"Pomluvy zabraly. Soupeři rádce jsou zničeni a on platí.","fail":"Pomluvy se obrátily proti tobě. Dvůr tě má za lháře.","karma":-1,"orig":"B","text":"Šiř pomluvy a dezinformace mezi dvořany, aby se rádce zbavil svých soupeřů."},"magie":{"mode":"choice","options":[{"label":"Podvrhnout důkazy proti nevinnému","outcome":"Nevinný rádce je popraven. Dostal jsi zlato… a těžké svědomí.","result":"good","karma":-1},{"label":"Podvrhnout důkazy proti samotnému zkorumpovanému rádci","outcome":"Zkorumpovaný rádce je zatčen! Král ti děkuje.","result":"good","karma":1}],"orig":"C","text":"Vymysli a proveď rafinovaný plán, jak obvinit nevinného rádce z velezrady a nechat ho popravit."}},"image":"assets/npc/n125.webp","source_file":"grok_image_1777131267778.jpg"},{"id":126,"name":"Zlatosláva Hrdina","title":"Legendární válečník a obránce města","is_boss":false,"story":"„Jsem Zlatosláva! Město je v obležení a nepřátelé se blíží. Potřebuji silné muže a ženy, kteří se nebojí bojovat za své domovy. Přidej se ke mně, nebo nám aspoň pomoz naverbovat další bojovníky!“","choices":{"boj":{"mode":"dice","success":"Útok na hradby je odražen! Zlatosláva tě před celým městem nazve hrdinou.","fail":"Nepřítel tě srazil z hradeb do příkopu.","karma":1,"orig":"A","text":"Přidej se přímo ke Zlatoslávě do první linie a pomoz odrazit útok nepřátelské armády na městské hradby.","quest":{"targets":["city"],"goal":"Braň se Zlatoslávou městské hradby","gp":false}},"charisma":{"mode":"choice","options":[{"label":"Verbovat v hospodách s rundou pro všechny","outcome":"Polovina hospody se přihlásí k obraně. Zlatosláva ti platí.","result":"good"},{"label":"Verbovat na tržišti výhrůžkami","outcome":"Trhovci tě zasypou zeleninou. Nikdo se nepřidá.","result":"bad"}],"orig":"B","text":"Pomoz Zlatoslávě naverbovat nové vojáky v hospodách, na tržišti a mezi vesničany (přesvědčování, sliby, výzvy k hrdinství)."},"magie":{"mode":"dice","success":"Tvá past v soutěsce rozdělila nepřítele. Město je zachráněno!","fail":"Tvůj plán nepřítel prohlédl. Ztráty byly těžké.","orig":"C","text":"Vymysli chytrou strategii obrany města – najdi slabá místa nepřítele, navrhni past nebo způsob, jak nepřítele rozdělit a porazit po částech."}},"image":"assets/npc/n126.webp","source_file":"grok_image_1777111383136.jpg"},{"id":127,"name":"Čaroděj Křup a Kamenný Golem","title":"Čaroděj Křup a Kamenný Golem","is_boss":false,"story":"(Čaroděj Křup běží a hystericky křičí)\nKřup: „Nějak se vymknul kontrole kamínek!!! ZDRHEEEEJ!!!!\nŘíkal jsem mu ‚stůj‘, ale on si to vyložil jako ‚znič všechno‘!!!“\n(Golem za ním dunivě dupá a řve hlubokým hlasem)\nGolem: „...KRUUUP... VRÁT... SE...“","choices":{"boj":{"mode":"dice","success":"Golem se rozpadl na kamínky. Křup ti přísahá věčnou vděčnost a zlato.","fail":"Golem tě zašlápl do dlažby. Jen trochu.","orig":"A","text":"Zastav golema a rozbij ho na kusy, než zničí půl města."},"charisma":{"mode":"choice","options":[{"label":"Uklidnit golema ukolébavkou","outcome":"Golem zívne, sedne si a usne. Křup jásá a platí.","result":"good"},{"label":"Poslat Křupa pryč a čelit golemovi sám","outcome":"Golem hledá Křupa a ty mu stojíš v cestě. Bum.","result":"bad"}],"orig":"B","text":"Pomoz Křupovi golema uklidnit (nebo ho přesvědč, ať uteče a nechá golema tobě)."},"magie":{"mode":"dice","success":"Křup řekl „Znič vše“ místo „Zůstaň v klidu“. Opravil jsi rozkaz a golem se zastavil.","fail":"Opravil jsi rozkaz na „Uhoď dvakrát“. Golem poslechl.","orig":"C","text":"Zjisti, jaký příkaz Křup špatně vyslovil a oprav golemovi rozkaz, aby se uklidnil."}},"image":"assets/npc/n127.webp","source_file":"grok_image_1777245516994.jpg"},{"id":128,"name":"Šeptun","title":"Stínový assassin","is_boss":false,"story":"(tiše, skoro šeptem)\n„...mluvíš nahlas. To je chyba. Mám pro tebe práci. Jeden kupec ve městě má příliš dlouhý jazyk. Chci, aby zmlkl. Navždy.“","choices":{"boj":{"mode":"choice","options":[{"label":"Kupce zabít","outcome":"Šeptun zaplatí v tichosti. Ty víš, co jsi udělal.","result":"good","karma":-1},{"label":"Kupce varovat a pomoci mu uprchnout","outcome":"Kupec ti dá odměnu. Šeptun ti od té doby šeptá ve snech.","result":"neutral","karma":1}],"orig":"A","text":"Zabij kupce a jeho stráže."},"charisma":{"mode":"dice","success":"Kupec pochopil a zmlkl. Nikdo nemusel zemřít a Šeptun platí polovinu.","fail":"Kupec křičel ještě hlasitěji. Šeptun tě odměnil studeným pohledem a kopancem.","orig":"B","text":"Přesvědč kupce, ať mlčí (nebo ho zastraš)."},"magie":{"mode":"dice","success":"Šeptuna najal kupcův bratr. Obrátil jsi ho proti němu a oba ti platí za mlčení.","fail":"Šeptun tvé pátrání odhalil. Byl jsi rád, že jsi vyvázl.","orig":"C","text":"Zjisti, kdo si Šeptuna najal a jestli ho můžeš obrátit proti němu."}},"image":"assets/npc/n128.webp","source_file":"grok_image_1777246913326.jpg"},{"id":129,"name":"Šupinák Bublavý","title":"Rybo-humanoid (vodní lid)","is_boss":false,"story":"„Ty být hrdina? Já rád! Povídat příběhy! Bububub!“","choices":{"boj":{"mode":"dice","success":"Velká štika je mrtvá. Šupinák tančí a dává ti perlu.","fail":"Štika tě kousla do nohy a stáhla pod vodu.","karma":1,"orig":"A","text":"„Velký štika požírat rybáře. Ty zabít velkou štiku.“"},"charisma":{"mode":"choice","options":[{"label":"Naučit Šupináka zpívat bublinkovou serenádu","outcome":"Rybí holka je okouzlena. Šupinák ti daruje mušli plnou zlata.","result":"good"},{"label":"Poradit mu, ať jí přinese červa","outcome":"Rybí holka červa sní a odpluje. Šupinák pláče bublinky.","result":"bad"}],"orig":"B","text":"„Já chtít najít hezkou rybí holku. Ty mi pomoct mluvit s ní.“"},"magie":{"mode":"dice","success":"Našel jsi vstup do potopeného chrámu a v něm truhlu.","fail":"Ztratil ses v podvodních chodbách a málem ses utopil.","orig":"C","text":"„Starý potopený chrám pod vodou. Ty pomoct mi najít cestu dovnitř.“","quest":{"targets":["jezero_dusi"],"goal":"Najdi cestu do potopeného chrámu","gp":false}}},"image":"assets/npc/n129.webp","source_file":"grok_image_1777023578676.jpg"},{"id":130,"name":"Žebrák Eman","title":"Toulavý žebrák s nožem","is_boss":false,"story":"„Joooo, žebrák toulavý ten se máááá… občas někoho pobodááá!“","choices":{"boj":{"mode":"dice","success":"Emana jsi odzbrojil a on se rozplakal. Prý to byla jen písnička.","fail":"Eman tě pobodal do ruky a zmizel i s tvým měšcem.","orig":"A","text":"Eman tasí nůž a zaútočí s křikem „To je loupež století!“"},"charisma":{"mode":"choice","options":[{"label":"Dát mu pár mincí za písničku","outcome":"Eman zazpívá tak falešně, že se ti chce brečet. Ale nechá tě být a dá ti tip na poklad.","result":"good"},{"label":"Odmítnout a jít dál","outcome":"Eman tasí nůž a zaútočí! Odrazíš ho, ale škrábl tě.","result":"bad"}],"orig":"B","text":"Přesvědč ho, ať tě nechá na pokoji, nebo mu dej pár mincí za „speciální písničku“."},"magie":{"mode":"dice","success":"„Šťastný“ hadr byl u studny. Eman se rozzáří a nůž schová.","fail":"Hadr jsi nenašel – Eman tasí nůž a zaútočí!","orig":"C","text":"Zjisti, proč je agresivní (ukradli mu „šťastný“ hadr) a pomoz mu ho najít."}},"image":"assets/npc/n130.webp","source_file":"grok_image_1777095400473.jpg","special":"Nesplníš-li úkol, Eman tasí nůž a zaútočí (−1 život navíc).","onfail_extra_dmg":1}];
